-- >>> supabase/schemas/05_geo/040_place_search.sql
-- Geo · place search
--
-- One search over the places a ride can start, end or meet at that are picked by name:
-- cities and road junctions (D71). Streets are not searched here; they are picked inside a
-- chosen city, straight from public.streets. A function rather than two table reads because
-- the picker needs one ranked list across both catalogs with plain latitude / longitude,
-- which a table read of a geography column does not give.

-- Returns at most p_limit places whose Hebrew or English name contains p_query, names that
-- start with it first. Runs with the caller's rights: the tables' own policies apply.
-- junction_kind tells a junction from an interchange so the client can word the label.
create function public.search_places(
  p_query text,
  p_kinds text[] default array['city', 'junction'],
  p_limit integer default 20
)
returns table (
  place_kind    text,
  place_id      text,
  name_he       text,
  name_en       text,
  junction_kind text,
  roads         text,
  city_id       text,
  lat           double precision,
  lng           double precision
)
language plpgsql
stable
set search_path = ''
as $$
declare
  v_query   text := btrim(coalesce(p_query, ''));
  v_pattern text;
begin
  if char_length(v_query) not between 1 and 80 then
    raise exception 'place_query_invalid' using errcode = '22023';
  end if;
  if p_kinds is null or cardinality(p_kinds) = 0 or not (p_kinds <@ array['city', 'junction']) then
    raise exception 'place_kinds_invalid' using errcode = '22023';
  end if;
  if p_limit is null or p_limit not between 1 and 50 then
    raise exception 'place_limit_invalid' using errcode = '22023';
  end if;

  -- The query is matched literally: pattern characters typed by the member are escaped.
  v_pattern := '%' || replace(replace(replace(v_query, '\', '\\'), '%', '\%'), '_', '\_') || '%';

  return query
  select p.place_kind, p.place_id, p.name_he, p.name_en, p.junction_kind, p.roads, p.city_id,
         extensions.st_y(p.location::extensions.geometry),
         extensions.st_x(p.location::extensions.geometry)
    from (
      -- A city without a centre cannot be placed on a route, so it is not a ride place.
      select 'city'::text as place_kind, c.city_id as place_id, c.name_he, c.name_en,
             null::text as junction_kind, null::text as roads, c.city_id, c.location
        from public.cities c
       where 'city' = any (p_kinds)
         and c.location is not null
         and (c.name_he ilike v_pattern or lower(c.name_en) like lower(v_pattern))
      union all
      select 'junction', j.junction_id::text, j.name_he, j.name_en, j.kind, j.roads, null, j.location
        from public.road_junctions j
       where 'junction' = any (p_kinds)
         and (j.name_he ilike v_pattern or lower(j.name_en) like lower(v_pattern))
    ) p
   -- Total order, so equal names always come back in the same sequence.
   order by (p.name_he ilike substr(v_pattern, 2) or lower(p.name_en) like lower(substr(v_pattern, 2))) desc,
            p.name_he, p.place_kind, p.place_id
   limit p_limit;
end;
$$;
comment on function public.search_places(text, text[], integer) is
  'Place picker search over cities and road junctions (D71): at most 50 rows, names starting with the query first.';

grant execute on function public.search_places(text, text[], integer) to authenticated;

-- >>> supabase/schemas/10_identity/010_users.sql
-- Identity · users (public profile)
--
-- One row per member, holding only what other members may see. Private fields, account state
-- and counters live in their own 1:1 tables (user_private, user_account, user_stats), so a
-- row another member can select never contains anything private.

create table public.users (
  -- Same id as the auth account; removing the auth account removes the member.
  id                 uuid primary key references auth.users (id) on delete cascade,
  -- Public, shareable identifier used in profile links.
  share_handle       text not null unique check (share_handle ~ '^[a-z0-9_]{3,30}$'),
  -- Empty until the member completes the first onboarding step.
  display_name       text check (char_length(display_name) between 1 and 50),
  -- Free text; links are rejected so the profile cannot be used for advertising.
  biography          text check (
                       char_length(biography) <= 200
                       and biography !~* '(https?://|www\.|[\w.-]+\.[a-z]{2,})'),
  avatar_url         text,
  city_id            text references public.cities (city_id),
  -- 'Private' hides the member's posts and follower lists from non-followers.
  privacy_mode       text not null default 'Public' check (privacy_mode in ('Public', 'Private')),
  privacy_changed_at timestamptz,
  -- 0 none · 1 phone · 2 identity document · 3 verified badge.
  verification_level smallint not null default 0 check (verification_level between 0 and 3),
  -- BCP 47 tag of the member's interface language.
  preferred_language text check (char_length(preferred_language) between 2 and 35),
  -- Mirror of user_account.status = 'active', maintained by trigger. Kept on this row so the
  -- visibility policy is a plain column test rather than a join on every profile read.
  is_active          boolean not null default false,
  -- Search document over name and handle; `simple` keeps Hebrew tokens unstemmed.
  search_vector      tsvector generated always as (
                       to_tsvector('simple', coalesce(display_name, '') || ' ' || share_handle)) stored,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
comment on table public.users is 'Public profile of a member. Contains nothing private.';

-- Member search: whole-word match, then substring match on the display name.
create index users_search_gin_idx on public.users using gin (search_vector) where is_active;
create index users_display_name_trgm_idx on public.users
  using gin (display_name extensions.gin_trgm_ops) where is_active;
-- City filter in member search and city statistics.
create index users_city_idx on public.users (city_id) where is_active;

create trigger users_set_updated_at
  before update on public.users
  for each row execute function kc_private.set_updated_at();

alter table public.users enable row level security;
alter table public.users force row level security;

-- A member sees active profiles, and always their own (whatever its account state).
create policy users_select_active_or_self on public.users
  for select to authenticated
  using (is_active or id = (select auth.uid()));

-- A member edits their own profile; which columns is decided by the grant below.
create policy users_update_self on public.users
  for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

grant select on public.users to authenticated;
-- Handle, privacy mode, verification level and is_active change only through server code.
grant update (display_name, biography, avatar_url, city_id, preferred_language)
  on public.users to authenticated;

-- >>> supabase/schemas/10_identity/020_user_private.sql
-- Identity · user_private (owner-only data)
--
-- Personal details and preferences that only the member may read. Kept out of `users` so
-- that no policy mistake on the public profile can ever expose them.

create table public.user_private (
  user_id                     uuid primary key references public.users (id) on delete cascade,
  -- Contact number shown to a counterparty only through a dedicated RPC.
  contact_phone               text check (char_length(btrim(contact_phone)) between 1 and 20),
  -- Used for the 18+ rule and age-restricted worlds; written only through set_date_of_birth.
  date_of_birth               date,
  -- Default pickup address, prefilled into new posts. Both parts or neither.
  profile_street              text check (char_length(profile_street) between 1 and 80),
  -- Digits with an optional entrance letter, Latin or Hebrew (U+05D0–U+05EA, written as
  -- escapes because Hebrew text is allowed only in locale files).
  profile_street_number       text check (profile_street_number ~ '^[0-9]+[A-Za-z\u05D0-\u05EA]?$'),
  -- Per-category push settings and quiet hours.
  notification_preferences    jsonb not null default '{}'::jsonb
                                check (jsonb_typeof(notification_preferences) = 'object'),
  -- Whether other members see the "active recently" indicator.
  show_active_status          boolean not null default true,
  -- One-time explainer and nudge dismissals.
  closure_explainer_dismissed boolean not null default false,
  first_post_nudge_dismissed  boolean not null default false,
  -- The member chose to fill in basic details later.
  basic_info_skipped          boolean not null default false,
  updated_at                  timestamptz not null default now(),
  constraint user_private_address_pair_chk
    check ((profile_street is null) = (profile_street_number is null))
);
comment on table public.user_private is 'Personal details and preferences readable only by their owner.';

create trigger user_private_set_updated_at
  before update on public.user_private
  for each row execute function kc_private.set_updated_at();

alter table public.user_private enable row level security;
alter table public.user_private force row level security;

create policy user_private_select_self on public.user_private
  for select to authenticated
  using (user_id = (select auth.uid()));

create policy user_private_update_self on public.user_private
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

grant select on public.user_private to authenticated;
-- date_of_birth is excluded: it is written only by set_date_of_birth, which enforces 18+.
grant update (
  contact_phone, profile_street, profile_street_number, notification_preferences,
  show_active_status, closure_explainer_dismissed, first_post_nudge_dismissed, basic_info_skipped
) on public.user_private to authenticated;

-- >>> supabase/schemas/10_identity/030_user_account.sql
-- Identity · user_account (server-written account state)
--
-- Account status, onboarding progress, sanctions and the 30-day deletion grace period.
-- The member may read their own row; nothing here is writable from a device.

insert into kc_private.fsm_state (machine_id, status) values
  ('account_status', 'pending_verification'),
  ('account_status', 'active'),
  ('account_status', 'suspended_for_false_reports'),
  ('account_status', 'suspended_admin'),
  ('account_status', 'banned'),
  ('account_status', 'pending_deletion'),
  ('onboarding', 'pending_basic_info'),
  ('onboarding', 'pending_avatar'),
  ('onboarding', 'completed');

insert into kc_private.fsm_edge (machine_id, from_status, to_status) values
  ('account_status', 'pending_verification', 'active'),
  ('account_status', 'pending_verification', 'suspended_for_false_reports'),
  ('account_status', 'pending_verification', 'suspended_admin'),
  ('account_status', 'pending_verification', 'banned'),
  ('account_status', 'pending_verification', 'pending_deletion'),
  ('account_status', 'active', 'suspended_for_false_reports'),
  ('account_status', 'active', 'suspended_admin'),
  ('account_status', 'active', 'banned'),
  ('account_status', 'active', 'pending_deletion'),
  ('account_status', 'suspended_for_false_reports', 'active'),
  ('account_status', 'suspended_for_false_reports', 'suspended_admin'),
  ('account_status', 'suspended_for_false_reports', 'banned'),
  ('account_status', 'suspended_admin', 'active'),
  ('account_status', 'suspended_admin', 'banned'),
  ('account_status', 'banned', 'active'),
  -- Restoring within the grace period returns to the status held before the request.
  ('account_status', 'pending_deletion', 'active'),
  ('account_status', 'pending_deletion', 'pending_verification'),
  ('onboarding', 'pending_basic_info', 'pending_avatar'),
  -- Deferred basic details (FR-AUTH-015): the member skipped the avatar step.
  ('onboarding', 'pending_basic_info', 'completed'),
  ('onboarding', 'pending_avatar', 'completed');

create table public.user_account (
  user_id                     uuid primary key references public.users (id) on delete cascade,
  status                      text not null default 'pending_verification',
  -- End of a temporary suspension; null for every other status.
  status_until                timestamptz,
  onboarding_state            text not null default 'pending_basic_info',
  -- Moderation counters behind the false-report sanction ladder.
  false_reports_count         integer not null default 0 check (false_reports_count >= 0),
  false_report_sanction_count smallint not null default 0 check (false_report_sanction_count between 0 and 3),
  -- A member barred from the food world cannot post there until this time.
  food_posting_banned_until   timestamptz,
  verified_at                 timestamptz,
  verification_method         text check (verification_method in ('manual', 'document', 'provider', 'org_vouch')),
  -- Account deletion: requested → hidden at once → purged after the grace period.
  deletion_requested_at       timestamptz,
  deletion_purge_at           timestamptz,
  status_before_deletion      text check (status_before_deletion in ('active', 'pending_verification')),
  updated_at                  timestamptz not null default now(),
  -- A purge date exists exactly while the account is pending deletion.
  constraint user_account_pending_deletion_chk
    check ((status = 'pending_deletion') = (deletion_purge_at is not null)),
  constraint user_account_deletion_fields_chk
    check ((deletion_purge_at is null) = (deletion_requested_at is null)
       and (deletion_purge_at is null) = (status_before_deletion is null))
);
comment on table public.user_account is 'Account status, onboarding and deletion state. Written only by server code.';

-- Daily purge job: accounts whose grace period has ended.
create index user_account_purge_due_idx on public.user_account (deletion_purge_at)
  where deletion_purge_at is not null;
-- Daily job that lifts expired suspensions.
create index user_account_status_until_idx on public.user_account (status_until)
  where status_until is not null;

create trigger user_account_status_fsm
  before insert or update of status on public.user_account
  for each row execute function kc_private.fsm_guard_status('account_status', 'status');

create trigger user_account_onboarding_fsm
  before insert or update of onboarding_state on public.user_account
  for each row execute function kc_private.fsm_guard_status('onboarding', 'onboarding_state');

create trigger user_account_set_updated_at
  before update on public.user_account
  for each row execute function kc_private.set_updated_at();

-- Keeps users.is_active equal to (status = 'active'), so profile visibility follows the
-- account state in the same transaction that changes it.
create function kc_private.user_account_sync_is_active()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.users u
     set is_active = (new.status = 'active')
   where u.id = new.user_id
     and u.is_active is distinct from (new.status = 'active');
  return null;
end;
$$;

create trigger user_account_sync_is_active
  after insert or update of status on public.user_account
  for each row execute function kc_private.user_account_sync_is_active();

alter table public.user_account enable row level security;
alter table public.user_account force row level security;

create policy user_account_select_self on public.user_account
  for select to authenticated
  using (user_id = (select auth.uid()));

grant select on public.user_account to authenticated;

-- >>> supabase/schemas/10_identity/040_user_stats.sql
-- Identity · user_stats (denormalized counters)
--
-- Counters shown on a profile. They live apart from `users` so that a follow, a reaction or a
-- new post never rewrites the profile row. Maintained by triggers in the modules that own the
-- counted rows; a nightly job recomputes them and records any drift.

create table public.user_stats (
  user_id                    uuid primary key references public.users (id) on delete cascade,
  followers_count            integer not null default 0 check (followers_count >= 0),
  following_count            integer not null default 0 check (following_count >= 0),
  items_given_count          integer not null default 0 check (items_given_count >= 0),
  items_received_count       integer not null default 0 check (items_received_count >= 0),
  -- Open posts by visibility: a viewer is shown the sum they are allowed to see.
  open_posts_public          integer not null default 0 check (open_posts_public >= 0),
  open_posts_followers_only  integer not null default 0 check (open_posts_followers_only >= 0),
  open_posts_only_me         integer not null default 0 check (open_posts_only_me >= 0),
  posts_created_total        integer not null default 0 check (posts_created_total >= 0),
  karma_points               integer not null default 0 check (karma_points >= 0),
  volunteer_hours_total      numeric(10, 2) not null default 0 check (volunteer_hours_total >= 0),
  updated_at                 timestamptz not null default now()
);
comment on table public.user_stats is 'Profile counters, maintained by triggers and reconciled nightly.';

create trigger user_stats_set_updated_at
  before update on public.user_stats
  for each row execute function kc_private.set_updated_at();

alter table public.user_stats enable row level security;
alter table public.user_stats force row level security;

-- Counters are visible exactly when the profile is: the subquery runs under the caller's
-- own access to `users`, so it inherits that table's policy.
create policy user_stats_select_visible_profile on public.user_stats
  for select to authenticated
  using (exists (select 1 from public.users u where u.id = user_stats.user_id));

-- Column grant: the private "only me" count is left out; its owner reads it through an RPC.
grant select (
  user_id, followers_count, following_count, items_given_count, items_received_count,
  open_posts_public, open_posts_followers_only, posts_created_total, karma_points,
  volunteer_hours_total, updated_at
) on public.user_stats to authenticated;

-- >>> supabase/schemas/10_identity/050_auth_user_triggers.sql
-- Identity · auth account → member rows
--
-- The auth service owns sign-up. These triggers on `auth.users` create the member's four rows
-- in the same transaction as the auth account, and activate the member once a contact
-- channel is confirmed. They are SECURITY DEFINER because the auth service's role has no
-- access to the product tables.

-- True when the auth account has proven a contact channel: Google and Apple accounts are
-- verified by the provider; email and phone accounts once their confirmation arrived.
create function kc_private.auth_user_is_verified(p_auth_user auth.users)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select coalesce(p_auth_user.raw_app_meta_data ->> 'provider', 'email') in ('google', 'apple')
      or p_auth_user.email_confirmed_at is not null
      or p_auth_user.phone_confirmed_at is not null;
$$;

-- Returns a share handle no member holds yet: `u_` plus 12 random hex characters. The
-- handle is random rather than derived from the account id, because a prefix of the id is
-- not unique at scale and a collision would fail the sign-up.
create function kc_private.generate_share_handle()
returns text
language plpgsql
volatile
set search_path = ''
as $$
declare
  v_handle text;
begin
  loop
    v_handle := 'u_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12);
    exit when not exists (select 1 from public.users u where u.share_handle = v_handle);
  end loop;
  return v_handle;
end;
$$;

-- Creates the profile, private, account and counter rows of a new member.
create function kc_private.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_meta constant jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  -- Name offered by the identity provider, else the local part of the email address.
  v_display_name constant text := left(
    coalesce(
      nullif(btrim(coalesce(v_meta ->> 'full_name', v_meta ->> 'name')), ''),
      nullif(split_part(coalesce(new.email, ''), '@', 1), '')),
    50);
begin
  insert into public.users (id, share_handle, display_name, avatar_url)
  values (
    new.id,
    kc_private.generate_share_handle(),
    v_display_name,
    nullif(coalesce(v_meta ->> 'avatar_url', v_meta ->> 'picture'), ''));

  insert into public.user_private (user_id) values (new.id);
  insert into public.user_stats (user_id) values (new.id);
  insert into public.user_account (user_id, status)
  values (
    new.id,
    case when kc_private.auth_user_is_verified(new) then 'active' else 'pending_verification' end);

  return new;
end;
$$;
comment on function kc_private.handle_new_auth_user() is
  'AFTER INSERT on auth.users: creates the member rows; verified accounts start active.';

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function kc_private.handle_new_auth_user();

-- Activates a member waiting for verification when their email or phone is confirmed.
-- Any other status is left alone: a suspension or a deletion request outranks verification.
create function kc_private.handle_auth_user_verified()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if kc_private.auth_user_is_verified(new) then
    update public.user_account a
       set status = 'active'
     where a.user_id = new.id
       and a.status = 'pending_verification';
  end if;
  return new;
end;
$$;
comment on function kc_private.handle_auth_user_verified() is
  'AFTER UPDATE on auth.users: pending_verification → active once a contact channel is confirmed.';

create trigger on_auth_user_verified
  after update of email_confirmed_at, phone_confirmed_at on auth.users
  for each row execute function kc_private.handle_auth_user_verified();

-- >>> supabase/schemas/10_identity/060_user_devices.sql
-- Identity · user_devices (push tokens, FR-NOTIF-015)
--
-- One row per device a member receives push notifications on. The member registers the
-- token at sign-in, refreshes `last_seen_at` on every app start and deletes the row at
-- sign-out; server code deletes it when the push provider reports the token as dead, when
-- the account is deactivated (FR-SETTINGS-012 AC2) and after 90 days without use.

create table public.user_devices (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.users (id) on delete cascade,
  platform     text not null check (platform in ('ios', 'android', 'web')),
  -- Provider token. Unique: one physical device delivers to one member at a time.
  push_token   text not null unique check (char_length(push_token) between 1 and 4096),
  -- Last app start on this device; drives the 90-day prune (FR-NOTIF-015 AC4).
  last_seen_at timestamptz not null default now(),
  created_at   timestamptz not null default now()
);
comment on table public.user_devices is 'Push tokens of a member''s devices. Owner-only.';

-- Notification dispatch: every token of the recipient.
create index user_devices_user_idx on public.user_devices (user_id);
-- Daily prune job: tokens not seen for 90 days.
create index user_devices_last_seen_idx on public.user_devices (last_seen_at);

alter table public.user_devices enable row level security;
alter table public.user_devices force row level security;

create policy user_devices_select_self on public.user_devices
  for select to authenticated
  using (user_id = (select auth.uid()));

create policy user_devices_insert_self on public.user_devices
  for insert to authenticated
  with check (user_id = (select auth.uid()));

-- Refreshing a registration (upsert on the token) may only touch the caller's own row.
create policy user_devices_update_self on public.user_devices
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create policy user_devices_delete_self on public.user_devices
  for delete to authenticated
  using (user_id = (select auth.uid()));

grant select, insert, delete on public.user_devices to authenticated;
-- The columns an upsert on `push_token` rewrites; `id` and `created_at` never change.
grant update (user_id, platform, push_token, last_seen_at) on public.user_devices to authenticated;

-- >>> supabase/schemas/10_identity/070_legal_documents.sql
-- Identity · legal documents (FR-SETTINGS-010)
--
-- Terms of service and privacy policy are published from the server. `legal_documents` is
-- the current pointer of each document; `legal_document_versions` is the immutable history
-- a member's consent refers to. Both are written only by the admin publishing RPC.

create table public.legal_documents (
  id                     uuid primary key default gen_random_uuid(),
  doc_type               text not null unique check (doc_type in ('terms', 'privacy')),
  -- 0 until the first version is published.
  current_version        integer not null default 0 check (current_version >= 0),
  current_effective_date timestamptz not null,
  -- Newest version a member must have accepted: minor edits do not raise it.
  last_material_version  integer not null default 0,
  last_material_severity text check (last_material_severity in ('standard', 'critical')),
  updated_at             timestamptz not null default now(),
  constraint legal_documents_material_version_chk
    check (last_material_version between 0 and current_version)
);
comment on table public.legal_documents is 'Current version pointer of each legal document.';

create trigger legal_documents_set_updated_at
  before update on public.legal_documents
  for each row execute function kc_private.set_updated_at();

create table public.legal_document_versions (
  id             uuid primary key default gen_random_uuid(),
  doc_type       text not null references public.legal_documents (doc_type),
  version        integer not null check (version >= 1),
  -- BCP 47 tag of the text.
  language       text not null default 'he' check (char_length(language) between 2 and 35),
  -- A version published ahead of time is shown, but asks for consent only from this date.
  effective_date timestamptz not null,
  body_md        text not null check (char_length(body_md) > 0),
  -- SHA-256 of body_md, set by trigger: proves which text a consent referred to.
  content_hash   text not null,
  -- minor: no consent needed · standard: 7 days of notice · critical: blocks at once.
  severity       text not null check (severity in ('minor', 'standard', 'critical')),
  change_summary text,
  -- The publishing admin; null once that account has been removed.
  published_by   uuid references public.users (id) on delete set null,
  published_at   timestamptz not null default now(),
  -- Also serves the foreign key on doc_type and "newest version of a document".
  constraint legal_document_versions_doc_version_key unique (doc_type, version),
  constraint legal_document_versions_summary_chk
    check (severity = 'minor' or char_length(btrim(change_summary)) > 0)
);
comment on table public.legal_document_versions is 'Immutable history of published legal texts.';

-- Foreign key lookup when a publisher's account is removed.
create index legal_document_versions_published_by_idx
  on public.legal_document_versions (published_by) where published_by is not null;

-- Stamps the content hash, so it never depends on what the publisher sent.
create function kc_private.legal_document_versions_set_hash()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.content_hash := encode(sha256(convert_to(new.body_md, 'UTF8')), 'hex');
  return new;
end;
$$;

create trigger legal_document_versions_set_hash
  before insert on public.legal_document_versions
  for each row execute function kc_private.legal_document_versions_set_hash();

-- A published version never changes and is never removed. The single exception is the
-- foreign key clearing `published_by` when the publisher's account is removed.
create function kc_private.legal_document_versions_immutable()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' and new.published_by is null
     and to_jsonb(new) - 'published_by' = to_jsonb(old) - 'published_by' then
    return new;
  end if;
  raise exception 'append_only' using errcode = 'P0001', detail = 'legal_document_versions';
end;
$$;

create trigger legal_document_versions_immutable
  before update or delete on public.legal_document_versions
  for each row execute function kc_private.legal_document_versions_immutable();

alter table public.legal_documents enable row level security;
alter table public.legal_documents force row level security;
alter table public.legal_document_versions enable row level security;
alter table public.legal_document_versions force row level security;

-- Published legal text is public: the sign-up screen shows the terms and the privacy policy
-- before an account exists (FR-AUTH-002 AC3; PM decision 2026-11-10). This is the only
-- product table a signed-out caller can read.
create policy legal_documents_select_anyone on public.legal_documents
  for select to anon, authenticated
  using (true);

create policy legal_document_versions_select_anyone on public.legal_document_versions
  for select to anon, authenticated
  using (true);

grant select on public.legal_documents to anon, authenticated;
grant select on public.legal_document_versions to anon, authenticated;

-- >>> supabase/schemas/10_identity/080_user_consents.sql
-- Identity · user_consents
--
-- One append-only record of everything a member agreed to: the legal documents, the driver
-- declaration of the rides world and the code of conduct of the housing world. A row is the
-- evidence of a consent, so it is never changed and leaves only together with its member.

create table public.user_consents (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.users (id) on delete cascade,
  -- terms / privacy refer to legal_document_versions; the two world consents are versioned
  -- by the module that asks for them.
  consent_kind text not null
                 check (consent_kind in ('terms', 'privacy', 'driver_declaration', 'housing_conduct')),
  version      integer not null check (version >= 1),
  accepted_at  timestamptz not null default now(),
  -- Evidence of the circumstances of the consent; all three may be unknown.
  locale       text check (char_length(locale) between 2 and 35),
  ip_address   inet,
  user_agent   text check (char_length(user_agent) <= 500),
  -- A version is accepted once. Also serves "newest accepted version of a kind" for a
  -- member (session start, world gates) and the foreign key on user_id.
  constraint user_consents_user_kind_version_key unique (user_id, consent_kind, version)
);
comment on table public.user_consents is 'Append-only record of a member''s consents. Written only by server code.';

-- No update at all; a delete only as part of removing the member (the cascade runs after
-- the profile row is gone, a direct delete does not).
create function kc_private.user_consents_append_only()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' and not exists (select 1 from public.users u where u.id = old.user_id) then
    return old;
  end if;
  raise exception 'append_only' using errcode = 'P0001', detail = 'user_consents';
end;
$$;

create trigger user_consents_append_only
  before update or delete on public.user_consents
  for each row execute function kc_private.user_consents_append_only();

alter table public.user_consents enable row level security;
alter table public.user_consents force row level security;

create policy user_consents_select_self on public.user_consents
  for select to authenticated
  using (user_id = (select auth.uid()));

grant select on public.user_consents to authenticated;

-- The signed-in caller, for RPCs that act on the caller's own data.
create function kc_private.require_caller()
returns uuid
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user_id constant uuid := (select auth.uid());
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;
  return v_user_id;
end;
$$;
comment on function kc_private.require_caller() is 'Returns auth.uid(); raises unauthenticated without a session.';

-- Records one consent with its evidence and returns the stored row. Recording the same
-- version again keeps the first row. The world modules call this from their own RPCs after
-- checking the version they require.
create function kc_private.record_consent(
  p_user_id uuid, p_kind text, p_version integer, p_locale text, p_user_agent text)
returns public.user_consents
language plpgsql
set search_path = ''
as $$
declare
  -- The API gateway forwards the device address as the first hop of this header.
  v_forwarded constant text := btrim(split_part(
    nullif(current_setting('request.headers', true), '')::jsonb ->> 'x-forwarded-for', ',', 1));
  v_ip inet;
  v_row public.user_consents;
begin
  begin
    v_ip := coalesce(nullif(v_forwarded, '')::inet, inet_client_addr());
  exception when invalid_text_representation then
    v_ip := null;
  end;

  insert into public.user_consents (user_id, consent_kind, version, locale, ip_address, user_agent)
  values (p_user_id, p_kind, p_version, nullif(btrim(p_locale), ''), v_ip, left(p_user_agent, 500))
  on conflict (user_id, consent_kind, version) do nothing;

  select c.* into strict v_row
    from public.user_consents c
   where c.user_id = p_user_id and c.consent_kind = p_kind and c.version = p_version;
  return v_row;
end;
$$;

-- The caller accepts a published version of a legal document (FR-AUTH-002 AC5,
-- FR-SETTINGS-010 AC3/AC4). Only a version that satisfies the consent gate is accepted:
-- from the last material version up to the current one.
create function public.accept_legal_document(
  p_doc_type text, p_version integer, p_locale text default null, p_user_agent text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_document public.legal_documents;
  v_consent public.user_consents;
begin
  select d.* into v_document from public.legal_documents d where d.doc_type = p_doc_type;
  if not found then
    raise exception 'unknown_legal_document' using errcode = 'P0001';
  end if;
  if p_version is null or p_version < greatest(v_document.last_material_version, 1)
     or p_version > v_document.current_version then
    raise exception 'legal_version_out_of_range' using errcode = 'P0001';
  end if;

  v_consent := kc_private.record_consent(v_user_id, p_doc_type, p_version, p_locale, p_user_agent);
  return jsonb_build_object('acceptance_id', v_consent.id, 'accepted_at', v_consent.accepted_at);
end;
$$;
comment on function public.accept_legal_document(text, integer, text, text) is
  'Records the caller''s consent to a published legal document version.';
grant execute on function public.accept_legal_document(text, integer, text, text) to authenticated;

-- >>> supabase/schemas/10_identity/090_account_rpcs.sql
-- Identity · account RPCs (onboarding, date of birth, account deletion)
--
-- `user_account` and `user_private.date_of_birth` are not writable from a device. These are
-- the named moves a member may make on their own account. Errors are raised with SQLSTATE
-- P0001 and a stable snake_case message the app maps to its error types.

-- ── Onboarding (FR-AUTH-010 AC5, FR-AUTH-015) ───────────────────────────────
-- Moves the caller's onboarding forward. Leaving step 1 requires a display name, a city and
-- a date of birth on file, so a modified client cannot skip the step.
create function public.set_onboarding_state(p_state text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_current text;
begin
  select a.onboarding_state into v_current
    from public.user_account a where a.user_id = v_user_id for update;
  if not found then
    raise exception 'user_not_found' using errcode = 'P0001';
  end if;

  if v_current = 'pending_basic_info' and p_state is distinct from v_current and not exists (
       select 1
         from public.users u
         join public.user_private p on p.user_id = u.id
        where u.id = v_user_id
          and nullif(btrim(u.display_name), '') is not null
          and u.city_id is not null
          and p.date_of_birth is not null) then
    raise exception 'onboarding_basic_info_missing' using errcode = 'P0001';
  end if;

  begin
    update public.user_account a set onboarding_state = p_state where a.user_id = v_user_id;
  exception when sqlstate 'P0001' then
    -- The machine refused the move (backwards, or not a state): one error for the app.
    raise exception 'onboarding_transition_invalid' using errcode = 'P0001', detail = sqlerrm;
  end;
end;
$$;
comment on function public.set_onboarding_state(text) is
  'Moves the caller''s onboarding along its machine; step 1 needs name, city and date of birth.';
grant execute on function public.set_onboarding_state(text) to authenticated;

-- ── Date of birth (FR-AUTH-010 AC2.d, FR-PROFILE-007 AC7, D109) ─────────────
-- Stores the caller's date of birth. The member must be at least 18 on the day of the call;
-- a later correction is held to the same rule.
create function public.set_date_of_birth(p_date date)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
begin
  if p_date is null or p_date > current_date or p_date < date '1900-01-01' then
    raise exception 'invalid_date_of_birth' using errcode = 'P0001';
  end if;
  if p_date > (current_date - interval '18 years')::date then
    raise exception 'underage' using errcode = 'P0001';
  end if;

  update public.user_private p set date_of_birth = p_date where p.user_id = v_user_id;
  if not found then
    raise exception 'user_not_found' using errcode = 'P0001';
  end if;
end;
$$;
comment on function public.set_date_of_birth(date) is 'Stores the caller''s date of birth; rejects anyone under 18.';
grant execute on function public.set_date_of_birth(date) to authenticated;

-- ── Account deletion: 30 days of grace (D108, FR-SETTINGS-012, FR-AUTH-016) ─
-- Whatever moves an account out of pending_deletion (a restore, or any later server move),
-- the deletion fields are cleared here, in one place, so no writer can leave them behind.
create function kc_private.user_account_leave_pending_deletion()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.deletion_requested_at := null;
  new.deletion_purge_at := null;
  new.status_before_deletion := null;
  return new;
end;
$$;

create trigger user_account_leave_pending_deletion
  before update of status on public.user_account
  for each row
  when (old.status = 'pending_deletion' and new.status <> 'pending_deletion')
  execute function kc_private.user_account_leave_pending_deletion();

-- Deactivates the caller's account and returns the purge date. The profile disappears for
-- everyone else at once (users.is_active), push stops, and nothing else is removed, so a
-- restore is complete. Calling it again returns the same date. A suspended or banned
-- member cannot use it to step out of a sanction.
create function public.request_account_deletion()
returns timestamptz
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_account public.user_account;
  v_purge_at constant timestamptz := now() + interval '30 days';
begin
  select a.* into v_account from public.user_account a where a.user_id = v_user_id for update;
  if not found then
    raise exception 'user_not_found' using errcode = 'P0001';
  end if;
  if v_account.status = 'pending_deletion' then
    return v_account.deletion_purge_at;
  end if;
  if v_account.status not in ('active', 'pending_verification') then
    raise exception 'suspended' using errcode = 'P0001';
  end if;

  update public.user_account a
     set status = 'pending_deletion',
         status_before_deletion = v_account.status,
         deletion_requested_at = now(),
         deletion_purge_at = v_purge_at
   where a.user_id = v_user_id;

  delete from public.user_devices d where d.user_id = v_user_id;
  return v_purge_at;
end;
$$;
comment on function public.request_account_deletion() is
  'Deactivates the caller''s account for 30 days and returns the purge date.';
grant execute on function public.request_account_deletion() to authenticated;

-- Restores the caller's account while the grace period is running. The account returns to
-- the status it had before, except that a member whose contact channel was confirmed in the
-- meantime returns as active.
create function public.restore_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_account public.user_account;
begin
  select a.* into v_account from public.user_account a where a.user_id = v_user_id for update;
  if not found or v_account.status <> 'pending_deletion' then
    raise exception 'not_pending_deletion' using errcode = 'P0001';
  end if;
  if v_account.deletion_purge_at <= now() then
    raise exception 'grace_expired' using errcode = 'P0001';
  end if;

  update public.user_account a
     set status = case
           when exists (select 1 from auth.users au
                         where au.id = v_user_id and kc_private.auth_user_is_verified(au)) then 'active'
           else v_account.status_before_deletion
         end
   where a.user_id = v_user_id;
end;
$$;
comment on function public.restore_account() is 'Restores the caller''s account during the deletion grace period.';
grant execute on function public.restore_account() to authenticated;

-- Accounts whose grace period has ended, oldest first, for the daily purge job. An account
-- stays listed until its auth identity is gone, so a failed purge is retried the next day.
create function kc_private.accounts_due_for_purge(p_limit integer default 100)
returns table (user_id uuid, deletion_purge_at timestamptz)
language sql
stable
set search_path = ''
as $$
  select a.user_id, a.deletion_purge_at
    from public.user_account a
   where a.deletion_purge_at <= now()
   order by a.deletion_purge_at
   limit p_limit;
$$;
comment on function kc_private.accounts_due_for_purge(integer) is
  'Service role only: accounts past their purge date, oldest first.';

-- >>> supabase/schemas/10_identity/100_bootstrap_session.sql
-- Identity · bootstrap_session (docs/db/target-design.md §5 "Session start")
--
-- Everything the app needs to decide what to show after sign-in, in one round trip: the
-- account gate, the caller's private profile and the legal consent prompt. Each later module
-- adds its own top-level key (unread counts, admin roles, survey prompts); existing keys
-- never change shape.
--
-- It runs with the caller's rights: every row it reads is one the caller may already select.

create function public.bootstrap_session()
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user_id constant uuid := (select auth.uid());
  v_result jsonb;
begin
  select jsonb_build_object(
           'user_id', a.user_id,
           -- Account gate: `status` other than active sends the app to the matching screen.
           'account', jsonb_build_object(
             'status', a.status,
             'status_until', a.status_until,
             'onboarding_state', a.onboarding_state,
             'deletion_requested_at', a.deletion_requested_at,
             'deletion_purge_at', a.deletion_purge_at),
           'private_profile', jsonb_build_object(
             'contact_phone', p.contact_phone,
             'date_of_birth', p.date_of_birth,
             'profile_street', p.profile_street,
             'profile_street_number', p.profile_street_number,
             'notification_preferences', p.notification_preferences,
             'show_active_status', p.show_active_status,
             'closure_explainer_dismissed', p.closure_explainer_dismissed,
             'first_post_nudge_dismissed', p.first_post_nudge_dismissed,
             'basic_info_skipped', p.basic_info_skipped),
           -- ↓ Added by the messaging and notifications modules: the two badges of the top bar
           -- (FR-CHAT-012, spec 07 §7.11). Both functions are created by those modules.
           'unread', jsonb_build_object(
             'chats', public.chat_unread_total(),
             'notifications', public.notifications_unread_count()),
           -- ↑ End of the messaging and notifications addition.
           -- >>> moderation module: staff roles of the caller (empty for an ordinary member).
           'admin', jsonb_build_object('roles', public.get_my_admin_roles()),
           -- <<< moderation module
           'legal', (
             -- Documents in force whose last material version the caller has not accepted.
             -- `modal` blocks the app; `banner` is the 7-day notice of a standard change,
             -- measured on the database clock (FR-SETTINGS-010 AC3, AC5).
             select jsonb_build_object(
                      'needs_reacknowledgement', count(*) > 0,
                      'blocking', coalesce(bool_or(o.block_mode = 'modal'), false),
                      'documents', coalesce(jsonb_agg(to_jsonb(o) order by o.doc_type), '[]'::jsonb))
               from (
                 select d.doc_type, d.current_version, d.current_effective_date,
                        d.last_material_version, d.last_material_severity,
                        coalesce(c.version, 0) as last_accepted_version,
                        case
                          when d.last_material_severity = 'critical'
                            or now() - d.current_effective_date >= interval '7 days' then 'modal'
                          else 'banner'
                        end as block_mode
                   from public.legal_documents d
                   left join lateral (
                     select max(uc.version) as version
                       from public.user_consents uc
                      where uc.user_id = a.user_id and uc.consent_kind = d.doc_type) c on true
                  where d.current_effective_date <= now()
                    and coalesce(c.version, 0) < d.last_material_version) o))
    into v_result
    from public.user_account a
    join public.user_private p on p.user_id = a.user_id
   where a.user_id = v_user_id;

  if v_result is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;
  return v_result;
end;
$$;
comment on function public.bootstrap_session() is
  'Session start in one call: account gate, private profile, unread badges, legal consent prompt.';
grant execute on function public.bootstrap_session() to authenticated;

-- >>> supabase/schemas/15_social_graph/010_follows.sql
-- Social graph · follows
--
-- One row per "follower follows followed". A private profile is followed through an approved
-- request, so an edge is created only by server code; removing an edge (unfollow, or removing
-- a follower) is a plain delete by either party (FR-FOLLOW-002, FR-FOLLOW-009).

create table public.follows (
  follower_id uuid not null references public.users (id) on delete cascade,
  followed_id uuid not null references public.users (id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (follower_id, followed_id),
  constraint follows_not_self_chk check (follower_id <> followed_id)
);
comment on table public.follows is 'Follow edges. Created by server code, deleted by either party.';

-- Followers list of a profile, newest first (keyset on created_at, follower_id).
create index follows_followed_recent_idx on public.follows (followed_id, created_at desc, follower_id);
-- Following list of a profile, newest first; also serves the feed's "people I follow" lookup.
create index follows_follower_recent_idx on public.follows (follower_id, created_at desc, followed_id);

-- Keeps the two profile counters in step with the edge, in the same transaction
-- (FR-FOLLOW-001 AC2). Runs with definer rights because counters are not client-writable.
create function kc_private.follows_sync_counters()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_delta constant integer := case tg_op when 'INSERT' then 1 else -1 end;
  v_edge constant public.follows := case tg_op when 'INSERT' then new else old end;
begin
  update public.user_stats s
     set followers_count = greatest(s.followers_count + v_delta, 0)
   where s.user_id = v_edge.followed_id;
  update public.user_stats s
     set following_count = greatest(s.following_count + v_delta, 0)
   where s.user_id = v_edge.follower_id;
  return null;
end;
$$;

create trigger follows_sync_counters
  after insert or delete on public.follows
  for each row execute function kc_private.follows_sync_counters();

alter table public.follows enable row level security;
alter table public.follows force row level security;

-- Followers and following lists of any member are visible to every signed-in member,
-- whatever the privacy mode (FR-PROFILE-010 AC1). A profile hidden from the viewer drops out
-- when the list is joined to `users`.
create policy follows_select_member on public.follows
  for select to authenticated
  using (true);

-- Unfollow, or remove one of my followers.
create policy follows_delete_party on public.follows
  for delete to authenticated
  using ((select auth.uid()) in (follower_id, followed_id));

grant select, delete on public.follows to authenticated;

-- >>> supabase/schemas/15_social_graph/020_blocks.sql
-- Social graph · blocks
--
-- A block hides two members from each other in both directions. Only the blocker can see or
-- remove the row: the blocked member is never told who blocked them.

create table public.blocks (
  blocker_id uuid not null references public.users (id) on delete cascade,
  blocked_id uuid not null references public.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker_id, blocked_id),
  constraint blocks_not_self_chk check (blocker_id <> blocked_id)
);
comment on table public.blocks is 'Blocks between members. Visible to the blocker only; effective in both directions.';

-- Reverse lookup: "has this member blocked me?" in the bilateral predicate below.
create index blocks_blocked_idx on public.blocks (blocked_id, blocker_id);

-- True when either member has blocked the other. Definer rights are required because a
-- member cannot read the other side's block row. Used by policies on every table that must
-- hide blocked counterparts.
create function kc_access.is_blocked_between(p_user_a uuid, p_user_b uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.blocks b
     where (b.blocker_id = p_user_a and b.blocked_id = p_user_b)
        or (b.blocker_id = p_user_b and b.blocked_id = p_user_a));
$$;
comment on function kc_access.is_blocked_between(uuid, uuid) is
  'Policy predicate: a block exists between the two members, in either direction.';
grant execute on function kc_access.is_blocked_between(uuid, uuid) to authenticated;

-- Blocking ends any follow relation between the two members, in both directions.
create function kc_private.blocks_remove_follows()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.follows f
   where (f.follower_id = new.blocker_id and f.followed_id = new.blocked_id)
      or (f.follower_id = new.blocked_id and f.followed_id = new.blocker_id);
  return null;
end;
$$;

create trigger blocks_remove_follows
  after insert on public.blocks
  for each row execute function kc_private.blocks_remove_follows();

alter table public.blocks enable row level security;
alter table public.blocks force row level security;

create policy blocks_select_own on public.blocks
  for select to authenticated
  using (blocker_id = (select auth.uid()));

create policy blocks_insert_own on public.blocks
  for insert to authenticated
  with check (blocker_id = (select auth.uid()));

create policy blocks_delete_own on public.blocks
  for delete to authenticated
  using (blocker_id = (select auth.uid()));

grant select, insert, delete on public.blocks to authenticated;

-- Blocked counterparts disappear from each other. Restrictive, so it narrows whatever the
-- permissive profile policies allow; a member's own row is never affected (no self-block).
create policy users_hide_blocked on public.users
  as restrictive
  for select to authenticated
  using (not kc_access.is_blocked_between((select auth.uid()), id));

-- >>> supabase/schemas/15_social_graph/030_follow_requests.sql
-- Social graph · follow_requests (FR-FOLLOW-003 … FR-FOLLOW-008)
--
-- Following a private profile needs its owner's approval. A request is pending until the
-- target accepts or rejects it or the requester cancels it; resolved rows are kept as
-- history. A rejection is silent and starts a 14-day cooldown for the same pair.

insert into kc_private.fsm_state (machine_id, status) values
  ('follow_request', 'pending'),
  ('follow_request', 'accepted'),
  ('follow_request', 'rejected'),
  ('follow_request', 'cancelled');

-- Who may make each move is part of the edge: the RPC states its role before it writes.
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('follow_request', 'pending', 'accepted', 'target'),
  ('follow_request', 'pending', 'rejected', 'target'),
  ('follow_request', 'pending', 'cancelled', 'requester'),
  -- A block between the two members withdraws the request (FR-MOD-003 AC4).
  ('follow_request', 'pending', 'cancelled', 'system');

create table public.follow_requests (
  id             uuid primary key default gen_random_uuid(),
  requester_id   uuid not null references public.users (id) on delete cascade,
  target_id      uuid not null references public.users (id) on delete cascade,
  status         text not null default 'pending',
  -- Set on rejection: the requester may ask again from this time (FR-FOLLOW-006 AC1).
  cooldown_until timestamptz,
  created_at     timestamptz not null default now(),
  resolved_at    timestamptz,
  constraint follow_requests_not_self_chk check (requester_id <> target_id),
  constraint follow_requests_cooldown_chk check ((cooldown_until is not null) = (status = 'rejected')),
  constraint follow_requests_resolved_chk check ((resolved_at is null) = (status = 'pending'))
);
comment on table public.follow_requests is
  'Requests to follow a private profile. Visible to the two members; moved only by RPCs.';

-- At most one live request per ordered pair.
create unique index follow_requests_one_pending_idx
  on public.follow_requests (requester_id, target_id) where status = 'pending';
-- Follow button state and the cooldown check: the newest request of a pair. Also the
-- foreign key on requester_id.
create index follow_requests_pair_recent_idx
  on public.follow_requests (requester_id, target_id, created_at desc);
-- Follow Requests screen: pending requests of a target, newest first, keyset on
-- (created_at, id) (FR-FOLLOW-007 AC1). Also the foreign key on target_id.
create index follow_requests_target_status_idx
  on public.follow_requests (target_id, status, created_at desc, id desc);

create trigger follow_requests_status_fsm
  before insert or update of status on public.follow_requests
  for each row execute function kc_private.fsm_guard_status('follow_request', 'status');

-- Stamps the resolution time, and the cooldown when the request was rejected.
create function kc_private.follow_requests_stamp_resolution()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.resolved_at := now();
  new.cooldown_until := case when new.status = 'rejected' then now() + interval '14 days' end;
  return new;
end;
$$;

create trigger follow_requests_stamp_resolution
  before update of status on public.follow_requests
  for each row
  when (old.status = 'pending' and new.status <> 'pending')
  execute function kc_private.follow_requests_stamp_resolution();

-- An accepted request becomes a follow edge in the same transaction (FR-FOLLOW-005 AC1).
create function kc_private.follow_requests_create_edge()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.follows (follower_id, followed_id)
  values (new.requester_id, new.target_id)
  on conflict do nothing;
  return null;
end;
$$;

create trigger follow_requests_create_edge
  after update of status on public.follow_requests
  for each row
  when (old.status = 'pending' and new.status = 'accepted')
  execute function kc_private.follow_requests_create_edge();

-- Blocking withdraws pending requests between the two members, in both directions, so a
-- request can never be approved across a block.
create function kc_private.blocks_cancel_follow_requests()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  -- A block may be inserted by code that acts under a role of its own: put it back after.
  v_outer_role constant text := coalesce(current_setting('kc.fsm_role', true), '');
begin
  perform set_config('kc.fsm_role', 'system', true);
  update public.follow_requests r
     set status = 'cancelled'
   where r.status = 'pending'
     and ((r.requester_id = new.blocker_id and r.target_id = new.blocked_id)
       or (r.requester_id = new.blocked_id and r.target_id = new.blocker_id));
  perform set_config('kc.fsm_role', v_outer_role, true);
  return null;
end;
$$;

create trigger blocks_cancel_follow_requests
  after insert on public.blocks
  for each row execute function kc_private.blocks_cancel_follow_requests();

alter table public.follow_requests enable row level security;
alter table public.follow_requests force row level security;

-- The requester sees their own requests (button state, cooldown end); the target sees the
-- requests addressed to them. Nobody else sees a request.
create policy follow_requests_select_party on public.follow_requests
  for select to authenticated
  using ((select auth.uid()) in (requester_id, target_id));

grant select on public.follow_requests to authenticated;

-- >>> supabase/schemas/15_social_graph/040_follow_rpcs.sql
-- Social graph · follow RPCs and the privacy mode switch
--
-- A follow edge and a follow request are never inserted from a device: these functions
-- decide which of the two a "follow" becomes and who may resolve a request. Errors are
-- raised with SQLSTATE P0001 and a stable snake_case message.

-- The signed-in caller, who must hold an active account: a member waiting for verification,
-- under a sanction or pending deletion cannot act on the social graph.
create function kc_private.require_active_caller()
returns uuid
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
begin
  if not exists (select 1 from public.users u where u.id = v_user_id and u.is_active) then
    raise exception 'account_not_active' using errcode = 'P0001';
  end if;
  return v_user_id;
end;
$$;
comment on function kc_private.require_active_caller() is
  'Returns auth.uid(); raises unless the caller is signed in with an active account.';

-- Follows a member: an edge at once on a public profile (FR-FOLLOW-001), a pending request
-- on a private one (FR-FOLLOW-003). Returns 'following' or 'requested'; repeating the call
-- returns the same answer without a second row.
create function public.follow_user(p_target uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_target public.users;
  v_cooldown_until timestamptz;
begin
  if p_target = v_user_id then
    raise exception 'self_follow_forbidden' using errcode = 'P0001';
  end if;

  -- The share lock makes a concurrent privacy switch of the target wait for this call.
  select u.* into v_target from public.users u where u.id = p_target for share;
  if not found or not v_target.is_active then
    raise exception 'user_unavailable' using errcode = 'P0001';
  end if;
  if kc_access.is_blocked_between(v_user_id, p_target) then
    raise exception 'blocked_relationship' using errcode = 'P0001';
  end if;

  if exists (select 1 from public.follows f
              where f.follower_id = v_user_id and f.followed_id = p_target) then
    return 'following';
  end if;
  if v_target.privacy_mode = 'Public' then
    insert into public.follows (follower_id, followed_id) values (v_user_id, p_target)
    on conflict do nothing;
    return 'following';
  end if;

  if exists (select 1 from public.follow_requests r
              where r.requester_id = v_user_id and r.target_id = p_target and r.status = 'pending') then
    return 'requested';
  end if;

  -- 14 days after a rejection the requester may ask again (FR-FOLLOW-008); the detail
  -- carries the end of the cooldown for the "try again in N days" hint.
  select max(r.cooldown_until) into v_cooldown_until
    from public.follow_requests r
   where r.requester_id = v_user_id and r.target_id = p_target
     and r.status = 'rejected' and r.cooldown_until > now();
  if v_cooldown_until is not null then
    raise exception 'follow_request_cooldown_active' using
      errcode = 'P0001',
      detail = 'cooldown_until='
        || to_char(v_cooldown_until at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
  end if;

  insert into public.follow_requests (requester_id, target_id) values (v_user_id, p_target)
  on conflict (requester_id, target_id) where status = 'pending' do nothing;
  return 'requested';
end;
$$;
comment on function public.follow_user(uuid) is
  'Follows a member: an edge on a public profile, a pending request on a private one.';
grant execute on function public.follow_user(uuid) to authenticated;

-- The target accepts or silently rejects a pending request (FR-FOLLOW-005, FR-FOLLOW-006).
create function public.follow_request_decide(p_requester uuid, p_accept boolean)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_moved boolean;
begin
  if p_accept is null then
    raise exception 'invalid_decision' using errcode = 'P0001';
  end if;

  perform set_config('kc.fsm_role', 'target', true);
  update public.follow_requests r
     set status = case when p_accept then 'accepted' else 'rejected' end
   where r.requester_id = p_requester and r.target_id = v_user_id and r.status = 'pending';
  v_moved := found;
  perform set_config('kc.fsm_role', '', true);

  if not v_moved then
    raise exception 'follow_request_not_pending' using errcode = 'P0001';
  end if;
end;
$$;
comment on function public.follow_request_decide(uuid, boolean) is
  'The caller accepts or rejects a pending follow request addressed to them.';
grant execute on function public.follow_request_decide(uuid, boolean) to authenticated;

-- The requester withdraws their own pending request; no cooldown follows (FR-FOLLOW-004).
create function public.follow_request_cancel(p_target uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_moved boolean;
begin
  perform set_config('kc.fsm_role', 'requester', true);
  update public.follow_requests r
     set status = 'cancelled'
   where r.requester_id = v_user_id and r.target_id = p_target and r.status = 'pending';
  v_moved := found;
  perform set_config('kc.fsm_role', '', true);

  if not v_moved then
    raise exception 'follow_request_not_pending' using errcode = 'P0001';
  end if;
end;
$$;
comment on function public.follow_request_cancel(uuid) is 'The caller withdraws their pending follow request.';
grant execute on function public.follow_request_cancel(uuid) to authenticated;

-- Switches the caller's profile between 'Public' and 'Private' (FR-PROFILE-005/006).
-- The switch is not retroactive for posts or existing followers. Going public accepts every
-- pending request in the same transaction; none of them can be from a blocked member,
-- because a block withdraws the requests between its two members.
create function public.set_privacy_mode(p_mode text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
begin
  if p_mode is null or p_mode not in ('Public', 'Private') then
    raise exception 'invalid_privacy_mode' using errcode = 'P0001';
  end if;

  update public.users u
     set privacy_mode = p_mode, privacy_changed_at = now()
   where u.id = v_user_id and u.privacy_mode <> p_mode;
  if not found or p_mode = 'Private' then
    return;
  end if;

  perform set_config('kc.fsm_role', 'target', true);
  update public.follow_requests r
     set status = 'accepted'
   where r.target_id = v_user_id and r.status = 'pending';
  perform set_config('kc.fsm_role', '', true);
end;
$$;
comment on function public.set_privacy_mode(text) is
  'Sets the caller''s privacy mode; going public accepts all pending follow requests.';
grant execute on function public.set_privacy_mode(text) to authenticated;

-- >>> supabase/schemas/15_social_graph/050_user_profile_fields.sql
-- Social graph · user_profile_fields (D109, D110, FR-PROFILE-007 AC8/AC9)
--
-- Optional profile fields, one row per member and field, each with its own visibility.
-- The table belongs to the profile, but lives in this module because who may read a field
-- depends on the follow graph.

create table public.user_profile_fields (
  user_id           uuid not null references public.users (id) on delete cascade,
  -- interests: giving worlds and item subcategories the member cares about
  -- help_tags: what the member can help with (giving-world tags)
  -- affiliated_org: a self-declared affiliation; a label only, it grants no role
  field_key         text not null check (field_key in ('interests', 'help_tags', 'affiliated_org')),
  -- Who may read the field. Left empty on insert, it follows the owner's privacy mode at
  -- that moment: everyone on a public profile, followers on a private one.
  visibility        text not null check (visibility in ('everyone', 'followers', 'only_me')),
  -- Value of the two tag fields: 1 to 50 slugs.
  tags              text[] check (
                      cardinality(tags) between 1 and 50
                      and array_to_string(tags, ' ', '') ~ '^[a-z0-9_.:-]{1,64}( [a-z0-9_.:-]{1,64})*$'),
  -- Value of affiliated_org. The organizations module adds the foreign key and restricts
  -- it to verified organizations.
  affiliated_org_id uuid,
  updated_at        timestamptz not null default now(),
  primary key (user_id, field_key),
  constraint user_profile_fields_value_chk check (
    case when field_key = 'affiliated_org'
      then affiliated_org_id is not null and tags is null
      else tags is not null and affiliated_org_id is null
    end)
);
comment on table public.user_profile_fields is
  'Optional profile fields with per-field visibility. A missing row means the field is not filled in.';

-- Members affiliated with an organization (organization page; future foreign key).
create index user_profile_fields_affiliated_org_idx
  on public.user_profile_fields (affiliated_org_id) where affiliated_org_id is not null;

-- Applies the default visibility. Runs with the caller's rights: the owner can always read
-- their own profile row.
create function kc_private.user_profile_fields_default_visibility()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  select case u.privacy_mode when 'Private' then 'followers' else 'everyone' end
    into new.visibility
    from public.users u where u.id = new.user_id;
  return new;
end;
$$;

create trigger user_profile_fields_default_visibility
  before insert on public.user_profile_fields
  for each row
  when (new.visibility is null)
  execute function kc_private.user_profile_fields_default_visibility();

create trigger user_profile_fields_set_updated_at
  before update on public.user_profile_fields
  for each row execute function kc_private.set_updated_at();

alter table public.user_profile_fields enable row level security;
alter table public.user_profile_fields force row level security;

-- The owner reads every field. Anyone else reads a field only when the owner's profile is
-- visible to them (so never across a block, and never for an inactive account) and the
-- field is open to everyone, or open to followers and the reader follows the owner.
create policy user_profile_fields_select_visible on public.user_profile_fields
  for select to authenticated
  using (
    user_id = (select auth.uid())
    or (visibility <> 'only_me'
        and exists (
          select 1
            from public.users u
           where u.id = user_profile_fields.user_id
             and (user_profile_fields.visibility = 'everyone'
                  or exists (select 1 from public.follows f
                              where f.follower_id = (select auth.uid())
                                and f.followed_id = u.id)))));

create policy user_profile_fields_insert_self on public.user_profile_fields
  for insert to authenticated
  with check (user_id = (select auth.uid()));

create policy user_profile_fields_update_self on public.user_profile_fields
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- Clearing a field is deleting its row.
create policy user_profile_fields_delete_self on public.user_profile_fields
  for delete to authenticated
  using (user_id = (select auth.uid()));

grant select, insert, delete on public.user_profile_fields to authenticated;
grant update (visibility, tags, affiliated_org_id) on public.user_profile_fields to authenticated;

-- >>> supabase/schemas/20_posts/010_catalog.sql
-- Posts · catalog (giving worlds, post kinds, item subcategories)
--
-- Configuration that decides what a post may be. Rows are loaded by the seed scripts and
-- changed only by migrations or server code: a device can read the catalog, never write it.
-- One list of giving worlds, with no second "domain" layer (D100).

-- A giving world (D100) and its per-world behaviour.
create table public.worlds (
  slug                    text primary key check (slug ~ '^[a-z][a-z0-9_]{1,30}$'),
  label_he                text not null,
  label_en                text not null,
  -- How careful the product is with this world's content (review, exposure).
  sensitivity             text not null default 'standard'
                            check (sensitivity in ('standard', 'elevated', 'restricted')),
  -- Publishing in this world requires a verified identity (for example housing, D30).
  requires_verification   boolean not null default false,
  -- Default audience of the poster's identity: 1 operators only · 2 followers · 3 everyone.
  default_anonymity_level smallint not null default 3 check (default_anonymity_level between 1 and 3),
  -- Default lifetime of a post; null = posts of this world do not expire (D21).
  default_ttl_hours       integer check (default_ttl_hours > 0),
  -- Whether distance matters: nearby, same region, or not at all (online).
  geo_mode                text not null default 'local' check (geo_mode in ('local', 'regional', 'remote')),
  default_radius_km       numeric(8, 2) not null default 25 check (default_radius_km > 0),
  -- Share of distance in ranking and matching for this world, 0 to 1.
  geo_weight              numeric(4, 3) not null default 1 check (geo_weight between 0 and 1),
  -- Posts of this world also appear in the main feed, not only on the world's own screen.
  shows_in_main_feed      boolean not null default false,
  -- An inactive world is kept for its existing posts but accepts no new ones.
  is_active               boolean not null default true,
  sort_order              integer not null default 0,
  created_at              timestamptz not null default now()
);
comment on table public.worlds is 'Giving worlds (D100) and their per-world configuration.';

-- What can be posted in a world: "ride offer", "lesson request", "item". Each kind owns the
-- JSON Schema of the type-specific fields stored in posts.details.
create table public.post_kinds (
  id                uuid primary key default gen_random_uuid(),
  world_slug        text not null references public.worlds (slug) on update cascade on delete cascade,
  slug              text not null check (slug ~ '^[a-z][a-z0-9_]{1,40}$'),
  label_he          text not null,
  label_en          text not null,
  -- Which side may use this kind; posts.direction must agree.
  direction         text not null check (direction in ('offer', 'request', 'either')),
  -- JSON Schema for posts.details of this kind.
  detail_schema     jsonb not null default '{"type":"object"}'::jsonb
                      check (jsonb_typeof(detail_schema) = 'object'),
  -- Overrides the world's default lifetime; null = follow the world.
  default_ttl_hours integer check (default_ttl_hours > 0),
  is_active         boolean not null default true,
  sort_order        integer not null default 0,
  created_at        timestamptz not null default now(),
  constraint post_kinds_world_slug_key unique (world_slug, slug),
  -- Target of the composite foreign key that keeps a post's kind inside the post's world.
  constraint post_kinds_id_world_key unique (id, world_slug)
);
comment on table public.post_kinds is 'Kinds of post per giving world; detail_schema describes posts.details.';

-- Kind picker of a world's create form (also covers the world_slug foreign key).
create index post_kinds_world_order_idx on public.post_kinds (world_slug, sort_order);

-- Sub-categories of a giving world, as a tree (item subcategory, food type, knowledge shelf).
-- Replaces the fixed item list that used to be a check constraint on posts.
create table public.item_subcategories (
  id         uuid primary key default gen_random_uuid(),
  world_slug text not null references public.worlds (slug) on update cascade on delete cascade,
  parent_id  uuid,
  slug       text not null check (slug ~ '^[a-z][a-z0-9_]{1,40}$'),
  label_he   text not null,
  label_en   text not null,
  is_active  boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  constraint item_subcategories_world_slug_key unique (world_slug, slug),
  constraint item_subcategories_id_world_key unique (id, world_slug),
  constraint item_subcategories_not_own_parent_chk check (parent_id <> id),
  -- A child always belongs to its parent's world.
  constraint item_subcategories_parent_fk foreign key (parent_id, world_slug)
    references public.item_subcategories (id, world_slug) on update cascade on delete cascade
);
comment on table public.item_subcategories is 'Per-world sub-category tree; a post points at one node of its own world.';

-- Children of a node in display order: the subcategory picker and browse filters.
create index item_subcategories_tree_idx on public.item_subcategories (world_slug, parent_id, sort_order);
-- Covers the parent foreign key (cascade on removing a node).
create index item_subcategories_parent_idx on public.item_subcategories (parent_id) where parent_id is not null;

alter table public.worlds enable row level security;
alter table public.worlds force row level security;
alter table public.post_kinds enable row level security;
alter table public.post_kinds force row level security;
alter table public.item_subcategories enable row level security;
alter table public.item_subcategories force row level security;

-- Read-only configuration for signed-in members. No insert, update or delete policy and no
-- write grant exist, so the catalog cannot be changed from a device.
create policy worlds_select_member on public.worlds
  for select to authenticated
  using (true);
create policy post_kinds_select_member on public.post_kinds
  for select to authenticated
  using (true);
create policy item_subcategories_select_member on public.item_subcategories
  for select to authenticated
  using (true);

grant select on public.worlds to authenticated;
grant select on public.post_kinds to authenticated;
grant select on public.item_subcategories to authenticated;

-- >>> supabase/schemas/20_posts/020_posts.sql
-- Posts · posts (the one content table of every giving world)
--
-- Everything published in the product is one post (D2, D19): a primary giving world, a kind, a
-- direction, a lifecycle status and an audience. Fields that only some worlds have live in
-- `details` (validated against post_kinds.detail_schema) or in a 1:1 detail table added by
-- that world's module. The exact address is never stored here (post_private_locations).

create table public.posts (
  id                     uuid primary key default gen_random_uuid(),
  owner_id               uuid not null references public.users (id) on delete cascade,
  -- Organization the post is published for. The foreign key is added by the organizations
  -- module, which creates the referenced table.
  beneficiary_org_id     uuid,
  world_slug             text not null references public.worlds (slug) on update cascade,
  kind_id                uuid not null,
  -- Which 1:1 detail table, if any, extends the post.
  post_type              text not null default 'standard'
                           check (post_type in ('standard', 'ride', 'event', 'housing_stay', 'job', 'challenge')),
  direction              text not null check (direction in ('offer', 'request')),
  -- Lifecycle, machine `post` (030_post_status_machine.sql). Never written by a device.
  status                 text not null default 'open',
  -- Status held when an admin removed the post; a restore returns to it (D129).
  status_before_removal  text check (status_before_removal in
                           ('open', 'paused', 'closed_delivered', 'deleted_no_recipient', 'expired')),
  -- Audience chosen by the owner; may change freely after publishing (FR-POST-009).
  visibility             text not null default 'Public'
                           check (visibility in ('Public', 'FollowersOnly', 'OnlyMe')),
  title                  text not null check (char_length(title) between 1 and 80),
  description            text check (char_length(description) <= 500),
  item_subcategory_id    uuid,
  -- Type-specific fields. Only the shape is checked here; validation against the kind's
  -- JSON Schema is added with the module that enables the schema validator.
  details                jsonb not null default '{}'::jsonb check (jsonb_typeof(details) = 'object'),
  city_id                text not null references public.cities (city_id),
  -- How precisely the location is shown to others (FR-POST-003 AC3).
  location_display_level text not null default 'CityAndStreet'
                           check (location_display_level in ('CityOnly', 'CityAndStreet', 'FullAddress')),
  -- The only location other members, the map and matching ever read. Derived by trigger
  -- (050_post_private_locations.sql); never the exact address.
  geo_approx             extensions.geography(Point, 4326),
  -- When the offer or need applies (event time, availability window).
  time_window            tstzrange check (not isempty(time_window)),
  -- 1 low · 2 medium · 3 high.
  urgency_level          smallint check (urgency_level between 1 and 3),
  -- When the post closes by itself; null = never (D21). Set by server code per post kind.
  expires_at             timestamptz,
  -- 'imported' marks a post brought in from an external channel until it is claimed.
  source                 text not null default 'native' check (source in ('native', 'imported')),
  -- Detected BCP 47 language of title and description; written by the translation pipeline.
  source_language        text check (char_length(source_language) between 2 and 35),
  -- Search document; `simple` keeps Hebrew tokens unstemmed.
  search_vector          tsvector generated always as (
                           to_tsvector('simple', title || ' ' || coalesce(description, ''))) stored,
  -- First time the post became open; the feed sorts on it. Null while a draft.
  published_at           timestamptz,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  -- The kind and the subcategory must belong to the post's own world.
  constraint posts_kind_fk foreign key (kind_id, world_slug)
    references public.post_kinds (id, world_slug) on update cascade,
  constraint posts_item_subcategory_fk foreign key (item_subcategory_id, world_slug)
    references public.item_subcategories (id, world_slug) on update cascade,
  -- The saved status exists exactly while the post is removed.
  constraint posts_removal_memory_chk
    check ((status = 'removed_admin') = (status_before_removal is not null)),
  -- A draft has never been published; every other status has.
  constraint posts_published_chk check ((status = 'draft') = (published_at is null))
);
comment on table public.posts is 'Every post of every giving world. Status moves only through server code.';

-- Main feed: open public posts, newest first (keyset on published_at, id).
create index posts_feed_recent_idx on public.posts (published_at desc, id desc)
  where status = 'open' and visibility = 'Public';
-- A profile's posts and "my posts" in any status, newest first; covers the owner foreign key.
create index posts_owner_recent_idx on public.posts (owner_id, created_at desc, id desc);
-- Browse a world by status, newest first; covers the world foreign key.
create index posts_world_status_recent_idx on public.posts (world_slug, status, published_at desc, id desc);
-- Feed and browse filtered by city; covers the city foreign key.
create index posts_city_recent_idx on public.posts (city_id, published_at desc, id desc) where status = 'open';
-- Expiry sweep: live posts whose time has come.
create index posts_expiry_due_idx on public.posts (expires_at)
  where expires_at is not null and status in ('open', 'paused');
-- Whole-word search over open posts.
create index posts_search_gin_idx on public.posts using gin (search_vector) where status = 'open';
-- Substring search over open posts (Hebrew has no useful stemming). A query must use the
-- same expression: (title || ' ' || coalesce(description, '')) ilike '%…%'.
create index posts_text_trgm_idx on public.posts
  using gin ((title || ' ' || coalesce(description, '')) extensions.gin_trgm_ops) where status = 'open';
-- Radius search, map pins and matching over open posts.
create index posts_geo_approx_gist_idx on public.posts using gist (geo_approx) where status = 'open';
-- Foreign keys to the catalog (a kind or subcategory being retired or renamed).
create index posts_kind_idx on public.posts (kind_id);
create index posts_item_subcategory_idx on public.posts (item_subcategory_id)
  where item_subcategory_id is not null;

create trigger posts_set_updated_at
  before update on public.posts
  for each row execute function kc_private.set_updated_at();

-- >>> supabase/schemas/20_posts/030_post_status_machine.sql
-- Posts · lifecycle (machine `post`: spec state machine S1 plus `draft`)
--
--   draft ─► open ◄─► paused
--             ├─► closed_delivered ─► open            (reopen, owner only)
--             ├─► deleted_no_recipient ─► open        (reopen, owner only)
--             └─► expired                             (never reopened: republish is a new post, D127)
--   live ─► hidden_pending_review ─► open | removed_admin
--   any published ─► removed_admin ─► the status held before the removal (D129)
--
-- Each edge names who may take it. The RPC performing a move states its role in the
-- transaction-local setting `kc.fsm_role`; a write without a role (or with the wrong one)
-- is refused, and a device has no UPDATE privilege on the column at all.
--   owner   the member who owns the post (D104)
--   admin   a moderator acting on the post
--   system  sweeps and automatic moderation (expiry D21 / D128, review hide D33, handoff completion)

insert into kc_private.fsm_state (machine_id, status) values
  ('post', 'draft'),
  ('post', 'open'),
  ('post', 'paused'),
  ('post', 'closed_delivered'),
  ('post', 'deleted_no_recipient'),
  ('post', 'expired'),
  ('post', 'hidden_pending_review'),
  ('post', 'removed_admin');

insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  -- Owner management (D104).
  ('post', 'draft', 'open', 'owner'),
  ('post', 'open', 'paused', 'owner'),
  ('post', 'paused', 'open', 'owner'),
  ('post', 'open', 'closed_delivered', 'owner'),
  ('post', 'open', 'deleted_no_recipient', 'owner'),
  ('post', 'paused', 'deleted_no_recipient', 'owner'),
  ('post', 'expired', 'deleted_no_recipient', 'owner'),
  ('post', 'hidden_pending_review', 'deleted_no_recipient', 'owner'),
  ('post', 'closed_delivered', 'open', 'owner'),
  ('post', 'deleted_no_recipient', 'open', 'owner'),
  -- A handoff completed by the other side closes the post; a recipient who removes their
  -- mark turns a delivered post into one closed without a recipient (FR-CLOSURE-007).
  ('post', 'open', 'closed_delivered', 'system'),
  ('post', 'hidden_pending_review', 'closed_delivered', 'system'),
  ('post', 'closed_delivered', 'deleted_no_recipient', 'system'),
  -- Expiry sweeps.
  ('post', 'open', 'expired', 'system'),
  ('post', 'paused', 'expired', 'system'),
  -- Automatic hide while reports are reviewed, and its automatic lift.
  ('post', 'open', 'hidden_pending_review', 'system'),
  ('post', 'paused', 'hidden_pending_review', 'system'),
  ('post', 'closed_delivered', 'hidden_pending_review', 'system'),
  ('post', 'expired', 'hidden_pending_review', 'system'),
  ('post', 'hidden_pending_review', 'open', 'system'),
  -- Moderation: a review outcome, a removal from any published status, and its restore.
  ('post', 'hidden_pending_review', 'open', 'admin'),
  ('post', 'open', 'removed_admin', 'admin'),
  ('post', 'paused', 'removed_admin', 'admin'),
  ('post', 'closed_delivered', 'removed_admin', 'admin'),
  ('post', 'deleted_no_recipient', 'removed_admin', 'admin'),
  ('post', 'expired', 'removed_admin', 'admin'),
  ('post', 'hidden_pending_review', 'removed_admin', 'admin'),
  ('post', 'removed_admin', 'open', 'admin'),
  ('post', 'removed_admin', 'paused', 'admin'),
  ('post', 'removed_admin', 'closed_delivered', 'admin'),
  ('post', 'removed_admin', 'deleted_no_recipient', 'admin'),
  ('post', 'removed_admin', 'expired', 'admin');

create trigger posts_status_fsm
  before insert or update of status on public.posts
  for each row execute function kc_private.fsm_guard_status('post', 'status');

-- Rules of a status write that the graph alone cannot express. Fires after posts_status_fsm
-- (triggers run in name order), so the move itself is already known to be legal.
--   insert   the kind must be active and admit the post's direction
--   publish  stamps the first time the post leaves draft
--   → open   an owner may hold at most 20 open posts (FR-POST-011); a paused post is not
--            resumed after its own expiry (D104)
--   removal  remembers the status the post is removed from, and a restore may only return
--            to it (D129); a post hidden for review counts as open
-- Definer rights: it reads the catalog and locks the owner's counter row, which a member
-- may not write.
create function kc_private.posts_apply_status_rules()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_from constant text := case tg_op when 'UPDATE' then old.status end;
  v_open_limit constant integer := 20;
begin
  if tg_op = 'INSERT' and not exists (
       select 1 from public.post_kinds k
        where k.id = new.kind_id and k.is_active and k.direction in (new.direction, 'either')) then
    raise exception 'post_kind_not_allowed' using errcode = 'P0001',
      detail = 'the post kind is inactive or does not admit this direction';
  end if;

  if v_from is not distinct from new.status then
    return new;
  end if;

  -- Leaving draft (or being created past it, as an imported post is) is the publish moment.
  if new.status <> 'draft' then
    new.published_at := coalesce(new.published_at, now());
  end if;

  if new.status = 'open' then
    if v_from = 'paused' and new.expires_at <= now() then
      raise exception 'post_expired' using errcode = 'P0001', detail = 'a post is not resumed after its expiry';
    end if;
    -- Moderation and sweeps return a post to open regardless of the owner's quota.
    if coalesce(current_setting('kc.fsm_role', true), '') not in ('admin', 'system') then
      -- The counter row is the per-owner lock: two concurrent publishes cannot both pass.
      perform 1 from public.user_stats s where s.user_id = new.owner_id for update;
      if (select count(*) from public.posts p where p.owner_id = new.owner_id and p.status = 'open')
         >= v_open_limit then
        raise exception 'post_limit_exceeded' using errcode = 'P0001',
          detail = format('at most %s open posts per member', v_open_limit);
      end if;
    end if;
  end if;

  if new.status = 'removed_admin' then
    new.status_before_removal := case v_from when 'hidden_pending_review' then 'open' else v_from end;
  elsif v_from = 'removed_admin' then
    if new.status is distinct from old.status_before_removal then
      raise exception 'illegal_transition' using errcode = 'P0001',
        detail = format('post: a removed post is restored to %s', old.status_before_removal);
    end if;
    new.status_before_removal := null;
  end if;

  return new;
end;
$$;
comment on function kc_private.posts_apply_status_rules() is
  'BEFORE INSERT OR UPDATE OF status on posts: kind check, publish time, open-post quota, removal memory.';

create trigger posts_status_rules
  before insert or update of status on public.posts
  for each row execute function kc_private.posts_apply_status_rules();

-- >>> supabase/schemas/20_posts/040_post_access.sql
-- Posts · who may read and write a post
--
-- Visibility is decided by indexed columns and one lookup on `follows`; no function is
-- evaluated over the row. Nothing is granted to signed-out callers.

alter table public.posts enable row level security;
alter table public.posts force row level security;

-- The owner sees their own posts in every status, whatever their account state.
create policy posts_select_owner on public.posts
  for select to authenticated
  using (owner_id = (select auth.uid()));

-- Another member sees a post when all three hold:
--   1. status — only `open` and `closed_delivered`. A delivered post stays on the giver's
--      profile as their record of giving (FR-PROFILE-001 closed tab, FR-POST-021). Drafts,
--      paused posts (D104), posts closed without a recipient, expired posts and posts hidden
--      or removed by moderation are the owner's alone.
--   2. audience — `Public`, or `FollowersOnly` when the viewer follows the owner. `OnlyMe`
--      never matches.
--   3. owner — the owner's profile is visible to the viewer. The subquery runs under the
--      viewer's own access to `users`, so it inherits that table's rules: the owner's
--      account is active and no block exists between the two, in either direction.
-- Extension points (later modules add policies; this one does not change): moderators read
-- every post; the counterparty of a handoff reads the post whatever its audience; a
-- member's own report hides the post from them (restrictive policy).
create policy posts_select_visible on public.posts
  for select to authenticated
  using (
    status in ('open', 'closed_delivered')
    and (visibility = 'Public'
         or (visibility = 'FollowersOnly'
             and exists (select 1 from public.follows f
                          where f.follower_id = (select auth.uid()) and f.followed_id = posts.owner_id)))
    and exists (select 1 from public.users u where u.id = posts.owner_id));

-- A member creates their own post, as a draft or already open, written in the product
-- (never 'imported'). A member whose account is not active cannot post (spec 7.1, S2).
create policy posts_insert_owner on public.posts
  for insert to authenticated
  with check (
    owner_id = (select auth.uid())
    and status in ('draft', 'open')
    and exists (select 1 from public.users u where u.id = (select auth.uid()) and u.is_active));

-- The owner edits content while the post is a draft, open or paused; once closed, expired
-- or under moderation the content is locked (D104). Which columns is decided by the grant.
create policy posts_update_owner on public.posts
  for update to authenticated
  using (
    owner_id = (select auth.uid())
    and status in ('draft', 'open', 'paused')
    and exists (select 1 from public.users u where u.id = (select auth.uid()) and u.is_active))
  with check (owner_id = (select auth.uid()));

-- Only a draft is ever deleted from a device: it was never published, so nobody else holds
-- a record of it. Removing a published post is a status move (`deleted_no_recipient`) made
-- by an RPC, and the row is purged by a server job after its grace period (design §4.1).
create policy posts_delete_owner_draft on public.posts
  for delete to authenticated
  using (owner_id = (select auth.uid()) and status = 'draft');

grant select, delete on public.posts to authenticated;

-- Insert: everything the create form sets. Status is limited to draft / open by the policy.
-- Not insertable: beneficiary_org_id, expires_at, source, source_language, geo_approx,
-- status_before_removal, published_at, timestamps — all server-written.
grant insert (
  id, owner_id, world_slug, kind_id, post_type, direction, status, visibility, title, description,
  item_subcategory_id, details, city_id, location_display_level, time_window, urgency_level
) on public.posts to authenticated;

-- Update: content only. The owner, world, kind, post type and direction are fixed at
-- creation (FR-POST-008 AC2); status moves through RPCs; derived columns are never writable.
grant update (
  visibility, title, description, item_subcategory_id, details, city_id, location_display_level,
  time_window, urgency_level
) on public.posts to authenticated;

-- >>> supabase/schemas/20_posts/050_post_private_locations.sql
-- Posts · exact address and the approximate location shown to others (design §3.9)
--
-- The exact point of a post lives only in `post_private_locations`, readable by its owner.
-- Everyone else — feed, map, distance search, matching — reads `posts.geo_approx`, which is
-- derived here and can never be written directly. Releasing the exact address to the
-- counterparty of a confirmed handoff is an audited RPC of the handoffs module.

create table public.post_private_locations (
  post_id       uuid primary key references public.posts (id) on delete cascade,
  -- Geocoded position of the address; null until the address has been resolved.
  exact_point   extensions.geography(Point, 4326),
  street        text check (char_length(btrim(street)) between 1 and 80),
  -- Digits with an optional entrance letter, Latin or Hebrew (U+05D0–U+05EA).
  street_number text check (street_number ~ '^[0-9]+[A-Za-z\u05D0-\u05EA]?$'),
  -- Free text for the person arriving: floor, entrance code, where to leave things.
  access_notes  text check (char_length(access_notes) <= 300),
  updated_at    timestamptz not null default now(),
  -- A house number only makes sense with a street.
  constraint post_private_locations_number_needs_street_chk
    check (street_number is null or street is not null)
);
comment on table public.post_private_locations is 'Exact address of a post. Readable and writable by the post owner only.';

create trigger post_private_locations_set_updated_at
  before update on public.post_private_locations
  for each row execute function kc_private.set_updated_at();

-- Approximate location of a post for the given display level.
--   CityOnly        the city centre
--   CityAndStreet   the city centre for now; the geo-reference module, which brings the
--                   street list, replaces this branch with the street centroid
--   FullAddress     the exact point snapped to a grid of 0.003° (about 300 m), then moved by
--                   an offset of up to half a cell that is fixed per post. The offset is
--                   taken from a hash of the post id, so it never changes between
--                   derivations, and any exact point inside the same cell yields the same
--                   result. Without an exact point the city centre is used.
create function kc_private.post_geo_approx(
  p_post_id uuid,
  p_city_id text,
  p_display_level text,
  p_exact_point extensions.geography
)
returns extensions.geography
language sql
stable
set search_path = ''
as $$
  with cell as (select 0.003::double precision as size),
       hash as (select md5(p_post_id::text) as hex)
  select case
    when p_display_level = 'FullAddress' and p_exact_point is not null then
      extensions.st_translate(
        extensions.st_snaptogrid(p_exact_point::extensions.geometry, cell.size),
        -- Two independent values in [-0.5, 0.5) of a cell, from separate parts of the hash.
        (('x' || substr(hash.hex, 1, 8))::bit(32)::bigint / 4294967296.0 - 0.5) * cell.size,
        (('x' || substr(hash.hex, 9, 8))::bit(32)::bigint / 4294967296.0 - 0.5) * cell.size
      )::extensions.geography
    else (select c.location from public.cities c where c.city_id = p_city_id)
  end
  from cell, hash;
$$;
comment on function kc_private.post_geo_approx(uuid, text, text, extensions.geography) is
  'Approximate public location of a post: city centre, or the exact point coarsened to about 300 m.';

-- Keeps posts.geo_approx derived on every write that could change it. On insert the private
-- location does not exist yet, so the post starts at the city centre and is refined by the
-- trigger on post_private_locations below. Definer rights: the derivation is internal.
create function kc_private.posts_set_geo_approx()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.geo_approx := kc_private.post_geo_approx(
    new.id, new.city_id, new.location_display_level,
    (select l.exact_point from public.post_private_locations l where l.post_id = new.id));
  return new;
end;
$$;

-- `geo_approx` is in the column list so that a server-side write to it is overwritten too.
create trigger posts_set_geo_approx
  before insert or update of city_id, location_display_level, geo_approx on public.posts
  for each row execute function kc_private.posts_set_geo_approx();

-- Re-derives the post's approximate location when its exact point is set, moved or removed.
-- Definer rights: the owner has no UPDATE privilege on posts.geo_approx.
create function kc_private.post_private_locations_refresh_geo()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post_id constant uuid := case tg_op when 'DELETE' then old.post_id else new.post_id end;
begin
  -- Writing the column fires posts_set_geo_approx, which computes the value.
  update public.posts p set geo_approx = null where p.id = v_post_id;
  return null;
end;
$$;

create trigger post_private_locations_refresh_geo
  after insert or delete or update of exact_point on public.post_private_locations
  for each row execute function kc_private.post_private_locations_refresh_geo();

alter table public.post_private_locations enable row level security;
alter table public.post_private_locations force row level security;

-- Every policy asks the same question: is the caller the owner of the post? The subquery
-- runs under the caller's access to `posts` and is a primary-key lookup.
create policy post_private_locations_select_owner on public.post_private_locations
  for select to authenticated
  using (exists (select 1 from public.posts p
                  where p.id = post_private_locations.post_id and p.owner_id = (select auth.uid())));

create policy post_private_locations_insert_owner on public.post_private_locations
  for insert to authenticated
  with check (exists (select 1 from public.posts p
                       where p.id = post_private_locations.post_id and p.owner_id = (select auth.uid())));

-- The address is editable exactly while the post's content is (draft, open, paused; D104).
create policy post_private_locations_update_owner on public.post_private_locations
  for update to authenticated
  using (exists (select 1 from public.posts p
                  where p.id = post_private_locations.post_id and p.owner_id = (select auth.uid())
                    and p.status in ('draft', 'open', 'paused')))
  with check (exists (select 1 from public.posts p
                       where p.id = post_private_locations.post_id and p.owner_id = (select auth.uid())));

grant select on public.post_private_locations to authenticated;
grant insert (post_id, exact_point, street, street_number, access_notes)
  on public.post_private_locations to authenticated;
-- The row cannot be moved to another post.
grant update (exact_point, street, street_number, access_notes)
  on public.post_private_locations to authenticated;

-- >>> supabase/schemas/20_posts/060_post_counters.sql
-- Posts · profile counters
--
-- user_stats holds, per member, the number of open posts in each audience and the number of
-- posts ever published. A viewer is shown the sum of the audiences they may see
-- (FR-PROFILE-013), so the three open counters are kept apart.

-- Applies the effect of one post write to its owner's counters, in the same transaction.
-- A post counts as open only in status `open`; it counts as created the moment it is first
-- published, and stays counted when it is later closed or deleted. Definer rights: counters
-- are not writable by members. When the owner's account is being removed the counter row
-- is already gone and the update matches nothing.
create function kc_private.posts_sync_user_stats()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  -- Audience the post was counted under before / is counted under after; null = not open.
  v_old constant text := case when tg_op <> 'INSERT' and old.status = 'open' then old.visibility end;
  v_new constant text := case when tg_op <> 'DELETE' and new.status = 'open' then new.visibility end;
  v_published constant integer := case
    when tg_op = 'INSERT' and new.published_at is not null then 1
    when tg_op = 'UPDATE' and old.published_at is null and new.published_at is not null then 1
    else 0 end;
  v_owner_id constant uuid := case tg_op when 'DELETE' then old.owner_id else new.owner_id end;
begin
  if v_old is not distinct from v_new and v_published = 0 then
    return null;
  end if;

  update public.user_stats s
     set open_posts_public = greatest(s.open_posts_public
           + (v_new is not distinct from 'Public')::integer - (v_old is not distinct from 'Public')::integer, 0),
         open_posts_followers_only = greatest(s.open_posts_followers_only
           + (v_new is not distinct from 'FollowersOnly')::integer
           - (v_old is not distinct from 'FollowersOnly')::integer, 0),
         open_posts_only_me = greatest(s.open_posts_only_me
           + (v_new is not distinct from 'OnlyMe')::integer - (v_old is not distinct from 'OnlyMe')::integer, 0),
         posts_created_total = s.posts_created_total + v_published
   where s.user_id = v_owner_id;
  return null;
end;
$$;
comment on function kc_private.posts_sync_user_stats() is
  'AFTER trigger on posts: keeps the owner''s open-post and created-post counters in step.';

create trigger posts_sync_user_stats
  after insert or delete or update of status, visibility on public.posts
  for each row execute function kc_private.posts_sync_user_stats();

-- >>> supabase/schemas/25_handoffs/010_post_handoffs.sql
-- Handoffs · post_handoffs (the closing stage of every post, D19)
--
-- One row per member who takes part in closing a post: the member who reserved an item, the
-- passenger of a ride, the guest of a stay, the attendee of an event, the learner of a
-- session. It replaces the former `recipients` table as well: the member an owner names when
-- closing a post is a handoff that is created already handed over.
--
-- Four machines share the table; the post type picks the one that rules a row:
--   giving_handoff      every post type without its own machine (items, food, animals, knowledge)
--   ride_booking        post type `ride`
--   housing_booking     post type `housing_stay`
--   event_registration  post type `event`
-- Each edge names who may take it: the post `owner`, the `recipient` (the other member), or
-- `system` (sweeps and the consequences of a post leaving the air).

-- The machine that rules the handoffs of a post of this type.
create function kc_private.handoff_machine_of(p_post_type text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_post_type
    when 'ride' then 'ride_booking'
    when 'housing_stay' then 'housing_booking'
    when 'event' then 'event_registration'
    else 'giving_handoff'
  end;
$$;
comment on function kc_private.handoff_machine_of(text) is
  'Lifecycle machine of the handoffs of a post, by post type.';

insert into kc_private.fsm_state (machine_id, status)
select m.machine_id, s.status
  from (values
    ('giving_handoff', array['reserved', 'confirmed', 'handed_over', 'cancelled', 'no_show']),
    ('ride_booking', array['reserved', 'confirmed', 'handed_over', 'cancelled']),
    ('housing_booking', array['reserved', 'confirmed', 'handed_over', 'cancelled', 'no_show']),
    ('event_registration',
     array['waitlisted', 'reserved', 'confirmed', 'handed_over', 'cancelled', 'no_show'])
  ) as m (machine_id, statuses), unnest(m.statuses) as s (status);

insert into kc_private.fsm_edge (machine_id, from_status, to_status, role)
select e.machine_id, e.from_status, e.to_status, r.role
  from (values
    -- Items, food, animals, knowledge: request → approval → handed over.
    ('giving_handoff', 'reserved', 'confirmed', array['owner']),
    -- The owner names a member who was still waiting as the one who received it.
    ('giving_handoff', 'reserved', 'handed_over', array['owner']),
    ('giving_handoff', 'reserved', 'cancelled', array['owner', 'recipient', 'system']),
    ('giving_handoff', 'confirmed', 'handed_over', array['owner', 'recipient']),
    ('giving_handoff', 'confirmed', 'cancelled', array['owner', 'recipient', 'system']),
    ('giving_handoff', 'confirmed', 'no_show', array['system']),
    -- The delivery is taken back: the owner reopens the post (FR-CLOSURE-005) or the
    -- recipient removes their own mark (FR-CLOSURE-007).
    ('giving_handoff', 'handed_over', 'cancelled', array['owner', 'recipient']),
    -- Rides: the driver approves, either side completes the trip, the driver may reinstate a
    -- booking they declined or cancelled.
    ('ride_booking', 'reserved', 'confirmed', array['owner']),
    ('ride_booking', 'reserved', 'handed_over', array['owner']),
    ('ride_booking', 'reserved', 'cancelled', array['owner', 'recipient', 'system']),
    ('ride_booking', 'confirmed', 'handed_over', array['owner', 'recipient']),
    ('ride_booking', 'confirmed', 'cancelled', array['owner', 'recipient', 'system']),
    ('ride_booking', 'cancelled', 'reserved', array['owner']),
    ('ride_booking', 'cancelled', 'confirmed', array['owner']),
    -- Housing: the host decides, completes the stay or reports a guest who did not arrive.
    ('housing_booking', 'reserved', 'confirmed', array['owner']),
    ('housing_booking', 'reserved', 'cancelled', array['owner', 'recipient', 'system']),
    ('housing_booking', 'confirmed', 'handed_over', array['owner']),
    ('housing_booking', 'confirmed', 'cancelled', array['owner', 'recipient', 'system']),
    ('housing_booking', 'confirmed', 'no_show', array['owner']),
    -- Events: a freed seat promotes the waiting list; the organizer marks attendance and
    -- may correct a no-show.
    ('event_registration', 'waitlisted', 'reserved', array['system']),
    ('event_registration', 'waitlisted', 'confirmed', array['system']),
    ('event_registration', 'waitlisted', 'cancelled', array['owner', 'recipient', 'system']),
    ('event_registration', 'reserved', 'confirmed', array['owner', 'system']),
    ('event_registration', 'reserved', 'cancelled', array['owner', 'recipient', 'system']),
    ('event_registration', 'confirmed', 'handed_over', array['owner']),
    ('event_registration', 'confirmed', 'cancelled', array['owner', 'recipient', 'system']),
    ('event_registration', 'confirmed', 'no_show', array['owner']),
    ('event_registration', 'no_show', 'handed_over', array['owner'])
  ) as e (machine_id, from_status, to_status, roles), unnest(e.roles) as r (role);

create table public.post_handoffs (
  id                      uuid primary key default gen_random_uuid(),
  post_id                 uuid not null references public.posts (id) on delete cascade,
  -- Owner of the post, copied on insert so that access is decided on this row alone.
  owner_id                uuid not null references public.users (id) on delete cascade,
  -- The other member: who reserves, books, registers, or is named by the owner.
  recipient_id            uuid not null references public.users (id) on delete cascade,
  -- Machine that rules `status`, derived from the post type on insert.
  machine_id              text not null,
  status                  text not null default 'reserved',
  -- Why a cancelled handoff ended. Present exactly while the status is `cancelled`.
  cancel_reason           text check (cancel_reason in (
                            'declined', 'expired', 'owner_cancelled', 'recipient_cancelled',
                            'passenger_cancelled', 'driver_cancelled', 'guest_cancelled', 'host_cancelled',
                            'not_completed', 'superseded', 'system', 'post_deleted', 'reopened', 'unmarked')),
  pickup_mode             text not null default 'pickup' check (pickup_mode in ('pickup', 'delivery')),
  -- When the item is collected; a confirmed pickup long past its window is a no-show.
  pickup_window_start     timestamptz,
  pickup_window_end       timestamptz,
  -- The booked time: a lesson slot, a stay from check-in to check-out, an event.
  slot_starts_at          timestamptz,
  slot_ends_at            timestamptz,
  -- Seats of a ride, guests of a stay; 1 everywhere else.
  seats                   integer not null default 1 check (seats between 1 and 8),
  -- A reservation the owner has not answered by this time lapses.
  confirm_by              timestamptz,
  -- Meeting place a passenger asked for when booking (FR-RIDE-030).
  requested_meeting_point jsonb check (
                            jsonb_typeof(requested_meeting_point) = 'object'
                            and requested_meeting_point ?& array['kind', 'id', 'label']),
  created_at              timestamptz not null default now(),
  confirmed_at            timestamptz,
  handed_over_at          timestamptz,
  cancelled_at            timestamptz,
  no_show_at              timestamptz,
  updated_at              timestamptz not null default now(),
  constraint post_handoffs_distinct_members_chk check (owner_id <> recipient_id),
  constraint post_handoffs_pickup_window_chk check (pickup_window_end >= pickup_window_start),
  constraint post_handoffs_slot_chk check (slot_ends_at > slot_starts_at),
  constraint post_handoffs_cancel_reason_chk check ((status = 'cancelled') = (cancel_reason is not null))
);
comment on table public.post_handoffs is
  'Closing stage of every post: who takes it, when, how many seats, and how it ended. Written only by server code.';

-- A member holds at most one live handoff on a post.
create unique index post_handoffs_live_member_key on public.post_handoffs (post_id, recipient_id)
  where status in ('waitlisted', 'reserved', 'confirmed');
-- Seat arithmetic, the "has a live handoff" guards and the roster of a post; covers post_id.
create index post_handoffs_post_status_idx on public.post_handoffs (post_id, status);
-- "My requests and bookings", newest first; covers recipient_id.
create index post_handoffs_recipient_recent_idx on public.post_handoffs (recipient_id, created_at desc, id desc);
-- Requests waiting on the owner and their history, newest first; covers owner_id.
create index post_handoffs_owner_recent_idx on public.post_handoffs (owner_id, created_at desc, id desc);
-- Expiry sweep: unanswered reservations past their deadline.
create index post_handoffs_confirm_due_idx on public.post_handoffs (confirm_by) where status = 'reserved';
-- No-show sweep: confirmed pickups past their window.
create index post_handoffs_pickup_due_idx on public.post_handoffs (pickup_window_end)
  where status = 'confirmed' and machine_id = 'giving_handoff';

-- Guards every write of a handoff.
--   insert   copies the owner and the machine from the post; the status must be a state of
--            that machine
--   status   the move must be an edge of the row's machine for the role stated in the
--            transaction-local setting `kc.fsm_role`
-- and stamps the time of each state, so no writer can forget it.
create function kc_private.post_handoffs_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_from constant text := case tg_op when 'UPDATE' then old.status end;
begin
  if tg_op = 'INSERT' then
    select p.owner_id, kc_private.handoff_machine_of(p.post_type)
      into strict new.owner_id, new.machine_id
      from public.posts p where p.id = new.post_id;
    perform kc_private.fsm_assert_transition(new.machine_id, new.status, new.status);
  elsif new.status is distinct from old.status then
    perform kc_private.fsm_assert_transition(
      new.machine_id, old.status, new.status, nullif(current_setting('kc.fsm_role', true), ''));
  else
    return new;
  end if;

  -- A booking brought back from `cancelled`, or a corrected no-show, forgets how it ended.
  if new.status <> 'cancelled' then
    new.cancelled_at := null;
    new.cancel_reason := null;
  end if;
  if new.status <> 'no_show' then
    new.no_show_at := null;
  end if;
  case new.status
    when 'confirmed' then new.confirmed_at := now();
    when 'handed_over' then new.handed_over_at := now();
    when 'cancelled' then new.cancelled_at := now(); new.handed_over_at := null;
    when 'no_show' then new.no_show_at := now();
    else null;
  end case;
  if v_from = 'cancelled' and new.status = 'reserved' then
    new.confirmed_at := null;
  end if;
  return new;
end;
$$;
comment on function kc_private.post_handoffs_guard() is
  'BEFORE INSERT OR UPDATE OF status on post_handoffs: owner and machine from the post, legal move for the acting role, state timestamps.';

create trigger post_handoffs_guard
  before insert or update of status on public.post_handoffs
  for each row execute function kc_private.post_handoffs_guard();

create trigger post_handoffs_set_updated_at
  before update on public.post_handoffs
  for each row execute function kc_private.set_updated_at();

alter table public.post_handoffs enable row level security;
alter table public.post_handoffs force row level security;

-- Only the two members of a handoff ever see it. No write policy and no write grant exist:
-- every change goes through an RPC.
create policy post_handoffs_select_party on public.post_handoffs
  for select to authenticated
  using (owner_id = (select auth.uid()) or recipient_id = (select auth.uid()));

grant select on public.post_handoffs to authenticated;

-- The other member of a handoff reads the post whatever its audience (FR-POST-017): a
-- follower-only or private post stays readable to the member who reserved or received it.
-- Status and owner visibility are the same conditions as for every other reader.
create policy posts_select_handoff_party on public.posts
  for select to authenticated
  using (
    status in ('open', 'closed_delivered')
    and exists (select 1 from public.post_handoffs h
                 where h.post_id = posts.id and h.recipient_id = (select auth.uid())
                   and h.status <> 'cancelled')
    and exists (select 1 from public.users u where u.id = posts.owner_id));

-- >>> supabase/schemas/25_handoffs/020_handoff_internals.sql
-- Handoffs · shared internals
--
-- Building blocks of every handoff RPC, in this module and in the modules that add the
-- ride, housing, event and knowledge flows on top of it. None is callable from a device.

-- May the caller manage (publish, pause, close, reopen, delete) this post? Today: the caller
-- owns it. This is the one place the organizations module (admins of the organization the
-- post belongs to) and the moderation module (super admin) extend (design §12.1).
create function kc_private.can_manage_post(p_post_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.posts p
                  where p.id = p_post_id and p.owner_id = (select auth.uid()));
$$;
comment on function kc_private.can_manage_post(uuid) is
  'Authorization of every post management action: the caller owns the post.';

-- Locks a post the caller may manage and returns it. One error for "no such post" and
-- "not yours", so the existence of a post the caller cannot see is not revealed.
create function kc_private.post_lock_managed(p_post_id uuid)
returns public.posts
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post public.posts;
begin
  perform kc_private.require_active_caller();
  if not kc_private.can_manage_post(p_post_id) then
    raise exception 'post_not_found' using errcode = 'P0001';
  end if;
  select p.* into strict v_post from public.posts p where p.id = p_post_id for update;
  return v_post;
end;
$$;
comment on function kc_private.post_lock_managed(uuid) is
  'Row-locks a post for a management action; raises post_not_found unless the caller may manage it.';

-- Moves a post to a status in the given role, then restores the role that was in force, so
-- a move made in the middle of another move does not change who the outer one acts as.
create function kc_private.post_move(p_post_id uuid, p_to text, p_role text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_outer_role constant text := coalesce(current_setting('kc.fsm_role', true), '');
begin
  perform set_config('kc.fsm_role', p_role, true);
  update public.posts p set status = p_to where p.id = p_post_id;
  perform set_config('kc.fsm_role', v_outer_role, true);
end;
$$;
comment on function kc_private.post_move(uuid, text, text) is 'Moves a post along its machine in the given role.';

-- Moves a handoff to a status in the given role and returns the row.
create function kc_private.handoff_move(
  p_handoff_id uuid,
  p_to text,
  p_role text,
  p_cancel_reason text default null
)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_outer_role constant text := coalesce(current_setting('kc.fsm_role', true), '');
  v_handoff public.post_handoffs;
begin
  perform set_config('kc.fsm_role', p_role, true);
  update public.post_handoffs h
     set status = p_to, cancel_reason = p_cancel_reason
   where h.id = p_handoff_id
  returning h.* into v_handoff;
  perform set_config('kc.fsm_role', v_outer_role, true);
  return v_handoff;
end;
$$;
comment on function kc_private.handoff_move(uuid, text, text, text) is
  'Moves a handoff along its machine in the given role.';

-- Locks a handoff for a move and returns it. The post row is locked first: every writer
-- takes the two locks in this order, so a handoff move and a post closure never deadlock.
create function kc_private.handoff_lock(p_handoff_id uuid)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff public.post_handoffs;
begin
  perform 1 from public.posts p
    where p.id = (select h.post_id from public.post_handoffs h where h.id = p_handoff_id)
      for update;
  select h.* into v_handoff from public.post_handoffs h where h.id = p_handoff_id for update;
  if not found then
    raise exception 'handoff_not_found' using errcode = 'P0001';
  end if;
  return v_handoff;
end;
$$;
comment on function kc_private.handoff_lock(uuid) is 'Row-locks a handoff and its post, post first.';

-- Seats of a post that are held or were used: reserved, confirmed and handed over.
create function kc_private.handoff_seats_taken(p_post_id uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(sum(h.seats), 0)::integer
    from public.post_handoffs h
   where h.post_id = p_post_id and h.status in ('reserved', 'confirmed', 'handed_over');
$$;
comment on function kc_private.handoff_seats_taken(uuid) is 'Seats of a post held by live or completed handoffs.';

-- Does a live handoff stand in the way of pausing or closing the post (D104)? Event
-- registrations never do: they are cancelled with the event instead (D131).
create function kc_private.post_has_active_handoff(p_post_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.post_handoffs h
                  where h.post_id = p_post_id and h.status in ('reserved', 'confirmed')
                    and h.machine_id <> 'event_registration');
$$;
comment on function kc_private.post_has_active_handoff(uuid) is
  'A reserved or confirmed handoff exists on the post, event registrations aside.';

-- Could this member open the post as any other member would: it is open and not past its
-- expiry, its audience includes them, both accounts are active and no block stands between
-- them. The same rule as the read policy on posts, for a member other than the caller.
create function kc_private.post_open_to_member(p_post public.posts, p_member_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_post.status = 'open'
     and (p_post.expires_at is null or p_post.expires_at > now())
     and (p_post.visibility = 'Public'
          or (p_post.visibility = 'FollowersOnly'
              and exists (select 1 from public.follows f
                           where f.follower_id = p_member_id and f.followed_id = p_post.owner_id)))
     and (select count(*) from public.users u
           where u.id in (p_member_id, p_post.owner_id) and u.is_active) = 2
     and not kc_access.is_blocked_between(p_member_id, p_post.owner_id);
$$;
comment on function kc_private.post_open_to_member(public.posts, uuid) is
  'The post is open and visible to the given member, and neither side is blocked or inactive.';

-- Creates a handoff on an open post for a member, in the given starting status.
--   own_listing            the member owns the post
--   listing_not_available  the post is not open to that member (closed, hidden, expired,
--                          outside its audience, or a block between the two)
--   item_already_reserved  the member already holds a live handoff on the post
--   p_full_error           the seats asked for do not fit under p_capacity (null = no limit);
--                          a `waitlisted` row takes no seat and is never refused for capacity
-- The post row lock serializes competing reservations, so capacity cannot be exceeded.
create function kc_private.handoff_open(
  p_post_id uuid,
  p_recipient_id uuid,
  p_status text,
  p_capacity integer,
  p_seats integer default 1,
  p_fields jsonb default '{}'::jsonb,
  p_full_error text default 'seats_exhausted'
)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post public.posts;
  v_handoff public.post_handoffs;
begin
  select p.* into v_post from public.posts p where p.id = p_post_id for update;
  if found and v_post.owner_id = p_recipient_id then
    raise exception 'own_listing' using errcode = 'P0001';
  end if;
  if not found or not kc_private.post_open_to_member(v_post, p_recipient_id) then
    raise exception 'listing_not_available' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.post_handoffs h
              where h.post_id = p_post_id and h.recipient_id = p_recipient_id
                and h.status in ('waitlisted', 'reserved', 'confirmed')) then
    raise exception 'item_already_reserved' using errcode = 'P0001';
  end if;
  if p_status <> 'waitlisted'
     and kc_private.handoff_seats_taken(p_post_id) + p_seats > p_capacity then
    raise exception '%', p_full_error using errcode = 'P0001';
  end if;

  -- p_fields carries the optional columns by name: pickup_mode, pickup_window_start,
  -- pickup_window_end, slot_starts_at, slot_ends_at, confirm_by, requested_meeting_point.
  insert into public.post_handoffs (
    post_id, recipient_id, status, seats, pickup_mode, pickup_window_start, pickup_window_end,
    slot_starts_at, slot_ends_at, confirm_by, requested_meeting_point)
  values (
    p_post_id, p_recipient_id, p_status, p_seats,
    coalesce(p_fields ->> 'pickup_mode', 'pickup'),
    (p_fields ->> 'pickup_window_start')::timestamptz, (p_fields ->> 'pickup_window_end')::timestamptz,
    (p_fields ->> 'slot_starts_at')::timestamptz, (p_fields ->> 'slot_ends_at')::timestamptz,
    (p_fields ->> 'confirm_by')::timestamptz, p_fields -> 'requested_meeting_point')
  returning * into v_handoff;
  return v_handoff;
end;
$$;
comment on function kc_private.handoff_open(uuid, uuid, text, integer, integer, jsonb, text) is
  'Creates a handoff on an open post under the post row lock, enforcing visibility, one live handoff per member and capacity.';

-- Promotes the head of an event's waiting list into seats that became free: the oldest
-- waiting registrations move to p_to_status (`confirmed`, or `reserved` when the organizer
-- approves by hand) while they fit under p_capacity. Called by the events module, which
-- knows the capacity and the registration policy, whenever a seat is freed.
create function kc_private.handoff_promote_waitlist(p_post_id uuid, p_capacity integer, p_to_status text)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_next public.post_handoffs;
  v_promoted integer := 0;
begin
  perform 1 from public.posts p where p.id = p_post_id for update;
  for v_next in
    select h.* from public.post_handoffs h
     where h.post_id = p_post_id and h.status = 'waitlisted'
     order by h.created_at, h.id
  loop
    exit when kc_private.handoff_seats_taken(p_post_id) + v_next.seats > p_capacity;
    perform kc_private.handoff_move(v_next.id, p_to_status, 'system');
    v_promoted := v_promoted + 1;
  end loop;
  return v_promoted;
end;
$$;
comment on function kc_private.handoff_promote_waitlist(uuid, integer, text) is
  'Moves waiting event registrations into free seats, oldest first; returns how many were promoted.';

-- >>> supabase/schemas/25_handoffs/030_handoff_effects.sql
-- Handoffs · consequences of a status change
--
-- Whatever RPC or sweep moves a handoff, in whatever world, the same three things follow
-- from the new status, so they are attached to the table and not repeated in each writer:
--   1. the counterparty's profile counter (FR-CLOSURE-009 AC2)
--   2. a `karma` event — karma itself is computed by its own module
--   3. `notification` events for the member or members who did not make the change

-- Notification kind for a handoff change, or null when nobody is told. Kinds carry the
-- machine as a prefix (`giving_handoff_confirmed`, `ride_booking_confirmed`, …), except the
-- two that concern the recipient mark of a closed post (FR-NOTIF-009, FR-NOTIF-010).
create function kc_private.handoff_notification_kind(
  p_old public.post_handoffs,
  p_new public.post_handoffs,
  p_actor_id uuid
)
returns text
language sql
stable
set search_path = ''
as $$
  select case
    when p_old.id is null and p_new.status = 'handed_over' then 'mark_recipient'
    when p_new.cancel_reason = 'unmarked' then 'unmark_recipient'
    -- Reopening a delivered post tells nobody (FR-NOTIF-013).
    when p_new.cancel_reason = 'reopened' then null
    else p_new.machine_id || '_' || case
      -- A new handoff: a request waiting for the owner, or a seat taken at once.
      when p_old.id is null and p_new.status = 'reserved' then 'requested'
      when p_old.id is null and p_new.status = 'confirmed' and p_actor_id = p_new.recipient_id then 'claimed'
      when p_old.id is null and p_new.status = 'waitlisted' then null
      when p_old.status = 'waitlisted' and p_new.status in ('reserved', 'confirmed') then 'waitlist_promoted'
      when p_old.status = 'cancelled' then 'reinstated'
      when p_new.status = 'confirmed' then 'confirmed'
      when p_new.status = 'handed_over' then 'completed'
      when p_new.status = 'no_show' then 'no_show'
      when p_new.cancel_reason = 'expired' then 'expired'
      when p_new.cancel_reason = 'declined' then 'declined'
      when p_new.status = 'cancelled' then 'cancelled'
    end
  end;
$$;
comment on function kc_private.handoff_notification_kind(public.post_handoffs, public.post_handoffs, uuid) is
  'Notification kind of a handoff insert (p_old null) or status change; null = no notification.';

create function kc_private.post_handoffs_apply_effects()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_old public.post_handoffs;
  -- The member whose call made the change; null for a sweep or other server work.
  v_actor_id constant uuid := (select auth.uid());
  -- +1 when the handoff becomes handed over, -1 when a delivery is taken back.
  v_delta constant integer := (new.status = 'handed_over')::integer
    - (tg_op = 'UPDATE' and old.status = 'handed_over')::integer;
  v_post public.posts;
  v_kind text;
  v_to uuid;
begin
  if tg_op = 'UPDATE' then
    if new.status = old.status then
      return null;
    end if;
    v_old := old;
  end if;
  select p.* into v_post from public.posts p where p.id = new.post_id;

  if v_delta <> 0 then
    -- On an offer the other member receives; on a request the other member gives.
    update public.user_stats s
       set items_received_count = greatest(
             s.items_received_count + case v_post.direction when 'offer' then v_delta else 0 end, 0),
           items_given_count = greatest(
             s.items_given_count + case v_post.direction when 'request' then v_delta else 0 end, 0)
     where s.user_id = new.recipient_id;

    perform kc_private.outbox_enqueue('karma', jsonb_build_object(
      'kind', case v_delta when 1 then 'handoff_completed' else 'handoff_reverted' end,
      'handoff_id', new.id, 'post_id', new.post_id, 'owner_id', new.owner_id,
      'recipient_id', new.recipient_id, 'world_slug', v_post.world_slug,
      'post_type', v_post.post_type, 'direction', v_post.direction, 'seats', new.seats));
  end if;

  v_kind := kc_private.handoff_notification_kind(v_old, new, v_actor_id);
  if v_kind is null then
    return null;
  end if;
  -- Both members, minus the one who acted (FR-NOTIF-018 AC5): a request reaches the owner,
  -- a mark reaches the member who was marked, a sweep's change reaches both.
  foreach v_to in array array[new.owner_id, new.recipient_id] loop
    continue when v_to is not distinct from v_actor_id;
    perform kc_private.outbox_enqueue('notification', jsonb_build_object(
      'kind', v_kind, 'recipient_id', v_to, 'actor_id', v_actor_id,
      'entity', jsonb_build_object('type', 'post_handoff', 'id', new.id),
      'data', jsonb_build_object(
        'post_id', new.post_id, 'world_slug', v_post.world_slug, 'status', new.status,
        'cancel_reason', new.cancel_reason,
        -- One delivery per kind, handoff and addressee, however often the event is retried.
        'dedupe_key', v_kind || ':' || new.id || ':' || v_to)));
  end loop;
  return null;
end;
$$;
comment on function kc_private.post_handoffs_apply_effects() is
  'AFTER INSERT OR UPDATE OF status on post_handoffs: counterparty counter, karma event, notifications.';

create trigger post_handoffs_apply_effects
  after insert or update of status on public.post_handoffs
  for each row
  execute function kc_private.post_handoffs_apply_effects();

-- >>> supabase/schemas/25_handoffs/040_handoff_rpcs.sql
-- Handoffs · the generic flow (items, food, animals; knowledge for confirm / hand over / cancel)
--
-- reserve → (owner confirms) → handed over, or cancelled by either side. Rides, stays and
-- events have their own RPCs, built on the same internals, in the module that owns their
-- detail tables. Errors: SQLSTATE P0001 with a stable snake_case message.

-- How a member takes an offer of this world, when one member takes the whole post:
--   'request'  the owner approves within 24 hours (items; animals for adoption or foster)
--   'claim'    confirmed at once, first come first served (food)
--   null       the world has its own flow, or several members take part
create function kc_private.handoff_flow_of(p_world_slug text, p_kind_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select case
    when p_world_slug = 'items' then 'request'
    when p_world_slug = 'food' then 'claim'
    when p_world_slug = 'animals' and exists (
           select 1 from public.post_kinds k
            where k.id = p_kind_id and k.slug in ('adoption_offer', 'foster_offer')) then 'request'
  end;
$$;
comment on function kc_private.handoff_flow_of(text, uuid) is
  'Generic single-taker flow of a world and post kind: request, claim, or null when the world has its own flow.';

-- Shared body of the two entry points below.
create function kc_private.handoff_take_offer(
  p_post_id uuid,
  p_flow text,
  p_pickup_mode text,
  p_pickup_window_start timestamptz,
  p_pickup_window_end timestamptz
)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_pickup_mode constant text := coalesce(nullif(btrim(p_pickup_mode), ''), 'pickup');
  v_post public.posts;
begin
  if v_pickup_mode not in ('pickup', 'delivery') then
    raise exception 'invalid_pickup_mode' using errcode = 'P0001';
  end if;
  select p.* into v_post from public.posts p where p.id = p_post_id for update;
  if not found or v_post.direction <> 'offer'
     or kc_private.handoff_flow_of(v_post.world_slug, v_post.kind_id) is distinct from p_flow then
    raise exception 'listing_not_available' using errcode = 'P0001';
  end if;

  return kc_private.handoff_open(
    p_post_id, v_user_id,
    case p_flow when 'claim' then 'confirmed' else 'reserved' end,
    1, 1,
    jsonb_strip_nulls(jsonb_build_object(
      'pickup_mode', v_pickup_mode,
      -- A claim is collected now unless the claimer names a time, and by the post's expiry.
      'pickup_window_start', coalesce(p_pickup_window_start, case p_flow when 'claim' then now() end),
      'pickup_window_end', coalesce(p_pickup_window_end,
        case p_flow when 'claim' then coalesce(v_post.expires_at, now() + interval '4 hours') end),
      'confirm_by', case p_flow when 'request' then now() + interval '24 hours' end)),
    case p_flow when 'claim' then 'listing_not_available' else 'item_already_reserved' end);
end;
$$;
comment on function kc_private.handoff_take_offer(uuid, text, text, timestamptz, timestamptz) is
  'Creates the caller''s handoff on a single-taker offer in the given flow.';

-- Asks for an item (or an animal offered for adoption or foster). The owner has 24 hours
-- to approve; meanwhile nobody else can ask.
create function public.reserve_item_giving(
  p_post_id uuid,
  p_pickup_mode text default 'pickup',
  p_pickup_window_start timestamptz default null,
  p_pickup_window_end timestamptz default null
)
returns public.post_handoffs
language sql
security definer
set search_path = ''
as $$
  select kc_private.handoff_take_offer(
    p_post_id, 'request', p_pickup_mode, p_pickup_window_start, p_pickup_window_end);
$$;
comment on function public.reserve_item_giving(uuid, text, timestamptz, timestamptz) is
  'The caller asks for an item or animal offer; the owner approves within 24 hours.';
grant execute on function public.reserve_item_giving(uuid, text, timestamptz, timestamptz) to authenticated;

-- Claims a food offer: confirmed at once, first come first served.
create function public.claim_food_giving(
  p_post_id uuid,
  p_pickup_window_start timestamptz default null,
  p_pickup_window_end timestamptz default null
)
returns public.post_handoffs
language sql
security definer
set search_path = ''
as $$
  select kc_private.handoff_take_offer(p_post_id, 'claim', 'pickup', p_pickup_window_start, p_pickup_window_end);
$$;
comment on function public.claim_food_giving(uuid, timestamptz, timestamptz) is
  'The caller claims a food offer; the claim is confirmed immediately.';
grant execute on function public.claim_food_giving(uuid, timestamptz, timestamptz) to authenticated;

-- The owner approves a waiting request.
create function public.confirm_item_handoff(p_handoff_id uuid)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_handoff constant public.post_handoffs := kc_private.handoff_lock(p_handoff_id);
begin
  if v_handoff.owner_id <> v_user_id or v_handoff.status <> 'reserved'
     or v_handoff.machine_id <> 'giving_handoff' then
    raise exception 'handoff_not_found' using errcode = 'P0001';
  end if;
  return kc_private.handoff_move(p_handoff_id, 'confirmed', 'owner');
end;
$$;
comment on function public.confirm_item_handoff(uuid) is 'The post owner approves a waiting request.';
grant execute on function public.confirm_item_handoff(uuid) to authenticated;

-- Closes a post whose single taker has received it: the post becomes `closed_delivered`.
-- Only a post that is still open is closed; an expired, removed or under-review post keeps
-- its status and the handoff stands. Worlds where several members take part are closed by
-- their own module.
create function kc_private.post_close_after_handoff(p_handoff public.post_handoffs)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1 from public.posts p
              where p.id = p_handoff.post_id and p.status = 'open'
                and kc_private.handoff_flow_of(p.world_slug, p.kind_id) is not null) then
    perform kc_private.post_move(p_handoff.post_id, 'closed_delivered', 'system');
  end if;
end;
$$;
comment on function kc_private.post_close_after_handoff(public.post_handoffs) is
  'Moves an open single-taker post to closed_delivered once its handoff is handed over.';

-- Either member marks a confirmed handoff as handed over.
create function public.mark_giving_handed_over(p_handoff_id uuid)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_handoff public.post_handoffs := kc_private.handoff_lock(p_handoff_id);
begin
  if v_user_id not in (v_handoff.owner_id, v_handoff.recipient_id) then
    raise exception 'handoff_not_found' using errcode = 'P0001';
  end if;
  if v_handoff.machine_id <> 'giving_handoff' then
    raise exception 'handoff_world_not_supported' using errcode = 'P0001';
  end if;
  if v_handoff.status <> 'confirmed' then
    raise exception 'handoff_not_confirmed' using errcode = 'P0001';
  end if;

  v_handoff := kc_private.handoff_move(
    p_handoff_id, 'handed_over', case v_user_id when v_handoff.owner_id then 'owner' else 'recipient' end);
  perform kc_private.post_close_after_handoff(v_handoff);
  return v_handoff;
end;
$$;
comment on function public.mark_giving_handed_over(uuid) is
  'Either member marks a confirmed handoff as handed over; a single-taker post closes as delivered.';
grant execute on function public.mark_giving_handed_over(uuid) to authenticated;

-- Either member cancels a waiting or confirmed handoff. The reason records who: the owner
-- declining a request, the owner withdrawing an approval, or the other member backing out.
-- The seat is free again at once.
create function public.cancel_giving_handoff(p_handoff_id uuid)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_handoff constant public.post_handoffs := kc_private.handoff_lock(p_handoff_id);
  v_by_owner constant boolean := v_user_id = v_handoff.owner_id;
begin
  if v_user_id not in (v_handoff.owner_id, v_handoff.recipient_id)
     or v_handoff.status not in ('reserved', 'confirmed') then
    raise exception 'handoff_not_found' using errcode = 'P0001';
  end if;
  -- Rides, stays and events cancel through their own RPCs (late-cancel rules, waiting list).
  if v_handoff.machine_id <> 'giving_handoff' then
    raise exception 'handoff_world_not_supported' using errcode = 'P0001';
  end if;

  return kc_private.handoff_move(
    p_handoff_id, 'cancelled',
    case when v_by_owner then 'owner' else 'recipient' end,
    case when not v_by_owner then 'recipient_cancelled'
         when v_handoff.status = 'reserved' then 'declined'
         else 'owner_cancelled' end);
end;
$$;
comment on function public.cancel_giving_handoff(uuid) is
  'Either member cancels their waiting or confirmed handoff.';
grant execute on function public.cancel_giving_handoff(uuid) to authenticated;

-- >>> supabase/schemas/25_handoffs/050_post_closures.sql
-- Handoffs · closure bookkeeping of a post
--
-- What a closed post needs beyond its status: whether it counts as a delivery in its
-- owner's profile counter, when a post closed without a recipient is purged, and how often
-- it was reopened. A row appears the first time a post is closed or deleted.

create table public.post_closures (
  post_id       uuid primary key references public.posts (id) on delete cascade,
  -- The closure was a delivery — "close without marking" after handing the item over, or a
  -- recipient who removed their mark — as opposed to the owner deleting the post. Decides
  -- whether a `deleted_no_recipient` post counts in the owner's counter (FR-CLOSURE-009).
  delivered     boolean not null default false,
  -- End of the grace period of a `deleted_no_recipient` post (FR-CLOSURE-003 AC6): until
  -- then the owner may reopen it, afterwards the purge job deletes it (FR-CLOSURE-008).
  purge_after   timestamptz,
  -- Successful reopens; five or more flag the post for review (FR-CLOSURE-010).
  reopen_count  integer not null default 0 check (reopen_count >= 0),
  updated_at    timestamptz not null default now()
);
comment on table public.post_closures is
  'Closure state of a post: delivery flag, purge deadline, reopen count. Written only by server code.';

-- Purge job: posts whose grace period has ended.
create index post_closures_purge_due_idx on public.post_closures (purge_after) where purge_after is not null;

create trigger post_closures_set_updated_at
  before update on public.post_closures
  for each row execute function kc_private.set_updated_at();

alter table public.post_closures enable row level security;
alter table public.post_closures force row level security;

-- The owner sees how long a deleted post can still be restored. The subquery runs under
-- the caller's access to `posts`.
create policy post_closures_select_owner on public.post_closures
  for select to authenticated
  using (exists (select 1 from public.posts p
                  where p.id = post_closures.post_id and p.owner_id = (select auth.uid())));

-- The reopen count is an internal moderation signal (FR-CLOSURE-010 AC3) and is not readable.
grant select (post_id, delivered, purge_after) on public.post_closures to authenticated;

-- Follows every status change of a post, whoever makes it (owner RPC, sweep, moderation):
--   1. owner's counter — a post counts while it is `closed_delivered`, or
--      `deleted_no_recipient` after a delivery; on an offer the owner gave, on a request
--      the owner received (FR-CLOSURE-009 AC1)
--   2. purge deadline — seven days from entering `deleted_no_recipient`, cleared on leaving
--   3. reopen — counted; from the fifth on, a `moderation` event flags the post
--   4. chats — a `chat_system_message` event when an open post closes (FR-CLOSURE-001 AC4)
--   5. handoffs — a post that leaves the air takes its live handoffs with it
create function kc_private.posts_apply_closure_effects()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_closure public.post_closures;
  v_delta integer;
  v_reopened constant boolean :=
    old.status in ('closed_delivered', 'deleted_no_recipient') and new.status = 'open';
  v_handoff public.post_handoffs;
begin
  if new.status = old.status then
    return null;
  end if;

  if new.status = 'deleted_no_recipient' or v_reopened then
    insert into public.post_closures as c (post_id, delivered, purge_after, reopen_count)
    values (new.id, old.status = 'closed_delivered',
            case when not v_reopened then now() + interval '7 days' end, v_reopened::integer)
    on conflict (post_id) do update
      set delivered = c.delivered or excluded.delivered,
          purge_after = excluded.purge_after,
          reopen_count = c.reopen_count + excluded.reopen_count
    returning c.* into v_closure;
  else
    update public.post_closures c set purge_after = null
     where c.post_id = new.id returning c.* into v_closure;
  end if;

  -- 1. Owner's counter.
  v_delta := (new.status = 'closed_delivered'
              or (new.status = 'deleted_no_recipient' and coalesce(v_closure.delivered, false)))::integer
           - (old.status = 'closed_delivered'
              or (old.status = 'deleted_no_recipient' and coalesce(v_closure.delivered, false)))::integer;
  if v_delta <> 0 then
    update public.user_stats s
       set items_given_count = greatest(
             s.items_given_count + case new.direction when 'offer' then v_delta else 0 end, 0),
           items_received_count = greatest(
             s.items_received_count + case new.direction when 'request' then v_delta else 0 end, 0)
     where s.user_id = new.owner_id;
  end if;

  -- 3. A reopened post starts over as not delivered.
  if v_reopened then
    update public.post_closures c set delivered = false where c.post_id = new.id;
    if v_closure.reopen_count >= 5 then
      perform kc_private.outbox_enqueue('moderation', jsonb_build_object(
        'kind', 'excessive_reopens', 'post_id', new.id, 'owner_id', new.owner_id,
        'reopen_count', v_closure.reopen_count));
    end if;
  end if;

  -- 4. Chats anchored to the post get a closing line and lose their anchor.
  if old.status = 'open' and new.status in ('closed_delivered', 'deleted_no_recipient') then
    perform kc_private.outbox_enqueue('chat_system_message', jsonb_build_object(
      'kind', 'post_closed', 'post_id', new.id, 'status', new.status, 'owner_id', new.owner_id,
      'recipient_id', (select h.recipient_id from public.post_handoffs h
                        where h.post_id = new.id and h.status = 'handed_over'
                        order by h.handed_over_at desc limit 1)));
  end if;

  -- 5. Live handoffs end with the post. An event that already started keeps its
  --    registrations, so that attendance can still be marked (D128, D131). A pause only
  --    reaches event registrations: any other live handoff refuses the pause (D104).
  if new.status in ('paused', 'closed_delivered', 'deleted_no_recipient', 'expired', 'removed_admin') then
    for v_handoff in
      select h.* from public.post_handoffs h
       where h.post_id = new.id and h.status in ('waitlisted', 'reserved', 'confirmed')
         and (h.machine_id <> 'event_registration' or lower(new.time_window) > now()
              or new.time_window is null)
         and (new.status <> 'paused' or h.machine_id = 'event_registration')
    loop
      perform kc_private.handoff_move(
        v_handoff.id, 'cancelled', 'system',
        case when new.status = 'closed_delivered' then 'superseded'
             when coalesce(current_setting('kc.fsm_role', true), '') = 'owner' then 'host_cancelled'
             else 'system' end);
    end loop;
  end if;
  return null;
end;
$$;
comment on function kc_private.posts_apply_closure_effects() is
  'AFTER UPDATE OF status on posts: owner counter, purge deadline, reopen count, chat event, cancellation of live handoffs.';

create trigger posts_apply_closure_effects
  after update of status on public.posts
  for each row execute function kc_private.posts_apply_closure_effects();

-- Posts closed without a recipient whose grace period has ended, oldest first, for the
-- purge job (it removes the media files, then the post).
create function kc_private.posts_due_for_purge(p_limit integer default 100)
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select c.post_id
    from public.post_closures c
    join public.posts p on p.id = c.post_id
   where c.purge_after <= now() and p.status = 'deleted_no_recipient'
   order by c.purge_after
   limit least(greatest(p_limit, 1), 1000);
$$;
comment on function kc_private.posts_due_for_purge(integer) is
  'Ids of deleted_no_recipient posts past their seven-day grace period.';

-- >>> supabase/schemas/25_handoffs/060_post_owner_actions.sql
-- Handoffs · post management actions (publish, pause, resume, delete)
--
-- A device has no UPDATE privilege on posts.status: these are the named moves. Each one
-- asks kc_private.can_manage_post — today the owner; later also an admin of the post's
-- organization and the super admin — and then acts in the machine role `owner`.
-- Errors: SQLSTATE P0001 — post_not_found, listing_wrong_status, listing_has_active_handoff,
-- and whatever the post machine itself refuses (post_limit_exceeded, post_expired).

-- A delivered post may be deleted by its manager like any other (design §12.1); the
-- machine of the posts module only had this edge for the recipient un-mark (`system`).
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('post', 'closed_delivered', 'deleted_no_recipient', 'owner');

-- Publishes a draft.
create function public.publish_post(p_post_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post constant public.posts := kc_private.post_lock_managed(p_post_id);
begin
  if v_post.status <> 'draft' then
    raise exception 'listing_wrong_status' using errcode = 'P0001';
  end if;
  perform kc_private.post_move(p_post_id, 'open', 'owner');
end;
$$;
comment on function public.publish_post(uuid) is 'Publishes a draft post (draft → open).';
grant execute on function public.publish_post(uuid) to authenticated;

-- Takes an open post off the air without closing it (D104). A reserved or confirmed
-- handoff refuses the pause; registrations of an event that has not started are cancelled
-- and each attendee is notified (D131).
create function public.pause_post(p_post_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post constant public.posts := kc_private.post_lock_managed(p_post_id);
begin
  if v_post.status <> 'open' then
    raise exception 'listing_wrong_status' using errcode = 'P0001';
  end if;
  if kc_private.post_has_active_handoff(p_post_id) then
    raise exception 'listing_has_active_handoff' using errcode = 'P0001';
  end if;
  perform kc_private.post_move(p_post_id, 'paused', 'owner');
end;
$$;
comment on function public.pause_post(uuid) is
  'Pauses an open post; refused while a handoff is live, event registrations aside.';
grant execute on function public.pause_post(uuid) to authenticated;

-- Puts a paused post back on the air; refused after its expiry and beyond the open-post limit.
create function public.resume_post(p_post_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post constant public.posts := kc_private.post_lock_managed(p_post_id);
begin
  if v_post.status <> 'paused' then
    raise exception 'listing_wrong_status' using errcode = 'P0001';
  end if;
  perform kc_private.post_move(p_post_id, 'open', 'owner');
end;
$$;
comment on function public.resume_post(uuid) is 'Resumes a paused post (paused → open).';
grant execute on function public.resume_post(uuid) to authenticated;

-- Deletes a published post in any status (design §12.1), also while members are
-- registered or a handoff is live: every live handoff is cancelled with the reason
-- `post_deleted` and its member is notified, then the post becomes `deleted_no_recipient`.
-- Nothing is destroyed yet: the purge job removes the post after seven days, and until
-- then public.reopen_post brings it back. A draft is deleted directly (it was never
-- published); a post removed by moderation is not the owner's to delete.
create function public.delete_post(p_post_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post constant public.posts := kc_private.post_lock_managed(p_post_id);
  v_handoff_id uuid;
begin
  if v_post.status = 'draft' then
    delete from public.posts p where p.id = p_post_id;
    return;
  end if;
  if v_post.status in ('removed_admin', 'deleted_no_recipient') then
    raise exception 'listing_wrong_status' using errcode = 'P0001';
  end if;

  for v_handoff_id in
    select h.id from public.post_handoffs h
     where h.post_id = p_post_id and h.status in ('waitlisted', 'reserved', 'confirmed')
  loop
    perform kc_private.handoff_move(v_handoff_id, 'cancelled', 'owner', 'post_deleted');
  end loop;
  perform kc_private.post_move(p_post_id, 'deleted_no_recipient', 'owner');
end;
$$;
comment on function public.delete_post(uuid) is
  'Deletes a post in any status: cancels and notifies its live handoffs, then moves it to deleted_no_recipient until the purge.';
grant execute on function public.delete_post(uuid) to authenticated;

-- >>> supabase/schemas/25_handoffs/070_post_closure_rpcs.sql
-- Handoffs · closing and reopening a post (FR-CLOSURE-*)
--
-- "Mark as delivered" ends in one of two ways: with a named member (`closed_delivered`) or
-- without one (`deleted_no_recipient`, purged after seven days). Both can be reopened by
-- the owner; a named member can remove their own mark. Counters, karma events, chat and
-- push events follow from the status changes (030, 050); nothing is repeated here.
-- Errors: SQLSTATE P0001 — post_not_found, closure_wrong_status,
-- closure_recipient_not_in_chat, world_not_assignable, listing_has_active_handoff,
-- reopen_window_expired, not_recipient_or_wrong_status.

-- Closes an open post naming the member who received it (or, on a request, who gave):
-- FR-CLOSURE-003 AC5, FR-CLOSURE-011. A handoff that member already holds is completed;
-- otherwise one is created already handed over. Anyone else waiting is cancelled as
-- superseded. For worlds where one member takes the whole post; a ride or a stay assigns
-- its seats through its own module.
create function public.close_post_with_recipient(p_post_id uuid, p_recipient_id uuid)
returns public.post_handoffs
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post constant public.posts := kc_private.post_lock_managed(p_post_id);
  v_handoff public.post_handoffs;
begin
  if v_post.status <> 'open' then
    raise exception 'closure_wrong_status' using errcode = 'P0001';
  end if;
  if kc_private.handoff_flow_of(v_post.world_slug, v_post.kind_id) is null then
    raise exception 'world_not_assignable' using errcode = 'P0001';
  end if;
  -- The member must be someone who could have taken the post: not the owner, active, inside
  -- the post's audience, and not blocked in either direction.
  if p_recipient_id is null or p_recipient_id = v_post.owner_id
     or not kc_private.post_open_to_member(v_post, p_recipient_id) then
    raise exception 'closure_recipient_not_in_chat' using errcode = 'P0001';
  end if;

  select h.* into v_handoff from public.post_handoffs h
   where h.post_id = p_post_id and h.recipient_id = p_recipient_id
     and h.status in ('reserved', 'confirmed')
     for update;
  if found then
    v_handoff := kc_private.handoff_move(v_handoff.id, 'handed_over', 'owner');
  else
    insert into public.post_handoffs (post_id, recipient_id, status)
    values (p_post_id, p_recipient_id, 'handed_over')
    returning * into v_handoff;
  end if;

  -- Closing cancels every other live handoff of the post (050).
  perform kc_private.post_move(p_post_id, 'closed_delivered', 'owner');
  return v_handoff;
end;
$$;
comment on function public.close_post_with_recipient(uuid, uuid) is
  'Closes an open post as delivered to the named member and returns their handoff.';
grant execute on function public.close_post_with_recipient(uuid, uuid) to authenticated;

-- Closes an open post as delivered without naming anyone (FR-CLOSURE-003 AC6): it counts
-- as given, becomes `deleted_no_recipient` and is purged after seven days unless reopened.
-- Refused while a handoff is live (D104) — the owner settles it first, or names its member.
create function public.close_post_without_recipient(p_post_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post constant public.posts := kc_private.post_lock_managed(p_post_id);
begin
  if v_post.status <> 'open' then
    raise exception 'closure_wrong_status' using errcode = 'P0001';
  end if;
  if kc_private.post_has_active_handoff(p_post_id) then
    raise exception 'listing_has_active_handoff' using errcode = 'P0001';
  end if;

  -- Recorded before the move, which reads it to decide the owner's counter.
  insert into public.post_closures (post_id, delivered) values (p_post_id, true)
  on conflict (post_id) do update set delivered = true;
  perform kc_private.post_move(p_post_id, 'deleted_no_recipient', 'owner');
end;
$$;
comment on function public.close_post_without_recipient(uuid) is
  'Closes an open post as delivered to nobody in particular; purged after seven days unless reopened.';
grant execute on function public.close_post_without_recipient(uuid) to authenticated;

-- Reopens a closed or deleted post (FR-CLOSURE-005); also the undo of public.delete_post.
--   closed_delivered      the recipient mark of a single-taker post is withdrawn (the
--                         handoff is cancelled as `reopened`; nobody is notified, D-6)
--   deleted_no_recipient  only inside the seven-day grace period
-- The open-post limit applies as for any post becoming open (FR-POST-011).
create function public.reopen_post(p_post_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_post constant public.posts := kc_private.post_lock_managed(p_post_id);
  v_handoff_id uuid;
begin
  if v_post.status not in ('closed_delivered', 'deleted_no_recipient') then
    raise exception 'closure_wrong_status' using errcode = 'P0001';
  end if;
  if v_post.status = 'deleted_no_recipient' and exists (
       select 1 from public.post_closures c where c.post_id = p_post_id and c.purge_after <= now()) then
    raise exception 'reopen_window_expired' using errcode = 'P0001';
  end if;

  if kc_private.handoff_flow_of(v_post.world_slug, v_post.kind_id) is not null then
    for v_handoff_id in
      select h.id from public.post_handoffs h where h.post_id = p_post_id and h.status = 'handed_over'
    loop
      perform kc_private.handoff_move(v_handoff_id, 'cancelled', 'owner', 'reopened');
    end loop;
  end if;
  perform kc_private.post_move(p_post_id, 'open', 'owner');
end;
$$;
comment on function public.reopen_post(uuid) is
  'Returns a closed_delivered post, or a deleted_no_recipient post inside its grace period, to open.';
grant execute on function public.reopen_post(uuid) to authenticated;

-- The member named as recipient removes their own mark (FR-CLOSURE-007). The post stays a
-- delivery in the owner's counter but has no recipient any more, so it moves to
-- `deleted_no_recipient`: the owner may reopen it, name someone else, or let it be purged.
-- The owner is notified (FR-NOTIF-010) and the removal is recorded for the audit trail.
create function public.recipient_unmark_self(p_post_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_handoff_id uuid;
begin
  -- Post first, then the handoff: the same lock order as a concurrent reopen by the owner.
  perform 1 from public.posts p where p.id = p_post_id for update;
  select h.id into v_handoff_id
    from public.post_handoffs h
    join public.posts p on p.id = h.post_id
   where h.post_id = p_post_id and h.recipient_id = v_user_id and h.status = 'handed_over'
     and h.machine_id = 'giving_handoff' and p.status = 'closed_delivered'
     for update of h;
  if not found then
    raise exception 'not_recipient_or_wrong_status' using errcode = 'P0001';
  end if;

  perform kc_private.handoff_move(v_handoff_id, 'cancelled', 'recipient', 'unmarked');
  perform kc_private.post_move(p_post_id, 'deleted_no_recipient', 'system');
  perform kc_private.outbox_enqueue('audit', jsonb_build_object(
    'action', 'recipient_unmarked', 'actor_id', v_user_id,
    'entity', jsonb_build_object('type', 'post', 'id', p_post_id),
    'data', jsonb_build_object('handoff_id', v_handoff_id)));
end;
$$;
comment on function public.recipient_unmark_self(uuid) is
  'The caller removes their recipient mark from a delivered post; the post moves to deleted_no_recipient.';
grant execute on function public.recipient_unmark_self(uuid) to authenticated;

-- >>> supabase/schemas/25_handoffs/080_handoff_sweeps.sql
-- Handoffs · sweeps (run by the scheduler as the service role)
--
-- Time-driven moves, all in the machine role `system`. Each is safe to run concurrently
-- with itself and with member actions: rows are claimed with SKIP LOCKED and re-checked by
-- the machine on the move.

-- A reservation the owner did not answer by `confirm_by` lapses (`expired`), in every
-- world: the seat is free again and both members are notified (FR-NOTIF-018 AC3b). Before,
-- only some worlds swept the deadline and a stale request could hold a post indefinitely.
create function kc_private.handoff_reservation_expiry_sweep(p_limit integer default 500)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff_id uuid;
  v_count integer := 0;
begin
  for v_handoff_id in
    select h.id from public.post_handoffs h
     where h.status = 'reserved' and h.confirm_by < now()
     order by h.confirm_by
     limit least(greatest(p_limit, 1), 5000)
       for update skip locked
  loop
    perform kc_private.handoff_move(v_handoff_id, 'cancelled', 'system', 'expired');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;
comment on function kc_private.handoff_reservation_expiry_sweep(integer) is
  'Cancels reservations left unanswered past confirm_by; returns how many.';

-- A confirmed pickup of the giving machine whose window ended more than two hours ago is a
-- no-show: the handoff ends and the post, still open, can be taken by someone else. Stays
-- and events record a no-show by hand; rides have none.
create function kc_private.handoff_no_show_sweep(p_limit integer default 500)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_handoff_id uuid;
  v_count integer := 0;
begin
  for v_handoff_id in
    select h.id from public.post_handoffs h
     where h.status = 'confirmed' and h.machine_id = 'giving_handoff'
       and h.pickup_window_end < now() - interval '2 hours'
     order by h.pickup_window_end
     limit least(greatest(p_limit, 1), 5000)
       for update skip locked
  loop
    perform kc_private.handoff_move(v_handoff_id, 'no_show', 'system');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;
comment on function kc_private.handoff_no_show_sweep(integer) is
  'Marks confirmed pickups two hours past their window as no_show; returns how many.';

-- >>> supabase/schemas/25_handoffs/090_handoff_booking_details.sql
-- Handoffs · handoff_booking_details (the stay behind a housing booking)
--
-- 1:1 with a handoff of a housing post: dates, party, the guest's message and the notes
-- of the decision. Table and access only; the booking RPCs that write it belong to the
-- housing module.

create table public.handoff_booking_details (
  handoff_id          uuid primary key references public.post_handoffs (id) on delete cascade,
  check_in_date       date not null,
  check_out_date      date not null,
  adults              smallint not null check (adults between 1 and 8),
  minors              smallint not null default 0 check (minors between 0 and 7),
  -- The guest's introduction to the host; required with every request.
  message             text not null check (char_length(btrim(message)) between 1 and 500),
  -- The guest confirmed that an adult guardian accompanies the minors.
  minors_guardian_ack boolean not null default false,
  -- The guest cancelled inside the late-cancellation window (FR-HOUSING-018).
  late_cancel         boolean not null default false,
  decision_note       text check (char_length(decision_note) <= 300),
  cancel_note         text check (char_length(cancel_note) <= 300),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint handoff_booking_details_party_chk check (adults + minors <= 8),
  -- At least one night and at most thirty.
  constraint handoff_booking_details_dates_chk
    check (check_out_date > check_in_date and check_out_date - check_in_date <= 30)
);
comment on table public.handoff_booking_details is
  'Stay dates, party and notes of a housing booking. Written only by server code.';

create trigger handoff_booking_details_set_updated_at
  before update on public.handoff_booking_details
  for each row execute function kc_private.set_updated_at();

alter table public.handoff_booking_details enable row level security;
alter table public.handoff_booking_details force row level security;

-- Visible exactly when the handoff is: the subquery runs under the caller's access to
-- post_handoffs, so only the host and the guest match.
create policy handoff_booking_details_select_party on public.handoff_booking_details
  for select to authenticated
  using (exists (select 1 from public.post_handoffs h where h.id = handoff_booking_details.handoff_id));

grant select on public.handoff_booking_details to authenticated;

-- >>> supabase/schemas/25_handoffs/100_private_location_release.sql
-- Handoffs · release of a post's exact address (design §3.9)
--
-- The exact address is readable from the table by the post owner only. The other member
-- of a handoff receives it through this RPC, and only once the handoff is confirmed —
-- a request that is still waiting, was cancelled or ended as a no-show releases nothing.

-- Returns the exact location of a post to a caller who manages it, or who holds a
-- confirmed or completed handoff on it; null when the post has no exact address. A release
-- to the other member is recorded as an `audit` event with ids only, never the address.
--   post_not_found  the caller is neither (also when the post does not exist)
create function public.get_post_private_location(p_post_id uuid)
returns public.post_private_locations
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_handoff_id uuid;
  v_location public.post_private_locations;
begin
  if not kc_private.can_manage_post(p_post_id) then
    select h.id into v_handoff_id
      from public.post_handoffs h
     where h.post_id = p_post_id and h.recipient_id = v_user_id
       and h.status in ('confirmed', 'handed_over')
     order by h.created_at desc
     limit 1;
    if not found then
      raise exception 'post_not_found' using errcode = 'P0001';
    end if;
    perform kc_private.outbox_enqueue('audit', jsonb_build_object(
      'action', 'post_private_location_released', 'actor_id', v_user_id,
      'entity', jsonb_build_object('type', 'post', 'id', p_post_id),
      'data', jsonb_build_object('handoff_id', v_handoff_id)));
  end if;

  select l.* into v_location from public.post_private_locations l where l.post_id = p_post_id;
  return v_location;
end;
$$;
comment on function public.get_post_private_location(uuid) is
  'Exact address of a post, for its owner and for the member of a confirmed handoff; each release to that member is audited.';
grant execute on function public.get_post_private_location(uuid) to authenticated;

-- >>> supabase/schemas/25_handoffs/110_post_ratings.sql
-- Handoffs · post_ratings (one two-sided rating for every post type, D15, D19)
--
-- After a handoff each member rates the other, 1 to 5 with an optional note. Members never
-- see ratings — not the ones about them and not their own (D24): the table has no policy
-- and no grant for a device, and the moderation module adds the admin read. Ratings feed
-- the trust engine.

create table public.post_ratings (
  id         uuid primary key default gen_random_uuid(),
  -- Kept (as null) when the handoff goes with a deleted post or account, so the rating of
  -- the remaining member survives (design §4.1).
  handoff_id uuid references public.post_handoffs (id) on delete set null,
  -- Null once the rater's account is purged.
  rater_id   uuid references public.users (id) on delete set null,
  ratee_id   uuid not null references public.users (id) on delete cascade,
  stars      smallint not null check (stars between 1 and 5),
  comment    text check (char_length(comment) between 1 and 500),
  created_at timestamptz not null default now(),
  constraint post_ratings_distinct_members_chk check (rater_id <> ratee_id),
  -- Each member rates a handoff once; also covers the handoff foreign key.
  constraint post_ratings_once_key unique (handoff_id, rater_id)
);
comment on table public.post_ratings is
  'Ratings between the two members of a handoff. Not readable by members (D24).';

-- A member's ratings for the trust engine and the admin view, newest first; covers ratee_id.
create index post_ratings_ratee_recent_idx on public.post_ratings (ratee_id, created_at desc, id desc);
-- Covers the rater foreign key (account purge).
create index post_ratings_rater_idx on public.post_ratings (rater_id) where rater_id is not null;

alter table public.post_ratings enable row level security;
alter table public.post_ratings force row level security;

-- Rates the other member of a handoff the caller took part in.
--   invalid_rating          stars outside 1–5, or a note longer than 500 characters
--   handoff_not_found       no such handoff, or it was not handed over
--   not_participant         the caller is not one of its two members
--   handoff_already_rated   the caller already rated it; a rating is final, since its
--                           author cannot read it back
-- The spec sets no time limit for rating. A `karma` event rewards the rater once.
create function public.rate_handoff(p_handoff_id uuid, p_stars integer, p_comment text default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_comment constant text := nullif(btrim(p_comment), '');
  v_handoff public.post_handoffs;
begin
  if p_stars is null or p_stars not between 1 and 5 or char_length(v_comment) > 500 then
    raise exception 'invalid_rating' using errcode = 'P0001';
  end if;
  select h.* into v_handoff from public.post_handoffs h
   where h.id = p_handoff_id and h.status = 'handed_over';
  if not found then
    raise exception 'handoff_not_found' using errcode = 'P0001';
  end if;
  if v_user_id not in (v_handoff.owner_id, v_handoff.recipient_id) then
    raise exception 'not_participant' using errcode = 'P0001';
  end if;

  insert into public.post_ratings (handoff_id, rater_id, ratee_id, stars, comment)
  values (p_handoff_id, v_user_id,
          case v_user_id when v_handoff.owner_id then v_handoff.recipient_id else v_handoff.owner_id end,
          p_stars, v_comment)
  on conflict (handoff_id, rater_id) do nothing;
  if not found then
    raise exception 'handoff_already_rated' using errcode = 'P0001';
  end if;

  perform kc_private.outbox_enqueue('karma', jsonb_build_object(
    'kind', 'rating_given', 'handoff_id', p_handoff_id, 'post_id', v_handoff.post_id,
    'rater_id', v_user_id));
end;
$$;
comment on function public.rate_handoff(uuid, integer, text) is
  'The caller rates the other member of a handed-over handoff, once.';
grant execute on function public.rate_handoff(uuid, integer, text) to authenticated;

-- >>> supabase/schemas/30_social/010_post_media.sql
-- Social · post_media (one row per file attached to a post)
--
-- The file itself lives in object storage; the database holds what a card needs to lay the
-- media out before it loads (size, blurhash) and where to fetch it (design §5.3). A device
-- uploads straight to storage under its own folder and then records the row as `pending`;
-- the media pipeline strips EXIF, builds the fixed variants and marks the row `ready`
-- (FR-POST-005 AC3, AC4). Other members only ever see `ready` media.

insert into kc_private.fsm_state (machine_id, status) values
  ('post_media', 'pending'),
  ('post_media', 'ready'),
  ('post_media', 'failed');

-- Only the media pipeline (role `system`) moves a file out of `pending`.
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('post_media', 'pending', 'ready', 'system'),
  ('post_media', 'pending', 'failed', 'system');

create table public.post_media (
  id                uuid primary key default gen_random_uuid(),
  post_id           uuid not null references public.posts (id) on delete cascade,
  -- Always the post's owner; kept on the row so the storage folder rule and the purge of a
  -- member's files need no join.
  owner_id          uuid not null references public.users (id) on delete cascade,
  kind              text not null default 'image' check (kind in ('image', 'video')),
  storage_bucket    text not null default 'post-images' check (storage_bucket ~ '^[a-z0-9][a-z0-9-]{1,62}$'),
  -- Object path inside the bucket; for video, the provider's asset id (design §5.3).
  storage_key       text not null check (char_length(storage_key) between 1 and 512),
  -- Position in the post's gallery, 0 first. The range is the cap: five files per post
  -- (FR-POST-005 AC2).
  ordinal           smallint not null check (ordinal between 0 and 4),
  mime_type         text not null,
  size_bytes        bigint not null check (size_bytes > 0),
  width             integer check (width > 0),
  height            integer check (height > 0),
  duration_ms       integer check (duration_ms > 0),
  -- Compact placeholder painted while the file loads.
  blurhash          text check (char_length(blurhash) between 6 and 64),
  -- Lifecycle, machine `post_media`. Never written by a device.
  processing_status text not null default 'pending',
  created_at        timestamptz not null default now(),
  constraint post_media_post_ordinal_key unique (post_id, ordinal),
  constraint post_media_storage_object_key unique (storage_bucket, storage_key),
  -- A member's files live under a folder named by their id (design §4 "Storage").
  constraint post_media_owner_folder_chk check (starts_with(storage_key, owner_id::text || '/')),
  -- Images: JPEG or PNG, at most 8 MB after the client-side resize (FR-POST-005 AC1, AC2).
  constraint post_media_image_chk check (
    kind <> 'image' or (mime_type in ('image/jpeg', 'image/png') and size_bytes <= 8388608 and duration_ms is null)),
  constraint post_media_video_chk check (kind <> 'video' or mime_type like 'video/%')
);
comment on table public.post_media is 'Files attached to a post: location in storage, layout hints and processing status.';

-- Gallery of a post in order and the cover of a card are served by post_media_post_ordinal_key.
-- Files of a member: the account purge deletes them from storage first; covers the foreign key.
create index post_media_owner_idx on public.post_media (owner_id);

create trigger post_media_status_fsm
  before insert or update of processing_status on public.post_media
  for each row execute function kc_private.fsm_guard_status('post_media', 'processing_status');

alter table public.post_media enable row level security;
alter table public.post_media force row level security;

-- The owner sees every file of theirs. Anyone else sees processed files of a post they can
-- read: the subquery runs under the caller's own access to `posts`, so the post decides.
create policy post_media_select_visible on public.post_media
  for select to authenticated
  using (
    owner_id = (select auth.uid())
    or (processing_status = 'ready'
        and exists (select 1 from public.posts p where p.id = post_media.post_id)));

-- The owner attaches a file to a post of theirs while its content is editable (draft, open
-- or paused, D104). The row always starts `pending`.
create policy post_media_insert_owner on public.post_media
  for insert to authenticated
  with check (
    owner_id = (select auth.uid())
    and processing_status = 'pending'
    and exists (select 1 from public.posts p
                 where p.id = post_media.post_id and p.owner_id = (select auth.uid())
                   and p.status in ('draft', 'open', 'paused'))
    and exists (select 1 from public.users u where u.id = (select auth.uid()) and u.is_active));

-- The owner removes a file under the same condition. The object itself is removed by the
-- orphan reconciliation job (design §5.3).
create policy post_media_delete_owner on public.post_media
  for delete to authenticated
  using (
    owner_id = (select auth.uid())
    and exists (select 1 from public.posts p
                 where p.id = post_media.post_id and p.status in ('draft', 'open', 'paused')));

grant select, delete on public.post_media to authenticated;
-- Not insertable: processing_status (starts `pending`) and created_at.
grant insert (
  id, post_id, owner_id, kind, storage_bucket, storage_key, ordinal, mime_type, size_bytes,
  width, height, duration_ms, blurhash
) on public.post_media to authenticated;

-- >>> supabase/schemas/30_social/020_post_stats.sql
-- Social · post_stats (engagement counters of a post)
--
-- One row per post that has ever been reacted to, commented on or shared; a post without a
-- row has all counters at zero. Counters live apart from `posts` so that a reaction never
-- rewrites the post row, and no trigger is added to `posts` (design §5 trigger budget).
-- Maintained by statement-level triggers on the engagement tables; a nightly job recomputes
-- them and records any drift.

create table public.post_stats (
  post_id         uuid primary key references public.posts (id) on delete cascade,
  reactions_count integer not null default 0 check (reactions_count >= 0),
  -- Active comments, replies included.
  comments_count  integer not null default 0 check (comments_count >= 0),
  shares_count    integer not null default 0 check (shares_count >= 0),
  updated_at      timestamptz not null default now()
);
comment on table public.post_stats is 'Engagement counters per post, maintained by triggers and reconciled nightly.';

create trigger post_stats_set_updated_at
  before update on public.post_stats
  for each row execute function kc_private.set_updated_at();

alter table public.post_stats enable row level security;
alter table public.post_stats force row level security;

-- Counters are visible exactly when the post is: the subquery runs under the caller's own
-- access to `posts`.
create policy post_stats_select_visible_post on public.post_stats
  for select to authenticated
  using (exists (select 1 from public.posts p where p.id = post_stats.post_id));

grant select on public.post_stats to authenticated;

-- Adds (p_sign = 1) or subtracts (p_sign = -1) one unit of a counter for every element of
-- p_post_ids; a post listed n times moves by n. Called once per statement by the engagement
-- triggers. Adding creates the row on first use. Subtracting only updates: when the post
-- itself is being removed its counter row is already gone and nothing is written, and a
-- counter never drops below zero. Posts are touched in id order so two statements cannot
-- deadlock on each other.
create function kc_private.post_stats_add(p_counter text, p_sign integer, p_post_ids uuid[])
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_sign > 0 then
    insert into public.post_stats as s (post_id, reactions_count, comments_count, shares_count)
    select d.post_id,
           d.n * (p_counter = 'reactions')::integer,
           d.n * (p_counter = 'comments')::integer,
           d.n * (p_counter = 'shares')::integer
      from (select u.post_id, count(*)::integer as n
              from unnest(p_post_ids) as u (post_id)
             group by u.post_id
             order by u.post_id) d
    on conflict (post_id) do update
      set reactions_count = s.reactions_count + excluded.reactions_count,
          comments_count = s.comments_count + excluded.comments_count,
          shares_count = s.shares_count + excluded.shares_count;
    return;
  end if;

  update public.post_stats s
     set reactions_count = greatest(s.reactions_count - d.n * (p_counter = 'reactions')::integer, 0),
         comments_count = greatest(s.comments_count - d.n * (p_counter = 'comments')::integer, 0),
         shares_count = greatest(s.shares_count - d.n * (p_counter = 'shares')::integer, 0)
    from (select u.post_id, count(*)::integer as n
            from unnest(p_post_ids) as u (post_id)
           group by u.post_id
           order by u.post_id) d
   where s.post_id = d.post_id;
end;
$$;
comment on function kc_private.post_stats_add(text, integer, uuid[]) is
  'Moves one engagement counter of the listed posts up or down; used by the engagement triggers.';

-- Records an engagement notification for the notifications module to deliver. Nothing is
-- recorded when the recipient is the actor, no longer exists, or is in a blocked pair with
-- the actor. `group_key` lets the consumer fold events of one kind on one post within the
-- same hour into a single notification (S10).
create function kc_private.notify_engagement(
  p_kind text,
  p_recipient_id uuid,
  p_actor_id uuid,
  p_post_id uuid,
  p_entity_type text,
  p_entity_id uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_recipient_id is null or p_recipient_id = p_actor_id
     or kc_access.is_blocked_between(p_recipient_id, p_actor_id) then
    return;
  end if;
  perform kc_private.outbox_enqueue('notification', jsonb_build_object(
    'kind', p_kind,
    'recipient_id', p_recipient_id,
    'actor_id', p_actor_id,
    'entity', jsonb_build_object('type', p_entity_type, 'id', p_entity_id),
    'data', jsonb_build_object(
      'post_id', p_post_id,
      'group_key', p_kind || ':' || p_post_id || ':' || to_char(now() at time zone 'UTC', 'YYYYMMDDHH24'))));
end;
$$;
comment on function kc_private.notify_engagement(text, uuid, uuid, uuid, text, uuid) is
  'Enqueues one engagement notification event, skipping self-notifications and blocked pairs.';

-- >>> supabase/schemas/30_social/030_post_reactions.sql
-- Social · post_reactions (a member's reaction to a post, D25)
--
-- At most one reaction per member per post. Adding and removing are plain row writes under
-- RLS; switching the type of an existing reaction goes through set_post_reaction below.

create table public.post_reactions (
  post_id       uuid not null references public.posts (id) on delete cascade,
  user_id       uuid not null references public.users (id) on delete cascade,
  reaction_type text not null default 'like' check (reaction_type in ('like', 'support', 'thanks')),
  created_at    timestamptz not null default now(),
  primary key (post_id, user_id)
);
comment on table public.post_reactions is 'One reaction per member per post.';

-- Removal of a member's reactions with their account; covers the user foreign key.
create index post_reactions_user_idx on public.post_reactions (user_id, created_at desc);

-- Keeps post_stats.reactions_count in step, once per statement.
create function kc_private.post_reactions_sync_stats()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.post_stats_add(
    'reactions', case tg_op when 'INSERT' then 1 else -1 end, array(select c.post_id from changed c));
  return null;
end;
$$;

create trigger post_reactions_count_insert
  after insert on public.post_reactions
  referencing new table as changed
  for each statement execute function kc_private.post_reactions_sync_stats();
create trigger post_reactions_count_delete
  after delete on public.post_reactions
  referencing old table as changed
  for each statement execute function kc_private.post_reactions_sync_stats();

-- A new reaction notifies the post's owner (kind `post_reaction`). A type switch does not.
create function kc_private.post_reactions_notify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.notify_engagement(
    'post_reaction', (select p.owner_id from public.posts p where p.id = new.post_id),
    new.user_id, new.post_id, 'post', new.post_id);
  return null;
end;
$$;

create trigger post_reactions_notify
  after insert on public.post_reactions
  for each row execute function kc_private.post_reactions_notify();

alter table public.post_reactions enable row level security;
alter table public.post_reactions force row level security;

-- A reaction is visible when its post is and its author is: both subqueries run under the
-- caller's own access, so a post the caller cannot read shows no reactions, and members in
-- a blocked pair (or with an inactive account) never see each other's.
create policy post_reactions_select_visible on public.post_reactions
  for select to authenticated
  using (
    exists (select 1 from public.posts p where p.id = post_reactions.post_id)
    and exists (select 1 from public.users u where u.id = post_reactions.user_id));

-- A member with an active account reacts, as themselves, to a published post they can read.
create policy post_reactions_insert_self on public.post_reactions
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.users u where u.id = (select auth.uid()) and u.is_active)
    and exists (select 1 from public.posts p
                 where p.id = post_reactions.post_id and p.status in ('open', 'closed_delivered')));

-- Only the type of one's own reaction changes; which column is decided by the grant.
create policy post_reactions_update_self on public.post_reactions
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create policy post_reactions_delete_self on public.post_reactions
  for delete to authenticated
  using (user_id = (select auth.uid()));

grant select, insert, delete on public.post_reactions to authenticated;
grant update (reaction_type) on public.post_reactions to authenticated;

-- Sets the caller's reaction on a post: a type adds the reaction or switches its type, null
-- removes it. Returns the type now held. An RPC because "insert, or change the type of the
-- one I have" is an upsert, which the REST layer can only express with update rights on the
-- key columns. Runs with the caller's rights: every rule is enforced by the policies above.
create function public.set_post_reaction(p_post_id uuid, p_reaction_type text)
returns text
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_user_id constant uuid := (select auth.uid());
begin
  if v_user_id is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;
  if p_reaction_type is null then
    delete from public.post_reactions r where r.post_id = p_post_id and r.user_id = v_user_id;
    return null;
  end if;
  if p_reaction_type not in ('like', 'support', 'thanks') then
    raise exception 'invalid_reaction_type' using errcode = 'P0001';
  end if;
  if not exists (select 1 from public.users u where u.id = v_user_id and u.is_active) then
    raise exception 'account_not_active' using errcode = 'P0001';
  end if;
  if not exists (select 1 from public.posts p
                  where p.id = p_post_id and p.status in ('open', 'closed_delivered')) then
    raise exception 'post_not_found' using errcode = 'P0001';
  end if;

  insert into public.post_reactions as r (post_id, user_id, reaction_type)
  values (p_post_id, v_user_id, p_reaction_type)
  on conflict (post_id, user_id) do update set reaction_type = excluded.reaction_type
    where r.reaction_type <> excluded.reaction_type;
  return p_reaction_type;
end;
$$;
comment on function public.set_post_reaction(uuid, text) is
  'Adds, switches or (with null) removes the caller''s reaction on a post; returns the type now held.';
grant execute on function public.set_post_reaction(uuid, text) to authenticated;

-- >>> supabase/schemas/30_social/040_post_comments.sql
-- Social · post_comments (comments and one level of replies, D25, S8)
--
-- A comment is written and edited as a plain row under RLS; triggers supply everything a
-- device must not decide (thread rule, write rate, mentions, edit stamp, notifications).
-- Deleting is a status move (machine `post_comment`) made by delete_post_comment, so the
-- row stays as evidence for moderation while nobody can read it any more.

insert into kc_private.fsm_state (machine_id, status) values
  ('post_comment', 'active'),
  ('post_comment', 'deleted');

-- Who may delete a comment (S9). `deleted` is final.
insert into kc_private.fsm_edge (machine_id, from_status, to_status, role) values
  ('post_comment', 'active', 'deleted', 'author'),
  ('post_comment', 'active', 'deleted', 'post_owner'),
  ('post_comment', 'active', 'deleted', 'admin');

create table public.post_comments (
  id                uuid primary key default gen_random_uuid(),
  post_id           uuid not null references public.posts (id) on delete cascade,
  author_id         uuid not null references public.users (id) on delete cascade,
  -- Null for a comment on the post; a reply points at a top-level comment of the same post.
  parent_comment_id uuid references public.post_comments (id) on delete cascade,
  body              text not null check (char_length(body) between 1 and 2000 and body = btrim(body)),
  -- Lifecycle, machine `post_comment`. Never written by a device.
  status            text not null default 'active',
  -- Members named in the body as @share_handle who can read the post; derived by trigger.
  mention_user_ids  uuid[] not null default '{}',
  edited_at         timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
comment on table public.post_comments is 'Comments on a post, with one level of replies. Removal is a status move.';

-- Comments of a post, oldest first: top-level list (parent is null) and, by prefix, the
-- removal of a post's comments; covers the post foreign key.
create index post_comments_thread_idx on public.post_comments (post_id, parent_comment_id, created_at, id);
-- Replies of a comment, oldest first; covers the parent foreign key.
create index post_comments_replies_idx on public.post_comments (parent_comment_id, created_at, id)
  where parent_comment_id is not null;
-- Write-rate check and removal of a member's comments; covers the author foreign key.
create index post_comments_author_recent_idx on public.post_comments (author_id, created_at desc);

create trigger post_comments_status_fsm
  before insert or update of status on public.post_comments
  for each row execute function kc_private.fsm_guard_status('post_comment', 'status');
create trigger post_comments_set_updated_at
  before update on public.post_comments
  for each row execute function kc_private.set_updated_at();

-- Members named in a comment body as @share_handle, at most ten, who are active, are not in
-- a blocked pair with the author and can read the post. The audience test repeats the post
-- policy for another member, because a policy only ever answers for the caller.
create function kc_private.comment_mentions(p_body text, p_author_id uuid, p_post_id uuid)
returns uuid[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(m.id), '{}')
    from (select u.id
            from public.posts p
            join public.users u
              on u.share_handle in (select lower(t[1]) from regexp_matches(p_body, '@([A-Za-z0-9_]{3,30})', 'g') t)
           where p.id = p_post_id
             and u.is_active
             and u.id <> p_author_id
             and not kc_access.is_blocked_between(u.id, p_author_id)
             and not kc_access.is_blocked_between(u.id, p.owner_id)
             and (u.id = p.owner_id
                  or p.visibility = 'Public'
                  or (p.visibility = 'FollowersOnly'
                      and exists (select 1 from public.follows f
                                   where f.follower_id = u.id and f.followed_id = p.owner_id)))
           order by u.share_handle
           limit 10) m;
$$;
comment on function kc_private.comment_mentions(text, uuid, uuid) is
  'Resolves the @share_handle tokens of a comment body to members who can read the post.';

-- Server-side part of a comment write.
--   insert  at most 20 comments a minute per member; a reply must point at an active
--           top-level comment of the same post (one thread level, S8); mentions resolved
--   edit    the body changed: edit stamp and mentions refreshed
create function kc_private.post_comments_prepare()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if (select count(*) from public.post_comments c
         where c.author_id = new.author_id and c.created_at > now() - interval '1 minute') >= 20 then
      raise exception 'rate_limited' using errcode = 'P0001', detail = 'at most 20 comments a minute';
    end if;
    if new.parent_comment_id is not null and not exists (
         select 1 from public.post_comments c
          where c.id = new.parent_comment_id and c.post_id = new.post_id
            and c.parent_comment_id is null and c.status = 'active') then
      raise exception 'comment_parent_invalid' using errcode = 'P0001';
    end if;
  else
    new.edited_at := now();
  end if;
  new.mention_user_ids := kc_private.comment_mentions(new.body, new.author_id, new.post_id);
  return new;
end;
$$;

create trigger post_comments_prepare_insert
  before insert on public.post_comments
  for each row execute function kc_private.post_comments_prepare();
create trigger post_comments_prepare_edit
  before update of body on public.post_comments
  for each row when (old.body is distinct from new.body)
  execute function kc_private.post_comments_prepare();

-- Keeps post_stats.comments_count (active comments) in step, once per statement: a new
-- comment counts, a comment that leaves `active` or is removed while active stops counting.
create function kc_private.post_comments_sync_stats()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform kc_private.post_stats_add(
      'comments', 1, array(select c.post_id from changed c where c.status = 'active'));
  elsif tg_op = 'DELETE' then
    perform kc_private.post_stats_add(
      'comments', -1, array(select c.post_id from changed c where c.status = 'active'));
  else
    perform kc_private.post_stats_add(
      'comments', -1,
      array(select o.post_id from changed o join changed_new n on n.id = o.id
             where o.status = 'active' and n.status <> 'active'));
  end if;
  return null;
end;
$$;

create trigger post_comments_count_insert
  after insert on public.post_comments
  referencing new table as changed
  for each statement execute function kc_private.post_comments_sync_stats();
create trigger post_comments_count_delete
  after delete on public.post_comments
  referencing old table as changed
  for each statement execute function kc_private.post_comments_sync_stats();
create trigger post_comments_count_status
  after update on public.post_comments
  referencing old table as changed new table as changed_new
  for each statement execute function kc_private.post_comments_sync_stats();

-- A new comment notifies, each member at most once and never the author:
--   post_comment_reply   the author of the comment replied to
--   post_comment         the post's owner
--   post_mention         every member named in the body
create function kc_private.post_comments_notify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_parent_author_id constant uuid :=
    (select c.author_id from public.post_comments c where c.id = new.parent_comment_id);
  v_owner_id constant uuid := (select p.owner_id from public.posts p where p.id = new.post_id);
  v_mentioned_id uuid;
begin
  perform kc_private.notify_engagement(
    'post_comment_reply', v_parent_author_id, new.author_id, new.post_id, 'post_comment', new.id);
  if v_owner_id is distinct from v_parent_author_id then
    perform kc_private.notify_engagement(
      'post_comment', v_owner_id, new.author_id, new.post_id, 'post_comment', new.id);
  end if;
  foreach v_mentioned_id in array new.mention_user_ids loop
    if v_mentioned_id is distinct from v_owner_id and v_mentioned_id is distinct from v_parent_author_id then
      perform kc_private.notify_engagement(
        'post_mention', v_mentioned_id, new.author_id, new.post_id, 'post_comment', new.id);
    end if;
  end loop;
  return null;
end;
$$;

create trigger post_comments_notify
  after insert on public.post_comments
  for each row execute function kc_private.post_comments_notify();

alter table public.post_comments enable row level security;
alter table public.post_comments force row level security;

-- An active comment is visible when its post is and its author is (both under the caller's
-- own access): comments on a post the caller cannot read do not exist for them, and members
-- in a blocked pair never see each other's comments. A deleted comment is visible to nobody.
create policy post_comments_select_visible on public.post_comments
  for select to authenticated
  using (
    status = 'active'
    and exists (select 1 from public.posts p where p.id = post_comments.post_id)
    and exists (select 1 from public.users u where u.id = post_comments.author_id));

-- A member with an active account comments, as themselves, on a published post they can read.
create policy post_comments_insert_self on public.post_comments
  for insert to authenticated
  with check (
    author_id = (select auth.uid())
    and status = 'active'
    and exists (select 1 from public.users u where u.id = (select auth.uid()) and u.is_active)
    and exists (select 1 from public.posts p
                 where p.id = post_comments.post_id and p.status in ('open', 'closed_delivered')));

-- The author edits the body of their own active comment; which column is decided by the grant.
create policy post_comments_update_author on public.post_comments
  for update to authenticated
  using (author_id = (select auth.uid()) and status = 'active')
  with check (author_id = (select auth.uid()));

grant select on public.post_comments to authenticated;
-- Not insertable: status, mention_user_ids, edited_at, timestamps — all server-written.
grant insert (id, post_id, author_id, parent_comment_id, body) on public.post_comments to authenticated;
grant update (body) on public.post_comments to authenticated;

-- Deletes a comment: its author or the owner of the post may (S9; moderators act through
-- the moderation module). The replies under a top-level comment go with it, so no reply is
-- left without its thread. An RPC because the status column is not writable by a device and
-- the move names the role it is made in. Idempotent on an already deleted comment.
create function public.delete_post_comment(p_comment_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_comment public.post_comments;
  v_role text;
begin
  select c.* into v_comment from public.post_comments c where c.id = p_comment_id for update;
  v_role := case
    when v_comment.author_id = v_user_id then 'author'
    when exists (select 1 from public.posts p where p.id = v_comment.post_id and p.owner_id = v_user_id)
      then 'post_owner' end;
  -- One answer for "no such comment" and "not yours to delete".
  if v_role is null then
    raise exception 'comment_not_found' using errcode = 'P0001';
  end if;

  perform set_config('kc.fsm_role', v_role, true);
  update public.post_comments c
     set status = 'deleted'
   where (c.id = p_comment_id or c.parent_comment_id = p_comment_id) and c.status = 'active';
  perform set_config('kc.fsm_role', '', true);
end;
$$;
comment on function public.delete_post_comment(uuid) is
  'Deletes a comment and its replies; allowed to its author and to the owner of the post.';
grant execute on function public.delete_post_comment(uuid) to authenticated;

-- >>> supabase/schemas/30_social/050_comment_reactions_shares_saves.sql
-- Social · post_comment_reactions, post_shares, saved_posts
--
-- Three small member-owned tables. All of them are written as plain rows under RLS: each
-- rule is "my own row, on something I can read", which a policy expresses in full.

-- ── Likes on comments (D25) ──────────────────────────────────────────────────
create table public.post_comment_reactions (
  comment_id uuid not null references public.post_comments (id) on delete cascade,
  user_id    uuid not null references public.users (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (comment_id, user_id)
);
comment on table public.post_comment_reactions is 'One like per member per comment.';

-- Removal of a member's likes with their account; covers the user foreign key.
create index post_comment_reactions_user_idx on public.post_comment_reactions (user_id);

alter table public.post_comment_reactions enable row level security;
alter table public.post_comment_reactions force row level security;

-- Visible when the comment is (which in turn requires its post) and the member who liked
-- is; both subqueries run under the caller's own access.
create policy post_comment_reactions_select_visible on public.post_comment_reactions
  for select to authenticated
  using (
    exists (select 1 from public.post_comments c where c.id = post_comment_reactions.comment_id)
    and exists (select 1 from public.users u where u.id = post_comment_reactions.user_id));

create policy post_comment_reactions_insert_self on public.post_comment_reactions
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.users u where u.id = (select auth.uid()) and u.is_active)
    and exists (select 1 from public.post_comments c where c.id = post_comment_reactions.comment_id));

create policy post_comment_reactions_delete_self on public.post_comment_reactions
  for delete to authenticated
  using (user_id = (select auth.uid()));

grant select, insert, delete on public.post_comment_reactions to authenticated;

-- ── Shares (FR-POST-023) ─────────────────────────────────────────────────────
-- A log of "this member shared this post", kept for the share counter. Append-only.
create table public.post_shares (
  id               uuid primary key default gen_random_uuid(),
  post_id          uuid not null references public.posts (id) on delete cascade,
  user_id          uuid not null references public.users (id) on delete cascade,
  -- 'in_app' to another member inside the product; 'external' through the device share sheet.
  share_kind       text not null check (share_kind in ('in_app', 'external')),
  -- Where an external share went, as the share sheet reports it (for example 'whatsapp').
  external_channel text check (char_length(external_channel) between 1 and 64),
  created_at       timestamptz not null default now(),
  constraint post_shares_channel_chk check ((share_kind = 'external') = (external_channel is not null))
);
comment on table public.post_shares is 'Append-only log of post shares; feeds post_stats.shares_count.';

-- Removal with the post, and with the member; cover the two foreign keys.
create index post_shares_post_idx on public.post_shares (post_id);
create index post_shares_user_idx on public.post_shares (user_id, created_at desc);

-- Keeps post_stats.shares_count in step, once per statement.
create function kc_private.post_shares_sync_stats()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform kc_private.post_stats_add(
    'shares', case tg_op when 'INSERT' then 1 else -1 end, array(select c.post_id from changed c));
  return null;
end;
$$;

create trigger post_shares_count_insert
  after insert on public.post_shares
  referencing new table as changed
  for each statement execute function kc_private.post_shares_sync_stats();
create trigger post_shares_count_delete
  after delete on public.post_shares
  referencing old table as changed
  for each statement execute function kc_private.post_shares_sync_stats();

alter table public.post_shares enable row level security;
alter table public.post_shares force row level security;

-- Who shared what is the sharer's own business; everyone else sees only the counter.
create policy post_shares_select_own on public.post_shares
  for select to authenticated
  using (user_id = (select auth.uid()));

-- A member with an active account logs a share of a published post they can read that is
-- public, or their own (FR-POST-023 AC1).
create policy post_shares_insert_self on public.post_shares
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.users u where u.id = (select auth.uid()) and u.is_active)
    and exists (select 1 from public.posts p
                 where p.id = post_shares.post_id and p.status in ('open', 'closed_delivered')
                   and (p.visibility = 'Public' or p.owner_id = (select auth.uid()))));

grant select on public.post_shares to authenticated;
grant insert (id, post_id, user_id, share_kind, external_channel) on public.post_shares to authenticated;

-- ── Saved posts (FR-POST-022) ────────────────────────────────────────────────
create table public.saved_posts (
  user_id  uuid not null references public.users (id) on delete cascade,
  post_id  uuid not null references public.posts (id) on delete cascade,
  saved_at timestamptz not null default now(),
  primary key (user_id, post_id)
);
comment on table public.saved_posts is 'A member''s private bookmarks.';

-- "My saved posts", newest first (keyset on saved_at, post_id) (FR-PROFILE-016).
create index saved_posts_user_recent_idx on public.saved_posts (user_id, saved_at desc, post_id);
-- Removal with the post; covers the post foreign key.
create index saved_posts_post_idx on public.saved_posts (post_id);

alter table public.saved_posts enable row level security;
alter table public.saved_posts force row level security;

create policy saved_posts_select_own on public.saved_posts
  for select to authenticated
  using (user_id = (select auth.uid()));

-- A member saves any post they can read at that moment (FR-POST-022 AC2). A bookmark of a
-- post that later leaves the member's sight stays, and simply resolves to nothing.
create policy saved_posts_insert_self on public.saved_posts
  for insert to authenticated
  with check (
    user_id = (select auth.uid())
    and exists (select 1 from public.posts p where p.id = saved_posts.post_id));

create policy saved_posts_delete_own on public.saved_posts
  for delete to authenticated
  using (user_id = (select auth.uid()));

grant select, delete on public.saved_posts to authenticated;
grant insert (user_id, post_id) on public.saved_posts to authenticated;

-- >>> supabase/schemas/30_social/060_feed_personalisation.sql
-- Social · feed personalisation (hides, mute filters, ranking configuration, impressions)
--
-- What a member has asked not to see, the weights of the recommended sort, and the log of
-- what the feed has shown. The member-owned tables are written as plain rows under RLS.

-- ── Posts a member hid from their feed ───────────────────────────────────────
create table public.feed_hides (
  user_id   uuid not null references public.users (id) on delete cascade,
  post_id   uuid not null references public.posts (id) on delete cascade,
  hidden_at timestamptz not null default now(),
  primary key (user_id, post_id)
);
comment on table public.feed_hides is 'Posts a member removed from their own feed. The post stays reachable elsewhere.';

-- Removal with the post; covers the post foreign key.
create index feed_hides_post_idx on public.feed_hides (post_id);

alter table public.feed_hides enable row level security;
alter table public.feed_hides force row level security;

create policy feed_hides_own on public.feed_hides
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

grant select, delete on public.feed_hides to authenticated;
grant insert (user_id, post_id) on public.feed_hides to authenticated;

-- ── Things a member muted in their feed ──────────────────────────────────────
-- One row per muted member, giving world or keyword; exactly the column of its kind is set.
create table public.feed_mute_filters (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references public.users (id) on delete cascade,
  filter_kind   text not null check (filter_kind in ('user', 'world', 'keyword')),
  muted_user_id uuid references public.users (id) on delete cascade,
  world_slug    text references public.worlds (slug) on update cascade on delete cascade,
  -- Matched as a substring of the post's title and description; stored lower-case.
  keyword       text check (char_length(keyword) between 2 and 60 and keyword = lower(btrim(keyword))),
  created_at    timestamptz not null default now(),
  constraint feed_mute_filters_kind_chk check (
    (filter_kind = 'user') = (muted_user_id is not null)
    and (filter_kind = 'world') = (world_slug is not null)
    and (filter_kind = 'keyword') = (keyword is not null)),
  constraint feed_mute_filters_not_self_chk check (muted_user_id <> user_id),
  -- One row per muted thing; together the three constraints also serve "my mute filters",
  -- which the feed reads on every page, and cover the member foreign key.
  constraint feed_mute_filters_user_key unique (user_id, muted_user_id),
  constraint feed_mute_filters_world_key unique (user_id, world_slug),
  constraint feed_mute_filters_keyword_key unique (user_id, keyword)
);
comment on table public.feed_mute_filters is 'Members, giving worlds and keywords a member muted in their feed.';

-- Removal with the muted member or world; cover those two foreign keys.
create index feed_mute_filters_muted_user_idx on public.feed_mute_filters (muted_user_id)
  where muted_user_id is not null;
create index feed_mute_filters_world_idx on public.feed_mute_filters (world_slug)
  where world_slug is not null;

alter table public.feed_mute_filters enable row level security;
alter table public.feed_mute_filters force row level security;

create policy feed_mute_filters_own on public.feed_mute_filters
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

grant select, delete on public.feed_mute_filters to authenticated;
grant insert (id, user_id, filter_kind, muted_user_id, world_slug, keyword)
  on public.feed_mute_filters to authenticated;

-- ── Weights of the recommended sort (S33) ────────────────────────────────────
-- One row per setting that differs from the default written in feed_page; an empty table
-- means every default applies. Changed by operators through server code, never by a device.
--   window_hours     width of a ranking window: newer windows always come first, and the
--                    signals below order the posts inside one window (default 24)
--   follow_affinity  the viewer follows the owner (default 1)
--   active_world     the viewer has published in the post's giving world (default 0.5)
--   distance         closeness to the viewer's city, scaled by the world's geo_weight (default 1)
--   urgency          urgency level, or expiry within 48 hours (default 0.75)
--   no_response      nobody has commented yet (default 0.25)
create table public.feed_ranking_config (
  config_key text primary key check (config_key in
               ('window_hours', 'follow_affinity', 'active_world', 'distance', 'urgency', 'no_response')),
  value      numeric(8, 3) not null check (value >= 0),
  updated_at timestamptz not null default now(),
  constraint feed_ranking_config_window_chk check (config_key <> 'window_hours' or value between 1 and 720)
);
comment on table public.feed_ranking_config is 'Overrides of the recommended-sort weights; defaults live in feed_page.';

create trigger feed_ranking_config_set_updated_at
  before update on public.feed_ranking_config
  for each row execute function kc_private.set_updated_at();

alter table public.feed_ranking_config enable row level security;
alter table public.feed_ranking_config force row level security;

-- Readable by members: the feed query runs with the caller's rights.
create policy feed_ranking_config_select_member on public.feed_ranking_config
  for select to authenticated
  using (true);

grant select on public.feed_ranking_config to authenticated;

-- ── Impressions (what the feed showed to whom) ───────────────────────────────
-- Append-only log, partitioned by month so that retention (90 days, design §3.4) is a
-- partition drop. post_id deliberately has no foreign key: a removed post's impressions are
-- harmless, expire with their partition, and a cascade would have to search every partition.
create table public.feed_impressions (
  user_id uuid not null default auth.uid() references public.users (id) on delete cascade,
  post_id uuid not null,
  seen_at timestamptz not null default now()
) partition by range (seen_at);
comment on table public.feed_impressions is 'Append-only log of posts shown in a member''s feed; monthly partitions.';

-- A member's recent impressions, and their removal with the account; covers the foreign key.
create index feed_impressions_user_seen_idx on public.feed_impressions (user_id, seen_at desc);

-- Catches rows of a month whose partition the maintenance job has not created yet.
create table public.feed_impressions_default partition of public.feed_impressions default;

alter table public.feed_impressions enable row level security;
alter table public.feed_impressions force row level security;
alter table public.feed_impressions_default enable row level security;
alter table public.feed_impressions_default force row level security;

-- A member logs their own impressions and reads nothing back. Partitions carry no policy
-- and no grant: they are reached only through the parent.
create policy feed_impressions_insert_self on public.feed_impressions
  for insert to authenticated
  with check (user_id = (select auth.uid()));

-- The device sends post ids only; the member and the time are filled by the defaults.
grant insert (post_id) on public.feed_impressions to authenticated;

-- Creates the partition holding the month of p_month, if it is missing. Called ahead of
-- time by the scheduled maintenance job (the month must not yet have rows in the default
-- partition); the same job drops partitions older than the retention period.
create function kc_private.feed_impressions_ensure_partition(p_month date)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  -- Month boundaries in UTC, whatever the time zone of the calling session.
  v_from constant timestamptz := date_trunc('month', p_month)::timestamp at time zone 'UTC';
  v_to constant timestamptz := (date_trunc('month', p_month) + interval '1 month')::timestamp at time zone 'UTC';
  v_name constant text := 'feed_impressions_' || to_char(p_month, 'YYYY_MM');
begin
  if to_regclass('public.' || v_name) is not null then
    return;
  end if;
  execute format(
    'create table public.%I partition of public.feed_impressions for values from (%L) to (%L)',
    v_name, v_from, v_to);
  execute format('alter table public.%I enable row level security', v_name);
  execute format('alter table public.%I force row level security', v_name);
end;
$$;
comment on function kc_private.feed_impressions_ensure_partition(date) is
  'Creates the monthly partition of feed_impressions for the given month when it is missing.';

-- >>> supabase/schemas/30_social/070_post_cards.sql
-- Social · the post card and the post detail screen (design §5.1, layer 4)
--
-- A screen is one call. `post_card` is everything a card shows about a post — the post, its
-- owner, its location name, the cover, the counters and the viewer's own state — and every
-- list in the product (feed, world feed, profile tabs, search, saved posts) returns it.
-- All functions here run with the caller's rights: RLS on `posts` and on each joined table
-- decides what comes back, so a post the caller cannot read is simply absent.

create type public.post_card as (
  id                       uuid,
  owner_id                 uuid,
  world_slug               text,
  kind_id                  uuid,
  post_type                text,
  direction                text,
  status                   text,
  visibility               text,
  title                    text,
  description              text,
  item_subcategory_id      uuid,
  details                  jsonb,
  city_id                  text,
  city_name_he             text,
  city_name_en             text,
  location_display_level   text,
  time_window              tstzrange,
  urgency_level            smallint,
  expires_at               timestamptz,
  published_at             timestamptz,
  created_at               timestamptz,
  owner_display_name       text,
  owner_share_handle       text,
  owner_avatar_url         text,
  owner_verification_level smallint,
  -- First processed file: { id, kind, storage_bucket, storage_key, width, height, blurhash }.
  cover_media              jsonb,
  media_count              integer,
  reactions_count          integer,
  comments_count           integer,
  shares_count             integer,
  -- The viewer's own state: their reaction type (null = none), bookmark, follow of the owner.
  viewer_reaction          text,
  viewer_saved             boolean,
  viewer_follows_owner     boolean
);
comment on type public.post_card is 'Everything a post card shows, as returned by every post list.';

-- What a client needs to fetch and lay out one file.
create function kc_access.post_media_json(p_media public.post_media)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select jsonb_build_object(
    'id', p_media.id, 'kind', p_media.kind, 'storage_bucket', p_media.storage_bucket,
    'storage_key', p_media.storage_key, 'width', p_media.width, 'height', p_media.height,
    'duration_ms', p_media.duration_ms, 'blurhash', p_media.blurhash);
$$;
comment on function kc_access.post_media_json(public.post_media) is 'JSON form of a media row inside a card or a detail payload.';
grant execute on function kc_access.post_media_json(public.post_media) to authenticated;

-- Cards of the given posts (at most 100 ids are read), in no particular order. Also the way
-- to hydrate ids held elsewhere — saved posts, a notification, a map pin.
create function public.post_cards(p_post_ids uuid[])
returns setof public.post_card
language sql
stable
security invoker
set search_path = ''
as $$
  select p.id, p.owner_id, p.world_slug, p.kind_id, p.post_type, p.direction, p.status, p.visibility,
         p.title, p.description, p.item_subcategory_id, p.details,
         p.city_id, c.name_he, c.name_en, p.location_display_level, p.time_window, p.urgency_level,
         p.expires_at, p.published_at, p.created_at,
         u.display_name, u.share_handle, u.avatar_url, u.verification_level,
         media.cover, coalesce(media.n, 0),
         coalesce(s.reactions_count, 0), coalesce(s.comments_count, 0), coalesce(s.shares_count, 0),
         (select r.reaction_type from public.post_reactions r
           where r.post_id = p.id and r.user_id = (select auth.uid())),
         exists (select 1 from public.saved_posts sp
                  where sp.user_id = (select auth.uid()) and sp.post_id = p.id),
         exists (select 1 from public.follows f
                  where f.follower_id = (select auth.uid()) and f.followed_id = p.owner_id)
    from public.posts p
    join public.users u on u.id = p.owner_id
    join public.cities c on c.city_id = p.city_id
    left join public.post_stats s on s.post_id = p.id
    left join lateral (
      select count(*)::integer as n,
             (array_agg(kc_access.post_media_json(m) order by m.ordinal))[1] as cover
        from public.post_media m
       where m.post_id = p.id and m.processing_status = 'ready') media on true
   where p.id = any (p_post_ids[1:100]);
$$;
comment on function public.post_cards(uuid[]) is 'Cards of the listed posts that the caller can read.';
grant execute on function public.post_cards(uuid[]) to authenticated;

-- One page of the comments of a post (p_parent_comment_id null) or of the replies to a
-- comment, oldest first, each with its author, like count, reply count and whether the
-- caller liked it. Keyset on (created_at, id): pass the last row's next_cursor to continue.
create function public.post_comments_page(
  p_post_id uuid,
  p_parent_comment_id uuid default null,
  p_cursor jsonb default null,
  p_limit integer default 20
)
returns table (
  id uuid,
  post_id uuid,
  parent_comment_id uuid,
  author_id uuid,
  author_display_name text,
  author_share_handle text,
  author_avatar_url text,
  body text,
  mention_user_ids uuid[],
  created_at timestamptz,
  edited_at timestamptz,
  reactions_count integer,
  replies_count integer,
  viewer_reacted boolean,
  next_cursor jsonb
)
language sql
stable
security invoker
set search_path = ''
as $$
  select c.id, c.post_id, c.parent_comment_id, c.author_id, u.display_name, u.share_handle, u.avatar_url,
         c.body, c.mention_user_ids, c.created_at, c.edited_at,
         (select count(*)::integer from public.post_comment_reactions r where r.comment_id = c.id),
         (select count(*)::integer from public.post_comments reply where reply.parent_comment_id = c.id),
         exists (select 1 from public.post_comment_reactions r
                  where r.comment_id = c.id and r.user_id = (select auth.uid())),
         jsonb_build_object('t', c.created_at, 'id', c.id)
    from public.post_comments c
    join public.users u on u.id = c.author_id
   where c.post_id = p_post_id
     and c.parent_comment_id is not distinct from p_parent_comment_id
     and (p_cursor is null
          or (c.created_at, c.id) > ((p_cursor ->> 't')::timestamptz, (p_cursor ->> 'id')::uuid))
   order by c.created_at, c.id
   limit least(greatest(coalesce(p_limit, 20), 1), 50);
$$;
comment on function public.post_comments_page(uuid, uuid, jsonb, integer) is
  'One keyset page of a post''s comments, or of a comment''s replies, oldest first.';
grant execute on function public.post_comments_page(uuid, uuid, jsonb, integer) to authenticated;

-- The whole post detail screen in one call: the card, every processed file in gallery
-- order and the first page of comments. Null when the caller cannot read the post.
create function public.post_detail(p_post_id uuid)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select jsonb_build_object(
    'post', to_jsonb(card),
    'media', (select coalesce(jsonb_agg(kc_access.post_media_json(m) order by m.ordinal), '[]'::jsonb)
                from public.post_media m
               where m.post_id = card.id and m.processing_status = 'ready'),
    'comments', (select coalesce(jsonb_agg(to_jsonb(k)), '[]'::jsonb)
                   from public.post_comments_page(card.id) k))
    from public.post_cards(array[p_post_id]) card;
$$;
comment on function public.post_detail(uuid) is
  'Post detail payload: card, media gallery and first page of comments; null when not readable.';
grant execute on function public.post_detail(uuid) to authenticated;

-- >>> supabase/schemas/30_social/075_text_candidates.sql
-- Social · text-match candidates for search
--
-- The read functions of this module run with the caller's rights, so that RLS decides what
-- is visible. Under RLS the planner may only push leak-proof conditions into an index scan,
-- and text matching (ILIKE, @@) is not leak-proof: asked directly, a text search would
-- check the visibility of every row before it could use the trigram or full-text index.
--
-- These two functions do the index part with definer rights and return candidate ids only:
-- the newest (or most followed) matches, capped. The caller then reads those ids through
-- its own access, so visibility is still decided by RLS and by nothing else. They live in
-- `kc_access`, which a device cannot address, so the ids never leave the database unfiltered.

-- The text as an ILIKE pattern that matches it literally anywhere.
create function kc_private.contains_pattern(p_text text)
returns text
language sql
immutable
set search_path = ''
as $$
  select '%' || replace(replace(replace(p_text, '\', '\\'), '%', '\%'), '_', '\_') || '%';
$$;
comment on function kc_private.contains_pattern(text) is 'ILIKE pattern matching the given text literally, anywhere.';

-- Up to 500 newest open posts whose title or description contains the text (served by
-- posts_text_trgm_idx from three characters up), and, when asked, up to 500 newest
-- delivered posts likewise.
create function kc_access.post_ids_matching_text(p_query text, p_include_closed boolean default false)
returns uuid[]
language sql
stable
security definer
set search_path = ''
as $$
  select array(
    (select p.id from public.posts p
      where p.status = 'open'
        and (p.title || ' ' || coalesce(p.description, '')) ilike kc_private.contains_pattern(p_query)
      order by p.published_at desc
      limit 500)
    union all
    (select p.id from public.posts p
      where p_include_closed and p.status = 'closed_delivered'
        and (p.title || ' ' || coalesce(p.description, '')) ilike kc_private.contains_pattern(p_query)
      order by p.published_at desc
      limit 500));
$$;
comment on function kc_access.post_ids_matching_text(text, boolean) is
  'Candidate ids for post search: newest posts containing the text. The caller re-reads them under RLS.';
grant execute on function kc_access.post_ids_matching_text(text, boolean) to authenticated;

-- Up to 500 most followed active members whose display name contains the text
-- (users_display_name_trgm_idx) or whose name or handle has it as a whole word
-- (users_search_gin_idx).
create function kc_access.user_ids_matching_text(p_query text)
returns uuid[]
language sql
stable
security definer
set search_path = ''
as $$
  select array(
    select u.id
      from public.users u
      join public.user_stats s on s.user_id = u.id
     where u.is_active
       and (u.display_name ilike kc_private.contains_pattern(p_query)
            or u.search_vector @@ plainto_tsquery('simple', p_query))
     order by s.followers_count desc, u.id desc
     limit 500);
$$;
comment on function kc_access.user_ids_matching_text(text) is
  'Candidate ids for member search: most followed active members matching the text. The caller re-reads them under RLS.';
grant execute on function kc_access.user_ids_matching_text(text) to authenticated;

-- >>> supabase/schemas/30_social/080_feed_page.sql
-- Social · feed_page (the one feed query path, design §3.4 and §5.1)
--
-- Main feed, world feed and post search are the same query: candidates come straight from
-- partial indexes on `posts`, are ranked in SQL and returned as cards in one round trip.
-- No cache, no queue, no materialized view.
--
-- p_filters (every key optional):
--   sort                  'recommended' (default, D27) | 'newest' | 'oldest' | 'nearest'
--   world                 giving world slug: that world's feed (D5, D36). Without it, the
--                         main feed: worlds flagged shows_in_main_feed, minus muted worlds
--   direction             'offer' | 'request'
--   item_subcategory_ids  array of item subcategory ids
--   status                'open' (default) | 'closed' | 'all'
--   audience              'everyone' (default) | 'following' (D34, S6)
--   city_id, radius_km    posts of that city, or of every city whose centre lies within the
--                         radius of that city's centre (FR-FEED-004 AC1)
--   near_city_id          centre of the 'nearest' sort and of the distance signal;
--                         default the viewer's own city (FR-FEED-006 AC2)
--   q                     text contained in title or description, 2+ characters (FR-FEED-003)
--   scope                 'feed' (default) | 'search': search covers every world and ignores
--                         the viewer's hides and mute filters
--
-- Order and paging. Every sort orders by the same tuple (k1, k2, published_at, id), all
-- descending, and the cursor is that tuple of the last row plus `as_of`, the time of the
-- first page: later pages never see newer posts and time-based signals stay fixed, so
-- pages neither repeat nor skip a post.
--   recommended  k1 = ranking window of the publish time, k2 = score. Newer windows always
--                come first (freshness); inside a window the S33 signals order the posts.
--   newest       k1 = k2 = 0.            oldest   k2 = -publish time.
--   nearest      k2 = -distance in metres between the centre and the post's city
--                (FR-FEED-006 AC1).
-- Candidates of 'recommended' and 'nearest' are read by range (whole windows back in time,
-- a radius around the centre); the range is widened until it holds a full page, and a full
-- range ranks exactly, because everything outside it sorts after everything inside.
--
-- Index use under RLS. The planner pushes only leak-proof conditions into an index scan of
-- a table with row security, so every candidate condition here is an equality or a range
-- on an indexed column. Distance and text are not leak-proof; they are resolved first, to
-- city ids (a radius is a set of cities) and to post ids (075_text_candidates.sql).

-- Followers-only posts of the people the viewer follows: the second candidate stream.
create index posts_feed_followers_only_idx on public.posts (owner_id, published_at desc, id desc)
  where visibility = 'FollowersOnly' and status in ('open', 'closed_delivered');
-- Public delivered posts, newest first: the feed's "closed" and "all" status filters.
create index posts_feed_closed_idx on public.posts (published_at desc, id desc)
  where status = 'closed_delivered' and visibility = 'Public';

create function public.feed_page(
  p_cursor jsonb default null,
  p_limit integer default 20,
  p_filters jsonb default '{}'::jsonb
)
returns table (card public.post_card, next_cursor jsonb, distance_m integer)
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_viewer constant uuid := (select auth.uid());
  v_f constant jsonb := coalesce(p_filters, '{}'::jsonb);
  v_limit constant integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_search constant boolean := coalesce(v_f ->> 'scope', 'feed') = 'search';
  v_status constant text := coalesce(v_f ->> 'status', 'open');
  v_q constant text := btrim(coalesce(v_f ->> 'q', ''));
  v_as_of constant timestamptz := coalesce((p_cursor ->> 'as_of')::timestamptz, now());
  v_c_k1 constant bigint := (p_cursor ->> 'k1')::bigint;
  v_c_k2 constant bigint := (p_cursor ->> 'k2')::bigint;
  v_c_t constant timestamptz := (p_cursor ->> 't')::timestamptz;
  v_c_id constant uuid := (p_cursor ->> 'id')::uuid;
  v_sort text := coalesce(p_cursor ->> 'sort', v_f ->> 'sort', 'recommended');
  v_followed uuid[];
  v_worlds text[];
  v_active_worlds text[];
  v_muted_users uuid[] := '{}';
  v_muted_words text[] := '{}';
  v_origin extensions.geography;
  v_center extensions.geography;
  v_filter_cities text[];
  v_near_cities text[];
  v_match_ids uuid[];
  v_cfg jsonb;
  v_window bigint;
  v_lo timestamptz;
  v_hi timestamptz := 'infinity';
  v_radius double precision := 5000;
  v_span interval;
  v_where text;
  v_branch text;
  v_from text := '';
  v_k1 text := '0';
  v_k2 text := '0';
  v_extra text := '';
  v_sql text;
  v_page jsonb;
begin
  if v_viewer is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;
  if v_sort not in ('recommended', 'newest', 'oldest', 'nearest')
     or v_status not in ('open', 'closed', 'all') then
    raise exception 'invalid_input' using errcode = 'P0001';
  end if;

  -- The viewer's side of the query, read once.
  v_followed := array(select f.followed_id from public.follows f where f.follower_id = v_viewer);
  select c.location into v_origin from public.cities c
   where c.city_id = coalesce(v_f ->> 'near_city_id',
                              (select u.city_id from public.users u where u.id = v_viewer));
  select c.location into v_center from public.cities c where c.city_id = v_f ->> 'city_id';
  if v_sort = 'nearest' and v_origin is null then
    v_sort := 'newest';
  end if;
  if not v_search then
    v_muted_users := array(select m.muted_user_id from public.feed_mute_filters m
                            where m.user_id = v_viewer and m.filter_kind = 'user');
    v_muted_words := array(select m.keyword from public.feed_mute_filters m
                            where m.user_id = v_viewer and m.filter_kind = 'keyword');
  end if;
  v_worlds := case
    when v_f ->> 'world' is not null then array[v_f ->> 'world']
    when v_search then null
    else array(select w.slug from public.worlds w
                where w.shows_in_main_feed
                  and not exists (select 1 from public.feed_mute_filters m
                                   where m.user_id = v_viewer and m.world_slug = w.slug)) end;

  -- Filters, each added only when asked for, so the plan fits the request. Values travel
  -- as parameters ($n below); the text is assembled from the fixed fragments in this
  -- function only.
  v_where := ' and p.published_at <= $1';
  if v_worlds is not null then
    v_where := v_where || ' and p.world_slug = any ($2)';
  end if;
  if not v_search then
    v_where := v_where || ' and not exists (select 1 from public.feed_hides h'
                       || ' where h.user_id = $3 and h.post_id = p.id)';
  end if;
  if v_f ->> 'direction' is not null then
    v_where := v_where || ' and p.direction = $4';
  end if;
  if jsonb_typeof(v_f -> 'item_subcategory_ids') = 'array' then
    v_where := v_where || ' and p.item_subcategory_id = any ($5)';
  end if;
  if v_center is not null and v_f ->> 'radius_km' is not null then
    v_filter_cities := array(
      select c.city_id from public.cities c
       where extensions.st_dwithin(c.location, v_center, (v_f ->> 'radius_km')::double precision * 1000));
    v_where := v_where || ' and p.city_id = any ($6)';
  elsif v_f ->> 'city_id' is not null then
    v_where := v_where || ' and p.city_id = $8';
  end if;
  if char_length(v_q) >= 2 then
    v_match_ids := kc_access.post_ids_matching_text(v_q, v_status <> 'open');
    v_where := v_where || ' and p.id = any ($9)';
  end if;
  if v_f ->> 'audience' = 'following' then
    v_where := v_where || ' and p.owner_id = any ($10)';
  end if;
  if cardinality(v_muted_users) > 0 then
    v_where := v_where || ' and p.owner_id <> all ($11)';
  end if;
  if cardinality(v_muted_words) > 0 then
    v_where := v_where || ' and not exists (select 1 from unnest($12) w (word) where position(w.word'
                       || ' in lower(p.title || '' '' || coalesce(p.description, ''''))) > 0)';
  end if;

  -- Sort-specific parts: the range that bounds the candidates, and the two leading keys.
  if v_sort = 'recommended' then
    select coalesce(jsonb_object_agg(c.config_key, c.value), '{}'::jsonb) into v_cfg
      from public.feed_ranking_config c;
    v_window := (coalesce((v_cfg ->> 'window_hours')::numeric, 24) * 3600)::bigint;
    v_active_worlds := array(select distinct p.world_slug from public.posts p where p.owner_id = v_viewer);
    v_span := make_interval(secs => v_window);
    -- First page: the window holding as_of. Later pages: from the cursor's window down.
    v_lo := to_timestamp(coalesce(v_c_k1, floor(extract(epoch from v_as_of) / v_window)::bigint) * v_window);
    v_hi := to_timestamp((v_c_k1 + 1) * v_window);
    v_where := v_where || ' and p.published_at >= $13 and p.published_at < coalesce($14, ''infinity'')';
    v_k1 := 'floor(extract(epoch from p.published_at) / $16)::bigint';
    v_k2 := 'round(100 * ($17 * (p.owner_id = any ($10))::integer'
         || ' + $18 * (p.world_slug = any ($19))::integer'
         || ' + $20 * coalesce(w.geo_weight / (1 + extensions.st_distance(p.geo_approx, $21) / 25000), 0)'
         || ' + $22 * greatest(coalesce(p.urgency_level, 0) / 3.0,'
         || '                  (p.expires_at <= $1 + interval ''48 hours'')::integer)'
         || ' + $23 * (coalesce(s.comments_count, 0) = 0)::integer))::bigint';
    v_from := ' join public.worlds w on w.slug = p.world_slug'
           || ' left join public.post_stats s on s.post_id = p.id';
  elsif v_sort = 'nearest' then
    v_radius := greatest(v_radius, -coalesce(v_c_k2, 0) + 1);
    v_where := v_where || ' and p.city_id = any ($15)';
    v_k2 := '-floor(extensions.st_distance(pc.location, $21))::bigint';
    v_from := ' join public.cities pc on pc.city_id = p.city_id';
    -- Only rows strictly inside the radius are ranked: a tie group is never split by it.
    v_extra := ' and -c.k2 < $7';
  elsif v_sort = 'newest' then
    if p_cursor is not null then
      v_where := v_where || ' and (p.published_at, p.id) < ($26, $27)';
    end if;
    v_extra := ' order by p.published_at desc, p.id desc limit $28';
  else
    v_k2 := '-(extract(epoch from p.published_at) * 1000000)::bigint';
    if p_cursor is not null then
      v_where := v_where || ' and (p.published_at > $26 or (p.published_at = $26 and p.id < $27))';
    end if;
    v_extra := ' order by p.published_at, p.id desc limit $28';
  end if;

  -- Candidate streams, one per partial index: public open posts, public delivered posts,
  -- and followers-only posts of the viewer and of the people they follow.
  v_branch := '(select p.* from public.posts p where /*audience*/' || v_where
           || case when v_sort in ('newest', 'oldest') then v_extra else '' end || ')';
  v_sql := concat_ws(' union all ',
    case when v_status <> 'closed' then
      replace(v_branch, '/*audience*/', 'p.status = ''open'' and p.visibility = ''Public''') end,
    case when v_status <> 'open' then
      replace(v_branch, '/*audience*/', 'p.status = ''closed_delivered'' and p.visibility = ''Public''') end,
    replace(v_branch, '/*audience*/', 'p.visibility = ''FollowersOnly'' and p.owner_id = any ($10 || $3) and '
      || case v_status when 'open' then 'p.status = ''open'''
                       when 'closed' then 'p.status = ''closed_delivered'''
                       else 'p.status in (''open'', ''closed_delivered'')' end));
  v_sql := 'select coalesce(jsonb_agg(to_jsonb(r)), ''[]''::jsonb) from ('
        || 'select c.id, c.t, c.k1, c.k2 from ('
        || 'select p.id, p.published_at as t, ' || v_k1 || ' as k1, ' || v_k2 || ' as k2'
        || ' from (' || v_sql || ') p' || v_from || ') c'
        || ' where ($27 is null or (c.k1, c.k2, c.t, c.id) < ($24, $25, $26, $27))'
        || case when v_sort = 'nearest' then v_extra else '' end
        || ' order by c.k1 desc, c.k2 desc, c.t desc, c.id desc limit $28) r';

  loop
    if v_sort = 'nearest' then
      v_near_cities := array(select c.city_id from public.cities c
                              where extensions.st_dwithin(c.location, v_origin, v_radius));
    end if;
    execute v_sql into v_page using
      v_as_of, v_worlds, v_viewer, v_f ->> 'direction',                                   -- $1-$4
      array(select jsonb_array_elements_text(v_f -> 'item_subcategory_ids'))::uuid[],     -- $5
      v_filter_cities, v_radius, v_f ->> 'city_id', v_match_ids,                          -- $6-$9
      v_followed, v_muted_users, v_muted_words, v_lo, v_hi, v_near_cities, v_window,      -- $10-$16
      coalesce((v_cfg ->> 'follow_affinity')::numeric, 1),                                -- $17
      coalesce((v_cfg ->> 'active_world')::numeric, 0.5), v_active_worlds,                -- $18-$19
      coalesce((v_cfg ->> 'distance')::numeric, 1), v_origin,                             -- $20-$21
      coalesce((v_cfg ->> 'urgency')::numeric, 0.75),                                     -- $22
      coalesce((v_cfg ->> 'no_response')::numeric, 0.25),                                 -- $23
      v_c_k1, v_c_k2, v_c_t, v_c_id, v_limit;                                             -- $24-$28
    -- A full page is final. Otherwise widen the range fourfold, down to the first post
    -- ever published / out to the whole globe, and rank again.
    exit when jsonb_array_length(v_page) >= v_limit
      or v_sort in ('newest', 'oldest')
      or (v_sort = 'recommended' and v_lo < timestamptz '2020-01-01')
      or (v_sort = 'nearest' and v_radius > 2.1e7);
    v_span := v_span * 4;
    v_lo := v_lo - v_span;
    v_radius := v_radius * 4;
  end loop;

  return query
  select c,
         jsonb_build_object('sort', v_sort, 'as_of', v_as_of, 'k1', r.k1, 'k2', r.k2, 't', r.t, 'id', r.id),
         case when v_sort = 'nearest' then (-r.k2)::integer end
    from jsonb_to_recordset(v_page) as r (id uuid, t timestamptz, k1 bigint, k2 bigint)
    join public.post_cards(array(select (e ->> 'id')::uuid from jsonb_array_elements(v_page) e)) c
      on c.id = r.id
   order by r.k1 desc, r.k2 desc, r.t desc, r.id desc;
end;
$$;
comment on function public.feed_page(jsonb, integer, jsonb) is
  'One page of the main feed, a world feed or post search, as cards, with keyset paging.';
grant execute on function public.feed_page(jsonb, integer, jsonb) to authenticated;

-- >>> supabase/schemas/30_social/090_profile_and_search.sql
-- Social · profile post tabs and search
--
-- The remaining post lists and the member search. All run with the caller's rights, return
-- cards (or member rows) in one round trip and page by keyset.

-- One tab of a profile's posts, newest first (FR-PROFILE-001 AC4, FR-PROFILE-002):
--   open     open posts shown on the profile (never "only me")
--   closed   delivered posts; on one's own profile also posts deleted without a recipient,
--            which can still be reopened
--   hidden   the owner's "only me" posts — RLS returns them to nobody else
-- RLS narrows every tab to what the caller may read of that member. Keyset on
-- (created_at, id), served by posts_owner_recent_idx.
create function public.profile_posts_page(
  p_user_id uuid,
  p_cursor jsonb default null,
  p_limit integer default 20,
  p_tab text default 'open'
)
returns table (card public.post_card, next_cursor jsonb)
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_post_ids uuid[];
begin
  if p_tab is null or p_tab not in ('open', 'closed', 'hidden') then
    raise exception 'invalid_input' using errcode = 'P0001';
  end if;

  v_post_ids := array(
    select p.id
      from public.posts p
     where p.owner_id = p_user_id
       and case p_tab
             when 'open' then p.status = 'open' and p.visibility <> 'OnlyMe'
             when 'closed' then p.status in ('closed_delivered', 'deleted_no_recipient')
                                and p.visibility <> 'OnlyMe'
             else p.status in ('open', 'closed_delivered') and p.visibility = 'OnlyMe' end
       and (p_cursor is null
            or (p.created_at, p.id) < ((p_cursor ->> 't')::timestamptz, (p_cursor ->> 'id')::uuid))
     order by p.created_at desc, p.id desc
     limit least(greatest(coalesce(p_limit, 20), 1), 50));

  return query
  select c, jsonb_build_object('t', c.created_at, 'id', c.id)
    from public.post_cards(v_post_ids) c
   order by c.created_at desc, c.id desc;
end;
$$;
comment on function public.profile_posts_page(uuid, jsonb, integer, text) is
  'One keyset page of a tab of a member''s posts (open, closed, hidden), as cards.';
grant execute on function public.profile_posts_page(uuid, jsonb, integer, text) to authenticated;

-- Post search: posts whose title or description contains the text (FR-FEED-016), newest
-- first unless p_filters names another sort. It is the feed query in search scope, so the
-- filters, the visibility rules and the paging are the feed's. Fewer than two characters
-- return nothing.
create function public.search_posts_page(
  p_query text,
  p_cursor jsonb default null,
  p_limit integer default 20,
  p_filters jsonb default '{}'::jsonb
)
returns table (card public.post_card, next_cursor jsonb, distance_m integer)
language sql
stable
security invoker
set search_path = ''
as $$
  select f.card, f.next_cursor, f.distance_m
    from public.feed_page(
           p_cursor, p_limit,
           '{"sort": "newest"}'::jsonb || coalesce(p_filters, '{}'::jsonb)
             || jsonb_build_object('scope', 'search', 'q', btrim(p_query))) f
   where char_length(btrim(p_query)) >= 2;
$$;
comment on function public.search_posts_page(text, jsonb, integer, jsonb) is
  'One keyset page of posts matching a text, as cards; accepts the feed filters.';
grant execute on function public.search_posts_page(text, jsonb, integer, jsonb) to authenticated;

-- Member search: active members whose display name contains the text or whose name or
-- handle has it as a whole word, most followed first. The matching ids come from the two
-- text indexes on `users` (075_text_candidates.sql) and are read here under RLS. Keyset on
-- (followers_count, id). p_filters: city_id, min_followers.
create function public.search_users_page(
  p_query text,
  p_cursor jsonb default null,
  p_limit integer default 20,
  p_filters jsonb default '{}'::jsonb
)
returns table (
  id uuid,
  share_handle text,
  display_name text,
  avatar_url text,
  city_id text,
  privacy_mode text,
  verification_level smallint,
  followers_count integer,
  viewer_follows boolean,
  next_cursor jsonb
)
language sql
stable
security invoker
set search_path = ''
as $$
  select u.id, u.share_handle, u.display_name, u.avatar_url, u.city_id, u.privacy_mode,
         u.verification_level, s.followers_count,
         exists (select 1 from public.follows f
                  where f.follower_id = (select auth.uid()) and f.followed_id = u.id),
         jsonb_build_object('n', s.followers_count, 'id', u.id)
    from public.users u
    join public.user_stats s on s.user_id = u.id
   where char_length(btrim(p_query)) >= 2
     and u.id = any (kc_access.user_ids_matching_text(btrim(p_query)))
     and (p_filters ->> 'city_id' is null or u.city_id = p_filters ->> 'city_id')
     and s.followers_count >= coalesce((p_filters ->> 'min_followers')::integer, 0)
     and (p_cursor is null
          or (s.followers_count, u.id) < ((p_cursor ->> 'n')::integer, (p_cursor ->> 'id')::uuid))
   order by s.followers_count desc, u.id desc
   limit least(greatest(coalesce(p_limit, 20), 1), 50);
$$;
comment on function public.search_users_page(text, jsonb, integer, jsonb) is
  'One keyset page of active members matching a text, most followed first.';
grant execute on function public.search_users_page(text, jsonb, integer, jsonb) to authenticated;

-- The search screen's first paint: the top posts and the top members for a text in one
-- call (FR-FEED-016 AC2, AC3). Each section is expanded with its own paged function.
create function public.search_all(p_query text, p_limit integer default 5)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select jsonb_build_object(
    'posts', (select coalesce(jsonb_agg(to_jsonb(p)), '[]'::jsonb)
                from public.search_posts_page(p_query, null, least(coalesce(p_limit, 5), 10)) p),
    'users', (select coalesce(jsonb_agg(to_jsonb(u)), '[]'::jsonb)
                from public.search_users_page(p_query, null, least(coalesce(p_limit, 5), 10)) u));
$$;
comment on function public.search_all(text, integer) is
  'Search preview: the first posts and the first members matching a text.';
grant execute on function public.search_all(text, integer) to authenticated;

-- >>> supabase/schemas/30_social/900_storage.sql
-- Social · storage bucket for post images (design §4 "Storage", §5.3)
--
-- The `storage` schema belongs to the Supabase platform. It is absent on a plain PostgreSQL
-- server, where this file does nothing, so the baseline builds everywhere. On a Supabase
-- project it declares the bucket post_media.storage_bucket points at by default, with its
-- size and type limits, and who may write objects in it.
--   read    public: files are served by the CDN under unguessable, immutable names
--   write   a signed-in member, only under the folder named by their own id
--   limits  8 MB per file; JPEG and PNG only (FR-POST-005 AC1, AC2)

do $$
begin
  if to_regclass('storage.buckets') is null or to_regclass('storage.objects') is null then
    return;
  end if;

  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values ('post-images', 'post-images', true, 8388608, array['image/jpeg', 'image/png'])
  on conflict (id) do update
    set public = excluded.public,
        file_size_limit = excluded.file_size_limit,
        allowed_mime_types = excluded.allowed_mime_types;

  -- A member uploads into their own folder only.
  create policy post_images_insert_own_folder on storage.objects
    for insert to authenticated
    with check (bucket_id = 'post-images' and (storage.foldername(name))[1] = (select auth.uid())::text);

  -- A member removes their own files (the account purge and the orphan job use the service role).
  create policy post_images_delete_own_folder on storage.objects
    for delete to authenticated
    using (bucket_id = 'post-images' and (storage.foldername(name))[1] = (select auth.uid())::text);
end $$;

-- >>> supabase/schemas/40_messaging/010_chats.sql
-- Messaging · chats and their members (docs/db/target-design.md §3.5)
--
-- A chat is a conversation; who takes part is a row per member in `chat_members`, which also
-- holds everything that is personal to that member: how far they have read and whether they
-- removed the chat from their own inbox. Two kinds exist today:
--   direct   exactly two members, one chat per pair (D13, D126), optionally pinned to a post
--   support  a member's thread with the support team (FR-CHAT-007); staff join as members
-- A group or organizer chat is one more `kind` with any number of member rows: nothing in
-- this module assumes two members except the columns named `direct_*`.

create table public.chats (
  id              uuid primary key default gen_random_uuid(),
  kind            text not null check (kind in ('direct', 'support')),
  -- The pair of a direct chat, ordered (a < b), so that one unique index guarantees a single
  -- chat per pair whoever opens it first. A member who leaves the product leaves a null:
  -- the other member keeps the thread (FR-CHAT-013) and a new account never inherits it.
  direct_user_a   uuid references public.users (id) on delete set null,
  direct_user_b   uuid references public.users (id) on delete set null,
  -- The member a support thread belongs to.
  support_user_id uuid references public.users (id) on delete set null,
  -- The post the conversation is about right now (D13, FR-CHAT-014). The last entry from a
  -- post wins; closing the post clears it (050_chat_system_messages.sql).
  anchor_post_id  uuid references public.posts (id) on delete set null,
  -- Time of the newest message; null until the first one. Orders the inbox and is the
  -- value a member's read marker advances to.
  last_message_at timestamptz,
  created_at      timestamptz not null default now(),
  constraint chats_direct_pair_chk
    check (kind = 'direct' or (direct_user_a is null and direct_user_b is null)),
  constraint chats_direct_order_chk check (direct_user_a < direct_user_b),
  constraint chats_support_user_chk check (kind = 'support' or support_user_id is null),
  constraint chats_anchor_chk check (kind = 'direct' or anchor_post_id is null)
);
comment on table public.chats is 'Conversations. Membership and per-member state live in chat_members.';

-- One direct chat per pair; also the lookup of open_direct_chat and the foreign key on
-- direct_user_a.
create unique index chats_direct_pair_uidx on public.chats (direct_user_a, direct_user_b)
  where kind = 'direct';
-- Foreign key on direct_user_b (account removal).
create index chats_direct_user_b_idx on public.chats (direct_user_b) where direct_user_b is not null;
-- One support thread per member; also the foreign key on support_user_id.
create unique index chats_support_user_uidx on public.chats (support_user_id) where kind = 'support';
-- Chats pinned to a post: the closing line written when the post closes; also the foreign key.
create index chats_anchor_post_idx on public.chats (anchor_post_id) where anchor_post_id is not null;

create table public.chat_members (
  chat_id      uuid not null references public.chats (id) on delete cascade,
  user_id      uuid not null references public.users (id) on delete cascade,
  -- 'support_agent' marks staff in a support thread.
  role         text not null default 'member' check (role in ('member', 'support_agent')),
  -- Read marker: every message created after it and not sent by the member is unread.
  -- There is no per-message read state (state-machines.md §7 Q3).
  last_read_at timestamptz not null default now(),
  -- Set when the member removed the chat from their own inbox (FR-CHAT-016); cleared by
  -- the next message in the chat or when the member opens the chat again.
  hidden_at    timestamptz,
  joined_at    timestamptz not null default now(),
  primary key (chat_id, user_id)
);
comment on table public.chat_members is
  'Members of a chat with their personal state: read marker and inbox hide.';

-- A member's chats: inbox page and unread counters; also the foreign key on user_id.
create index chat_members_user_idx on public.chat_members (user_id, chat_id);

-- Membership follows the kind of the chat: a direct chat holds only its pair, and the only
-- plain member of a support thread is the member it belongs to.
create function kc_private.chat_members_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_chat public.chats;
begin
  select c.* into v_chat from public.chats c where c.id = new.chat_id;
  if (v_chat.kind = 'direct' and new.user_id not in (v_chat.direct_user_a, v_chat.direct_user_b))
     or (v_chat.kind = 'direct' and new.role <> 'member')
     or (v_chat.kind = 'support'
         and (new.role = 'member') <> (new.user_id is not distinct from v_chat.support_user_id)) then
    raise exception 'chat_member_not_allowed' using errcode = 'P0001';
  end if;
  return new;
end;
$$;
comment on function kc_private.chat_members_guard() is
  'BEFORE INSERT on chat_members: a direct chat admits only its pair; a support thread one plain member.';

create trigger chat_members_guard
  before insert on public.chat_members
  for each row execute function kc_private.chat_members_guard();

-- A chat nobody is a member of any more is removed with its messages: this happens when
-- the last member's account is purged (design §4.1).
create function kc_private.chat_members_remove_empty_chats()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.chats c
   where c.id in (select o.chat_id from old_rows o)
     and not exists (select 1 from public.chat_members cm where cm.chat_id = c.id);
  return null;
end;
$$;
comment on function kc_private.chat_members_remove_empty_chats() is
  'AFTER DELETE on chat_members (per statement): deletes chats left without members.';

create trigger chat_members_remove_empty_chats
  after delete on public.chat_members
  referencing old table as old_rows
  for each statement execute function kc_private.chat_members_remove_empty_chats();

-- True when the caller is a member of the chat and may currently use it. A block between
-- the two members of a direct chat closes it to both, in both directions, for as long as
-- the block exists (D105); lifting the block brings the thread back (FR-CHAT-009 AC2).
-- A support thread is never closed by a block (D33). Definer rights: the predicate reads
-- membership rows and block rows the caller cannot select directly.
create function kc_access.can_access_chat(p_chat_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.chat_members cm
      join public.chats c on c.id = cm.chat_id
     where cm.chat_id = p_chat_id
       and cm.user_id = (select auth.uid())
       and not (c.kind = 'direct' and kc_access.is_blocked_between(c.direct_user_a, c.direct_user_b)));
$$;
comment on function kc_access.can_access_chat(uuid) is
  'Policy predicate: the caller is a member of the chat and no block closes it.';
grant execute on function kc_access.can_access_chat(uuid) to authenticated;

alter table public.chats enable row level security;
alter table public.chats force row level security;
alter table public.chat_members enable row level security;
alter table public.chat_members force row level security;

-- Members read their chats. Nothing is writable from a device: chats are opened, read and
-- hidden through the RPCs of 030_chat_rpcs.sql.
create policy chats_select_member on public.chats
  for select to authenticated
  using (kc_access.can_access_chat(id));

-- Members see who else is in the chat and how far each has read (read receipts,
-- FR-CHAT-002 AC4).
create policy chat_members_select_member on public.chat_members
  for select to authenticated
  using (kc_access.can_access_chat(chat_id));

grant select on public.chats to authenticated;
-- `hidden_at` is left out: whether a member removed the chat from their inbox is not shown
-- to the other member (FR-CHAT-016).
grant select (chat_id, user_id, role, last_read_at, joined_at) on public.chat_members to authenticated;

-- >>> supabase/schemas/40_messaging/020_messages.sql
-- Messaging · messages and reactions
--
-- A message is written once and never changes: there is no edit and no delete from a device
-- (the spec has neither; removal by a moderator arrives with the moderation module). Rows
-- are inserted only by server code — `public.send_message` for members,
-- `kc_private.chat_post_system_message` for the product — so the rules that need a stable
-- error for the app (blocked pair, inactive account, retry of the same message) live in
-- one place and a system message can never be forged.

create table public.messages (
  id              uuid primary key default gen_random_uuid(),
  chat_id         uuid not null references public.chats (id) on delete cascade,
  -- Null for a system message, and for a message whose sender's account was removed: the
  -- other member keeps the text, shown as from a deleted user (FR-CHAT-013, design §4.1).
  sender_id       uuid references public.users (id) on delete set null,
  kind            text not null default 'user',
  body            text,
  -- System message: `{ "kind": "<snake_case>", … }`. The app renders the text from it, so
  -- no user-visible wording is stored here.
  system_payload  jsonb,
  -- Media message: `{ "type": "image" | "video" | "voice" | "location" | "post_share", … }`.
  media_payload   jsonb,
  -- Detected BCP 47 language of the body; written by the translation pipeline.
  source_language text check (char_length(source_language) between 2 and 35),
  -- Assigned by trigger, strictly increasing inside a chat (see messages_stamp below).
  created_at      timestamptz not null default clock_timestamp(),
  -- The one shape rule: what each kind must and must not carry (FR-CHAT-002 AC5: 2,000).
  -- `coalesce` makes a missing value fail the rule instead of leaving it undecided.
  constraint messages_shape_chk check (coalesce(
    case kind
      when 'user' then
        char_length(body) between 1 and 2000 and system_payload is null and media_payload is null
      when 'media' then
        coalesce(char_length(body), 1) between 1 and 2000 and system_payload is null
        and jsonb_typeof(media_payload) = 'object'
        and media_payload ->> 'type' in ('image', 'video', 'voice', 'location', 'post_share')
      when 'system' then
        body is null and media_payload is null and sender_id is null
        and jsonb_typeof(system_payload) = 'object'
        and jsonb_typeof(system_payload -> 'kind') = 'string'
      else false
    end, false))
);
comment on table public.messages is 'Chat messages. Immutable; read state is chat_members.last_read_at.';

-- The one index of the chat screens: a page of a chat (keyset on created_at), the newest
-- message of a chat for the inbox preview, and the unread count
-- (`chat_id = … and created_at > last_read_at`). Unique because the stamp trigger makes
-- created_at strictly increasing inside a chat, which is what lets a single timestamp be
-- the page cursor and the read marker.
create unique index messages_chat_created_uidx on public.messages (chat_id, created_at desc);
-- Foreign key on sender_id (account removal).
create index messages_sender_idx on public.messages (sender_id) where sender_id is not null;

-- Gives the message its time and moves the chat's `last_message_at` to it. The update takes
-- the chat's row lock, so writers of one chat queue up and each gets a time later than the
-- one before it, in commit order. A reader who marks the chat read up to `last_message_at`
-- therefore never skips a message that commits afterwards.
create function kc_private.messages_stamp()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.chats c
     set last_message_at = greatest(clock_timestamp(), c.last_message_at + interval '1 microsecond')
   where c.id = new.chat_id
  returning c.last_message_at into new.created_at;
  return new;
end;
$$;
comment on function kc_private.messages_stamp() is
  'BEFORE INSERT on messages: assigns a per-chat increasing created_at and advances chats.last_message_at.';

create trigger messages_stamp
  before insert on public.messages
  for each row execute function kc_private.messages_stamp();

-- What follows from a new message, of any kind:
--   1. the chat returns to the inbox of every member who had removed it (FR-CHAT-016 AC5)
--   2. one `notification` event per other member (FR-NOTIF-001/002/003, FR-CHAT-003 AC4).
--      A member blocked with the sender gets none. The event carries ids only — the
--      worker reads the preview text when it builds the push — so no message text is ever
--      copied into the queue.
create function kc_private.messages_apply_effects()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_chat public.chats;
  v_to uuid;
begin
  update public.chat_members cm
     set hidden_at = null
   where cm.chat_id = new.chat_id and cm.hidden_at is not null;

  select c.* into v_chat from public.chats c where c.id = new.chat_id;
  for v_to in
    select cm.user_id
      from public.chat_members cm
     where cm.chat_id = new.chat_id
       and cm.user_id is distinct from new.sender_id
       and not kc_access.is_blocked_between(cm.user_id, new.sender_id)
  loop
    perform kc_private.outbox_enqueue('notification', jsonb_build_object(
      'kind', case
                when new.kind = 'system' then 'system_message'
                -- An answer from the support team to the member the thread belongs to.
                when v_chat.kind = 'support' and v_to = v_chat.support_user_id then 'support_message'
                else 'chat_message'
              end,
      'recipient_id', v_to,
      'actor_id', new.sender_id,
      'entity', jsonb_build_object('type', 'chat', 'id', new.chat_id),
      'data', jsonb_build_object('message_id', new.id, 'message_kind', new.kind)));
  end loop;
  return null;
end;
$$;
comment on function kc_private.messages_apply_effects() is
  'AFTER INSERT on messages: un-hides the chat for its members and enqueues their notifications.';

create trigger messages_apply_effects
  after insert on public.messages
  for each row execute function kc_private.messages_apply_effects();

alter table public.messages enable row level security;
alter table public.messages force row level security;

-- Members of the chat read its messages; a block that closes the chat closes them too.
create policy messages_select_member on public.messages
  for select to authenticated
  using (kc_access.can_access_chat(chat_id));

grant select on public.messages to authenticated;

-- ── Reactions ───────────────────────────────────────────────────────────────
-- One reaction per member per message; set and cleared through set_message_reaction.
create table public.message_reactions (
  message_id    uuid not null references public.messages (id) on delete cascade,
  user_id       uuid not null references public.users (id) on delete cascade,
  reaction_type text not null check (reaction_type in ('like', 'love', 'laugh', 'sad')),
  created_at    timestamptz not null default now(),
  primary key (message_id, user_id)
);
comment on table public.message_reactions is 'A member''s reaction to a chat message.';

-- Foreign key on user_id (account removal).
create index message_reactions_user_idx on public.message_reactions (user_id);

alter table public.message_reactions enable row level security;
alter table public.message_reactions force row level security;

-- Visible exactly when the message is: the subquery runs under the caller's own access to
-- `messages`.
create policy message_reactions_select_member on public.message_reactions
  for select to authenticated
  using (exists (select 1 from public.messages m where m.id = message_reactions.message_id));

grant select on public.message_reactions to authenticated;

-- >>> supabase/schemas/40_messaging/030_chat_rpcs.sql
-- Messaging · RPCs that write (open, send, read, hide, react)
--
-- Nothing in this module is writable from a device. Errors are raised with SQLSTATE P0001
-- and a stable snake_case message the app maps to its error types.

-- Opens the caller's conversation with a member: the pair's existing chat, or a new one
-- (FR-CHAT-006, FR-CHAT-017, D13). Two members opening at the same moment get the same
-- chat: the unique index on the pair decides, not a lookup. Entering from a post pins the
-- chat to that post, replacing an earlier pin; entering without one keeps the pin
-- (FR-CHAT-014 AC6). A chat the caller had removed from their inbox comes back.
create function public.open_direct_chat(p_user_id uuid, p_anchor_post_id uuid default null)
returns public.chats
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
  v_chat public.chats;
begin
  if p_user_id is null or p_user_id = v_user_id then
    raise exception 'cannot_chat_self' using errcode = 'P0001';
  end if;
  if not exists (select 1 from public.users u where u.id = p_user_id and u.is_active) then
    raise exception 'user_unavailable' using errcode = 'P0001';
  end if;
  if kc_access.is_blocked_between(v_user_id, p_user_id) then
    raise exception 'blocked_relationship' using errcode = 'P0001';
  end if;
  -- The pin must be an open post of one of the two members (FR-CHAT-005).
  if p_anchor_post_id is not null and not exists (
       select 1 from public.posts p
        where p.id = p_anchor_post_id and p.status = 'open'
          and p.owner_id in (v_user_id, p_user_id)) then
    raise exception 'post_unavailable' using errcode = 'P0001';
  end if;

  insert into public.chats as c (kind, direct_user_a, direct_user_b, anchor_post_id)
  values ('direct', least(v_user_id, p_user_id), greatest(v_user_id, p_user_id), p_anchor_post_id)
  on conflict (direct_user_a, direct_user_b) where kind = 'direct'
  do update set anchor_post_id = coalesce(excluded.anchor_post_id, c.anchor_post_id)
  returning c.* into v_chat;

  insert into public.chat_members (chat_id, user_id)
  values (v_chat.id, v_user_id), (v_chat.id, p_user_id)
  on conflict do nothing;

  update public.chat_members cm
     set hidden_at = null
   where cm.chat_id = v_chat.id and cm.user_id = v_user_id and cm.hidden_at is not null;
  return v_chat;
end;
$$;
comment on function public.open_direct_chat(uuid, uuid) is
  'Returns the caller''s one chat with a member, creating it if needed; optionally pins it to a post.';
grant execute on function public.open_direct_chat(uuid, uuid) to authenticated;

-- Opens the caller's thread with the support team (FR-CHAT-007): one per member, created on
-- first use. Open to every signed-in member whatever their account status, so that a
-- suspended member can still reach support (D33).
create function public.open_support_thread()
returns public.chats
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_chat public.chats;
begin
  insert into public.chats as c (kind, support_user_id)
  values ('support', v_user_id)
  on conflict (support_user_id) where kind = 'support'
  do update set support_user_id = excluded.support_user_id
  returning c.* into v_chat;

  insert into public.chat_members (chat_id, user_id)
  values (v_chat.id, v_user_id)
  on conflict do nothing;
  return v_chat;
end;
$$;
comment on function public.open_support_thread() is 'Returns the caller''s support thread, creating it on first use.';
grant execute on function public.open_support_thread() to authenticated;

-- Sends a message as the caller. A text message has a body; a media message has a payload
-- and an optional caption. `p_message_id` is the id the app gave the message when it
-- showed it optimistically: sending the same id again returns the stored message instead
-- of a second one, so a retry after a lost answer is safe (FR-CHAT-003 AC3).
-- A message to a member whose account is gone or inactive is stored and simply not
-- delivered (FR-CHAT-013 AC2).
create function public.send_message(
  p_chat_id uuid,
  p_body text,
  p_media_payload jsonb default null,
  p_message_id uuid default null
)
returns public.messages
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_body constant text := nullif(btrim(p_body), '');
  v_chat public.chats;
  v_message public.messages;
begin
  select c.* into v_chat
    from public.chats c
    join public.chat_members cm on cm.chat_id = c.id and cm.user_id = v_user_id
   where c.id = p_chat_id;
  if not found then
    raise exception 'chat_not_found' using errcode = 'P0001';
  end if;
  -- Only a support thread is open to a member whose account is not active (D33).
  if v_chat.kind <> 'support' then
    perform kc_private.require_active_caller();
  end if;
  if v_chat.kind = 'direct' and kc_access.is_blocked_between(v_chat.direct_user_a, v_chat.direct_user_b) then
    raise exception 'blocked_relationship' using errcode = 'P0001';
  end if;

  select m.* into v_message
    from public.messages m
   where m.id = p_message_id and m.chat_id = p_chat_id and m.sender_id = v_user_id;
  if found then
    return v_message;
  end if;

  if p_media_payload is null and (v_body is null or char_length(v_body) > 2000) then
    raise exception 'message_body_invalid' using errcode = 'P0001';
  end if;
  if p_media_payload is not null and (
       jsonb_typeof(p_media_payload) <> 'object'
       or coalesce(p_media_payload ->> 'type', '') not in ('image', 'video', 'voice', 'location', 'post_share')
       or char_length(v_body) > 2000) then
    raise exception 'invalid_media_payload' using errcode = 'P0001';
  end if;

  insert into public.messages (id, chat_id, sender_id, kind, body, media_payload)
  values (
    coalesce(p_message_id, gen_random_uuid()), p_chat_id, v_user_id,
    case when p_media_payload is null then 'user' else 'media' end, v_body, p_media_payload)
  returning * into v_message;
  return v_message;
end;
$$;
comment on function public.send_message(uuid, text, jsonb, uuid) is
  'Sends a text or media message to a chat the caller is a member of; idempotent on p_message_id.';
grant execute on function public.send_message(uuid, text, jsonb, uuid) to authenticated;

-- Marks the chat read for the caller: the read marker moves to the newest message, of any
-- kind, in one statement (FR-CHAT-011 AC2, AC4). It never moves backwards.
create function public.mark_chat_read(p_chat_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
begin
  if not kc_access.can_access_chat(p_chat_id) then
    raise exception 'chat_not_found' using errcode = 'P0001';
  end if;
  update public.chat_members cm
     set last_read_at = c.last_message_at
    from public.chats c
   where c.id = cm.chat_id and cm.chat_id = p_chat_id and cm.user_id = v_user_id
     and c.last_message_at > cm.last_read_at;
end;
$$;
comment on function public.mark_chat_read(uuid) is 'Advances the caller''s read marker in a chat to its newest message.';
grant execute on function public.mark_chat_read(uuid) to authenticated;

-- Removes the chat from the caller's own inbox (FR-CHAT-016). The other member is not
-- affected and is not told. The support thread cannot be hidden (AC1).
create function public.hide_chat(p_chat_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_caller();
  v_kind text;
begin
  select c.kind into v_kind
    from public.chats c
    join public.chat_members cm on cm.chat_id = c.id and cm.user_id = v_user_id
   where c.id = p_chat_id;
  if not found then
    raise exception 'chat_not_found' using errcode = 'P0001';
  end if;
  if v_kind = 'support' then
    raise exception 'support_thread_not_hideable' using errcode = 'P0001';
  end if;
  update public.chat_members cm
     set hidden_at = now()
   where cm.chat_id = p_chat_id and cm.user_id = v_user_id and cm.hidden_at is null;
end;
$$;
comment on function public.hide_chat(uuid) is 'Hides a chat from the caller''s inbox until its next message.';
grant execute on function public.hide_chat(uuid) to authenticated;

-- Sets, changes or (with a null type) clears the caller's reaction to a message.
create function public.set_message_reaction(p_message_id uuid, p_reaction_type text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id constant uuid := kc_private.require_active_caller();
begin
  if not exists (select 1 from public.messages m
                  where m.id = p_message_id and kc_access.can_access_chat(m.chat_id)) then
    raise exception 'message_not_found' using errcode = 'P0001';
  end if;
  if p_reaction_type is null then
    delete from public.message_reactions r
     where r.message_id = p_message_id and r.user_id = v_user_id;
    return;
  end if;
  if p_reaction_type not in ('like', 'love', 'laugh', 'sad') then
    raise exception 'invalid_reaction_type' using errcode = 'P0001';
  end if;
  insert into public.message_reactions as r (message_id, user_id, reaction_type)
  values (p_message_id, v_user_id, p_reaction_type)
  on conflict (message_id, user_id) do update set reaction_type = excluded.reaction_type
  where r.reaction_type <> excluded.reaction_type;
end;
$$;
comment on function public.set_message_reaction(uuid, text) is
  'Sets, changes or clears the caller''s reaction to a message of a chat they are in.';
grant execute on function public.set_message_reaction(uuid, text) to authenticated;

-- True when the two members have exchanged at least one message in a direct chat. Used by
-- the handoffs module for the "chat partners only" rule of the recipient picker
-- (FR-CLOSURE-003 AC1).
create function kc_private.members_share_chat(p_user_a uuid, p_user_b uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.chats c
     where c.kind = 'direct'
       and c.direct_user_a = least(p_user_a, p_user_b)
       and c.direct_user_b = greatest(p_user_a, p_user_b)
       and c.last_message_at is not null);
$$;
comment on function kc_private.members_share_chat(uuid, uuid) is
  'The two members have a direct chat with at least one message.';

-- >>> supabase/schemas/40_messaging/040_chat_reads.sql
-- Messaging · RPCs that read (unread counters, inbox page, message page)
--
-- Each screen is one round trip. The functions run with definer rights and apply the access
-- rule once per call (membership of the caller, no closing block) instead of once per row,
-- which is what the row level policies would do for the same query.

-- Unread messages per chat of one member: messages created after the member's read marker
-- and not sent by them, counted on messages_chat_created_uidx. Chats the member removed
-- from their inbox and direct chats closed by a block count nothing (FR-CHAT-012 AC4,
-- FR-CHAT-009 AC1). A chat whose newest message is already read is skipped without
-- touching `messages`.
create function kc_private.chat_unread_counts(p_user_id uuid, p_chat_ids uuid[] default null)
returns table (chat_id uuid, unread_count bigint)
language sql
stable
set search_path = ''
as $$
  select cm.chat_id,
         (select count(*) from public.messages m
           where m.chat_id = cm.chat_id
             and m.created_at > cm.last_read_at
             and m.sender_id is distinct from p_user_id)
    from public.chat_members cm
    join public.chats c on c.id = cm.chat_id
   where cm.user_id = p_user_id
     and cm.hidden_at is null
     and (p_chat_ids is null or cm.chat_id = any (p_chat_ids))
     and c.last_message_at > cm.last_read_at
     and not (c.kind = 'direct' and kc_access.is_blocked_between(c.direct_user_a, c.direct_user_b));
$$;
comment on function kc_private.chat_unread_counts(uuid, uuid[]) is
  'Unread message count of each chat of a member that has any; all chats or the listed ones.';

-- Badge on the chat icon: unread messages across all of the caller's chats (FR-CHAT-012).
create function public.chat_unread_total()
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(sum(n.unread_count), 0)::bigint
    from kc_private.chat_unread_counts(kc_private.require_caller()) n;
$$;
comment on function public.chat_unread_total() is 'Unread messages across the caller''s chats.';
grant execute on function public.chat_unread_total() to authenticated;

-- Unread count of each listed chat; a chat with nothing unread is not returned.
create function public.chat_unread_counts(p_chat_ids uuid[])
returns table (chat_id uuid, unread_count bigint)
language sql
stable
security definer
set search_path = ''
as $$
  select n.chat_id, n.unread_count
    from kc_private.chat_unread_counts(kc_private.require_caller(), p_chat_ids) n
   where n.unread_count > 0;
$$;
comment on function public.chat_unread_counts(uuid[]) is 'Unread messages of each listed chat of the caller.';
grant execute on function public.chat_unread_counts(uuid[]) to authenticated;

-- One page of the caller's inbox, newest conversation first (FR-CHAT-001): the chat, the
-- other member's display fields, a preview of the newest message and the unread count.
-- Keyset on (last_message_at, chat_id): pass the last row's values to get the next page.
-- Left out: chats without a message, chats the caller removed from their inbox, and direct
-- chats closed by a block. The other member's fields are null when their account is gone
-- or not active — the app shows the "deleted user" placeholder — and in the member's own
-- support thread. `p_search` filters by the start of the other member's name (AC3).
-- The page is cut first and only its rows get the preview and the count.
create function public.chat_inbox_page(
  p_limit integer default 30,
  p_before_last_message_at timestamptz default null,
  p_before_chat_id uuid default null,
  p_search text default null
)
returns table (
  chat_id uuid,
  kind text,
  anchor_post_id uuid,
  last_message_at timestamptz,
  counterpart_id uuid,
  counterpart_display_name text,
  counterpart_avatar_url text,
  counterpart_share_handle text,
  -- How far the other member has read: drives the read receipt on the caller's messages.
  counterpart_last_read_at timestamptz,
  last_message_id uuid,
  last_message_kind text,
  last_message_sender_id uuid,
  last_message_preview text,
  unread_count bigint
)
language sql
stable
security definer
set search_path = ''
as $$
  with me as (select kc_private.require_caller() as id),
  page as (
    select c.id, c.kind, c.anchor_post_id, c.last_message_at, cm.last_read_at,
           u.id as counterpart_id, u.display_name, u.avatar_url, u.share_handle
      from me
      join public.chat_members cm on cm.user_id = me.id and cm.hidden_at is null
      join public.chats c on c.id = cm.chat_id
      left join public.users u
        on u.is_active
       and u.id <> me.id
       and u.id in (c.direct_user_a, c.direct_user_b, c.support_user_id)
     where c.last_message_at is not null
       and not (c.kind = 'direct' and kc_access.is_blocked_between(c.direct_user_a, c.direct_user_b))
       and (p_before_last_message_at is null
            or (c.last_message_at, c.id) < (p_before_last_message_at, p_before_chat_id))
       and (nullif(btrim(p_search), '') is null
            or u.display_name ilike
               replace(replace(replace(btrim(p_search), '\', '\\'), '%', '\%'), '_', '\_') || '%')
     order by c.last_message_at desc, c.id desc
     limit least(greatest(coalesce(p_limit, 30), 1), 50))
  select p.id, p.kind, p.anchor_post_id, p.last_message_at,
         p.counterpart_id, p.display_name, p.avatar_url, p.share_handle,
         (select om.last_read_at from public.chat_members om
           where om.chat_id = p.id and om.user_id = p.counterpart_id),
         lm.id, lm.kind, lm.sender_id, left(lm.body, 140),
         (select count(*) from public.messages m
           where m.chat_id = p.id and m.created_at > p.last_read_at
             and m.sender_id is distinct from (select me.id from me))
    from page p
    left join lateral (
      select m.id, m.kind, m.sender_id, m.body
        from public.messages m
       where m.chat_id = p.id
       order by m.created_at desc
       limit 1) lm on true
   order by p.last_message_at desc, p.id desc;
$$;
comment on function public.chat_inbox_page(integer, timestamptz, uuid, text) is
  'One page of the caller''s inbox: chat, other member, newest message preview, unread count.';
grant execute on function public.chat_inbox_page(integer, timestamptz, uuid, text) to authenticated;

-- Messages of a chat the caller is a member of. Without `p_after`: one page going back in
-- time, newest first, starting before `p_before` (the conversation screen). With
-- `p_after`: what arrived after that time, oldest first (catching up after a reconnect).
-- `created_at` is unique inside a chat, so it is the whole cursor.
create function public.chat_messages_page(
  p_chat_id uuid,
  p_limit integer default 50,
  p_before timestamptz default null,
  p_after timestamptz default null
)
returns setof public.messages
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_limit constant integer := least(greatest(coalesce(p_limit, 50), 1), 100);
begin
  perform kc_private.require_caller();
  if not kc_access.can_access_chat(p_chat_id) then
    raise exception 'chat_not_found' using errcode = 'P0001';
  end if;

  if p_after is not null then
    return query
      select m.* from public.messages m
       where m.chat_id = p_chat_id and m.created_at > p_after
       order by m.created_at
       limit v_limit;
  else
    return query
      select m.* from public.messages m
       where m.chat_id = p_chat_id and (p_before is null or m.created_at < p_before)
       order by m.created_at desc
       limit v_limit;
  end if;
end;
$$;
comment on function public.chat_messages_page(uuid, integer, timestamptz, timestamptz) is
  'A page of a chat''s messages for a member: backwards from p_before, or forwards from p_after.';
grant execute on function public.chat_messages_page(uuid, integer, timestamptz, timestamptz) to authenticated;

-- >>> supabase/schemas/40_messaging/050_chat_system_messages.sql
-- Messaging · system messages and the consumer of outbox topic `chat_system_message`
--
-- A system message is a line the product writes into a chat ("the post was delivered").
-- Its `system_payload` names what happened; the app renders the wording.
--
-- Contract of the topic, for every module that emits to it:
--   { "kind": "<snake_case>",            what happened; becomes system_payload.kind
--     "chat_id": "<uuid>"                 write into this one chat, or
--     "post_id": "<uuid>",                write into every chat pinned to this post
--     "data": { … } }                     optional; copied into system_payload as is
-- Exactly one of `chat_id` / `post_id` is given. Member ids never go into `data`: a
-- payload is readable by every member of the chat.
-- Kind `post_closed` (FR-CHAT-015 AC3–AC7, FR-CLOSURE-001 AC4/AC6) also carries `status`
-- and `recipient_id`: each pinned chat is told whether the post went to its own other
-- member, to somebody else, or to nobody — never who — and loses its pin
-- (FR-CHAT-014 AC6).

-- Writes one system message into a chat and returns its id.
create function kc_private.chat_post_system_message(p_chat_id uuid, p_system_payload jsonb)
returns uuid
language sql
security definer
set search_path = ''
as $$
  insert into public.messages (chat_id, kind, system_payload)
  values (p_chat_id, 'system', p_system_payload)
  returning id;
$$;
comment on function kc_private.chat_post_system_message(uuid, jsonb) is
  'Writes a system message into a chat; members are notified like for any message.';

-- Performs one `chat_system_message` event and returns the number of messages written.
-- Safe to run twice for the same event: a `post_id` event clears the pin of every chat it
-- writes to, and a `chat_id` event is recognised by the event id kept in the payload.
create function kc_private.chat_system_messages_deliver(p_event_id bigint)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event kc_private.outbox_events;
  v_payload jsonb;
  v_chat public.chats;
  v_written integer := 0;
begin
  select e.* into v_event
    from kc_private.outbox_events e
   where e.id = p_event_id and e.topic = 'chat_system_message';
  if not found then
    raise exception 'outbox_event_not_found' using errcode = 'P0001';
  end if;
  if jsonb_typeof(v_event.payload -> 'kind') is distinct from 'string'
     or ((v_event.payload ->> 'chat_id') is null) = ((v_event.payload ->> 'post_id') is null) then
    raise exception 'invalid_chat_system_message' using errcode = 'P0001';
  end if;
  v_payload := coalesce(v_event.payload -> 'data', '{}'::jsonb)
    || jsonb_build_object('kind', v_event.payload ->> 'kind', 'event_id', p_event_id);

  for v_chat in
    select c.*
      from public.chats c
     where c.id = (v_event.payload ->> 'chat_id')::uuid
        or c.anchor_post_id = (v_event.payload ->> 'post_id')::uuid
       for update
  loop
    continue when (v_event.payload ->> 'chat_id') is not null and exists (
      select 1 from public.messages m
       where m.chat_id = v_chat.id and m.created_at >= v_event.created_at
         and m.kind = 'system' and m.system_payload -> 'event_id' = to_jsonb(p_event_id));

    perform kc_private.chat_post_system_message(v_chat.id, case v_event.payload ->> 'kind'
      when 'post_closed' then v_payload || jsonb_build_object(
        'post_id', v_event.payload -> 'post_id',
        'status', v_event.payload -> 'status',
        'delivered_to_chat_member', coalesce(
          (v_event.payload ->> 'recipient_id')::uuid in (v_chat.direct_user_a, v_chat.direct_user_b),
          false))
      else v_payload
    end);
    if (v_event.payload ->> 'kind') = 'post_closed' then
      update public.chats c set anchor_post_id = null where c.id = v_chat.id;
    end if;
    v_written := v_written + 1;
  end loop;
  return v_written;
end;
$$;
comment on function kc_private.chat_system_messages_deliver(bigint) is
  'Consumer of outbox topic chat_system_message: writes the system message of one event.';

-- Worker entry point: claims due events of the topic, performs each and confirms it. A
-- failing event is released for a retry with its error and does not stop the batch.
-- Returns the number of events performed. Needs no service outside the database, so it
-- is run by a scheduled job.
create function kc_private.chat_system_messages_process(p_limit integer default 100)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_event_id bigint;
  v_done integer := 0;
begin
  for v_event_id in
    select e.id from kc_private.outbox_claim('chat_system_message', p_limit) e order by e.id
  loop
    begin
      perform kc_private.chat_system_messages_deliver(v_event_id);
      perform kc_private.outbox_complete(v_event_id);
      v_done := v_done + 1;
    exception when others then
      perform kc_private.outbox_complete(v_event_id, sqlerrm);
    end;
  end loop;
  return v_done;
end;
$$;
comment on function kc_private.chat_system_messages_process(integer) is
  'Claims and performs a batch of chat_system_message events; run by a scheduled job.';

-- >>> supabase/schemas/40_messaging/060_realtime.sql
-- Messaging · realtime (docs/db/target-design.md §5 "Realtime", ADR-003)
--
-- Broadcast only: triggers send small events to private topics, and row level security on
-- `realtime.messages` decides who may listen. No table is in a replication publication.
-- All of the module's realtime wiring is in this file. The `realtime` schema belongs to the
-- platform; where it is absent the baseline still applies and the triggers send nothing.
--
-- Topics (registry: docs/SSOT/social_realtime_conventions.md):
--   chat:<chat_id>:messages   INSERT (the message row) · read · reaction · chat_updated
--   chat:<chat_id>:typing     sent by clients (members of the chat)
--   chat:<chat_id>:presence   sent by clients (members of the chat)
--   user:<user_id>:chats      chat_updated — ids only: the member's inbox or badge changed
-- A message body goes only to the chat's own topic, which only members who can read the
-- message under RLS may join.

-- Sends one event to a private topic. Does nothing where the platform function is absent.
create function kc_private.broadcast(p_topic text, p_event text, p_payload jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if to_regproc('realtime.send') is not null then
    perform realtime.send(p_payload, p_event, p_topic, true);
  end if;
end;
$$;
comment on function kc_private.broadcast(text, text, jsonb) is
  'Broadcasts an event to a private realtime topic; a no-op without the realtime schema.';

-- The uuid in the second segment of a topic (`chat:<uuid>:…`, `user:<uuid>:…`); null when
-- the topic has none, so a malformed topic matches no policy instead of raising.
create function kc_access.realtime_topic_uuid(p_topic text)
returns uuid
language sql
immutable
set search_path = ''
as $$
  select case
    when split_part(p_topic, ':', 2) ~* '^[0-9a-f]{8}-([0-9a-f]{4}-){3}[0-9a-f]{12}$'
      then split_part(p_topic, ':', 2)::uuid
  end;
$$;
comment on function kc_access.realtime_topic_uuid(text) is 'Policy helper: the uuid segment of a realtime topic.';
grant execute on function kc_access.realtime_topic_uuid(text) to authenticated;

-- One trigger function for the four tables whose changes members see live.
create function kc_private.chat_broadcast_changes()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_chat_id uuid;
  v_user_id uuid;
begin
  if tg_table_name = 'messages' then
    perform kc_private.broadcast(
      'chat:' || new.chat_id || ':messages', 'INSERT', jsonb_build_object('record', to_jsonb(new)));
    -- Every member's inbox row and badge changed; the event carries no content.
    for v_user_id in select cm.user_id from public.chat_members cm where cm.chat_id = new.chat_id loop
      perform kc_private.broadcast('user:' || v_user_id || ':chats', 'chat_updated',
        jsonb_build_object('chat_id', new.chat_id, 'last_message_at', new.created_at));
    end loop;

  elsif tg_table_name = 'chat_members' then
    -- The other members see the read receipt; the member's other devices see the badge
    -- and the inbox change. Hiding a chat is told to the member alone.
    if new.last_read_at is distinct from old.last_read_at then
      perform kc_private.broadcast('chat:' || new.chat_id || ':messages', 'read',
        jsonb_build_object('user_id', new.user_id, 'last_read_at', new.last_read_at));
    end if;
    perform kc_private.broadcast('user:' || new.user_id || ':chats', 'chat_updated',
      jsonb_build_object('chat_id', new.chat_id));

  elsif tg_table_name = 'message_reactions' then
    select m.chat_id into v_chat_id
      from public.messages m where m.id = coalesce(new.message_id, old.message_id);
    perform kc_private.broadcast('chat:' || v_chat_id || ':messages', 'reaction', jsonb_build_object(
      'message_id', coalesce(new.message_id, old.message_id),
      'user_id', coalesce(new.user_id, old.user_id),
      'reaction_type', case when tg_op <> 'DELETE' then new.reaction_type end));

  else
    -- chats: the pinned post changed (FR-CHAT-014 AC6).
    perform kc_private.broadcast('chat:' || new.id || ':messages', 'chat_updated',
      jsonb_build_object('chat_id', new.id, 'anchor_post_id', new.anchor_post_id));
  end if;
  return null;
end;
$$;
comment on function kc_private.chat_broadcast_changes() is
  'AFTER trigger on messages, chat_members, message_reactions and chats: broadcasts the change.';

create trigger messages_broadcast
  after insert on public.messages
  for each row execute function kc_private.chat_broadcast_changes();

create trigger chat_members_broadcast
  after update of last_read_at, hidden_at on public.chat_members
  for each row
  when (new.last_read_at is distinct from old.last_read_at or new.hidden_at is distinct from old.hidden_at)
  execute function kc_private.chat_broadcast_changes();

create trigger message_reactions_broadcast
  after insert or update or delete on public.message_reactions
  for each row execute function kc_private.chat_broadcast_changes();

create trigger chats_broadcast
  after update of anchor_post_id on public.chats
  for each row
  when (new.anchor_post_id is distinct from old.anchor_post_id)
  execute function kc_private.chat_broadcast_changes();

-- Who may listen and who may send. The policies exist only where the platform table does.
do $$
begin
  if to_regclass('realtime.messages') is null then
    return;
  end if;

  -- Every topic of a chat is open to the members who can currently use that chat.
  execute $policy$
    create policy kc_chat_topics_receive on realtime.messages
      for select to authenticated
      using ((select realtime.topic()) like 'chat:%'
             and kc_access.can_access_chat(kc_access.realtime_topic_uuid((select realtime.topic()))))
  $policy$;

  -- A member's own topics (`user:<their id>:…`): inbox changes here, the notification
  -- badge in the notifications module.
  execute $policy$
    create policy kc_user_topics_receive on realtime.messages
      for select to authenticated
      using ((select realtime.topic()) like 'user:%'
             and kc_access.realtime_topic_uuid((select realtime.topic())) = (select auth.uid()))
  $policy$;

  -- Clients send only typing and presence, and only into chats they can use. Everything
  -- else on a chat topic comes from the triggers above.
  execute $policy$
    create policy kc_chat_topics_send on realtime.messages
      for insert to authenticated
      with check (((select realtime.topic()) like 'chat:%:typing'
                   or (select realtime.topic()) like 'chat:%:presence')
                  and kc_access.can_access_chat(kc_access.realtime_topic_uuid((select realtime.topic()))))
  $policy$;
end $$;

-- >>> supabase/schemas/50_notifications/010_notification_kinds.sql
-- Notifications · registry of notification kinds
--
-- Modules do not send notifications: they record an outbox event on topic `notification`
-- naming a kind, and this registry says what that kind is. The rows are vocabulary, like
-- the edges of a state machine: one per kind the product can emit. A later module adds the
-- rows of its own kinds next to the code that emits them.
--
-- Event payload (kc_private.outbox_enqueue('notification', …)):
--   { "kind": "<kind>", "recipient_id": "<uuid>", "actor_id": "<uuid|null>",
--     "entity": { "type": "<text>", "id": "<uuid>" },
--     "data": { …, "dedupe_key": "<text, optional>" } }
-- `data.dedupe_key`: a recipient gets at most one notification per key (FR-NOTIF-018 AC5).
-- `data` is stored on the notification as the arguments of its text, without the key.

create table kc_private.notification_kinds (
  kind               text primary key check (kind ~ '^[a-z][a-z0-9_]{1,62}$'),
  -- The two groups a member can switch off as a whole (FR-NOTIF-014, D5). `critical` is
  -- the group the project book calls "important" (spec 07 §7.11).
  category           text not null check (category in ('critical', 'social')),
  -- Whether the kind is on for a member who never touched its own switch (FR-NOTIF-017).
  default_enabled    boolean not null default true,
  -- Account and safety notices: delivered whatever the member switched off, also to a
  -- member whose account is not active and across a block.
  bypass_preferences boolean not null default false,
  -- Time-critical kinds are pushed during the member's quiet hours as well (D95).
  bypass_quiet_hours boolean not null default false,
  -- False = shown in the notification centre only, never pushed (S10: social).
  sends_push         boolean not null default true,
  -- Events of this kind about the same entity merge into one unread notification while
  -- they arrive within this time of each other ("X and 3 others"); null = never merged.
  group_window       interval check (group_window > interval '0'),
  -- Keys of the texts in the app's locale files; the database stores no wording.
  title_key          text not null,
  body_key           text not null
);
comment on table kc_private.notification_kinds is
  'Vocabulary of notification kinds: category, preference rules, channels, grouping, text keys.';

alter table kc_private.notification_kinds enable row level security;
alter table kc_private.notification_kinds force row level security;

-- Messaging, follows, the recipient mark and the kinds of spec requirements/09 that no
-- module emits yet (post_expiring, message_undeliverable, auto_removed, account_suspended,
-- match_suggested).
insert into kc_private.notification_kinds
  (kind, category, bypass_preferences, sends_push, group_window, title_key, body_key)
values
  -- FR-NOTIF-001/002: messages of one chat merge while unread (S10: per entity per hour).
  ('chat_message', 'critical', false, true, interval '1 hour', 'notifications.chatTitle', 'notifications.chatBody'),
  ('support_message', 'critical', false, true, interval '1 hour', 'notifications.supportTitle', 'notifications.chatBody'),
  -- FR-NOTIF-003.
  ('system_message', 'critical', false, true, null, 'notifications.systemTitle', 'notifications.systemBody'),
  -- FR-NOTIF-004.
  ('message_undeliverable', 'critical', false, true, null,
   'notifications.messageUndeliverableTitle', 'notifications.messageUndeliverableBody'),
  -- FR-NOTIF-005.
  ('post_expiring', 'critical', false, true, null, 'notifications.postExpiringTitle', 'notifications.postExpiringBody'),
  -- FR-NOTIF-006/007/008. New followers merge within the hour (FR-NOTIF-007 AC3).
  ('follow_request', 'social', false, false, null, 'notifications.followRequestTitle', 'notifications.followRequestBody'),
  ('follow_started', 'social', false, false, interval '1 hour', 'notifications.followStartedTitle', 'notifications.followStartedBody'),
  ('follow_approved', 'social', false, false, null, 'notifications.followApprovedTitle', 'notifications.followApprovedBody'),
  -- FR-NOTIF-009/010.
  ('mark_recipient', 'critical', false, true, null, 'notifications.markRecipientTitle', 'notifications.markRecipientBody'),
  ('unmark_recipient', 'critical', false, true, null, 'notifications.unmarkRecipientTitle', 'notifications.unmarkRecipientBody'),
  -- FR-NOTIF-011 and the suspension notice: the member has a right to know.
  ('auto_removed', 'critical', true, true, null, 'notifications.autoRemovedTitle', 'notifications.autoRemovedBody'),
  ('account_suspended', 'critical', true, true, null, 'notifications.accountSuspendedTitle', 'notifications.accountSuspendedBody'),
  -- FR-NOTIF-017.
  ('match_suggested', 'critical', false, true, null, 'notifications.matchSuggestedTitle', 'notifications.matchSuggestedBody');

-- Handoff changes (FR-NOTIF-018, D73, D131, D138): one kind per machine and change, named
-- `<machine>_<change>` by kc_private.handoff_notification_kind. All are critical; ride
-- bookings are also pushed during quiet hours (D95). Text keys are the kind in camelCase.
insert into kc_private.notification_kinds (kind, category, bypass_quiet_hours, title_key, body_key)
select k.kind, 'critical', m.machine = 'ride_booking',
       'notifications.' || k.camel || 'Title', 'notifications.' || k.camel || 'Body'
  from unnest(array['giving_handoff', 'ride_booking', 'housing_booking', 'event_registration']) as m (machine)
 cross join unnest(array[
         'requested', 'claimed', 'confirmed', 'declined', 'cancelled', 'expired', 'completed',
         'no_show', 'waitlist_promoted', 'reinstated']) as c (change)
 cross join lateral (
   select m.machine || '_' || c.change as kind,
          split_part(m.machine, '_', 1)
            || replace(initcap(replace(split_part(m.machine, '_', 2) || '_' || c.change, '_', ' ')), ' ', '')
            as camel) k;

